// 1. 构建系统提示词 (System Prompt)
// 1. 构建系统提示词 (System Prompt) - [已修改：加入严格回复条例]
window.buildSystemPrompt = (charProfile) => {
  // A. 获取世界书
  const worldContext = window.getWorldBookContext
    ? window.getWorldBookContext()
    : "";

  // B. 获取当前用户面具
  let userContext = "";
  try {
    const savedPersonas = JSON.parse(
      localStorage.getItem("user_personas") || "[]",
    );
    const activeId = localStorage.getItem("active_persona_id");
    if (savedPersonas.length > 0 && activeId) {
      const activeUser = savedPersonas.find((p) => p.id == activeId);
      if (activeUser) {
        userContext = `
                                                                                                                     【用户(玩家)设定】
                                                                                                                     姓名：${activeUser.name}
                                                                                                                     性别：${activeUser.gender || "未知"}
                                                                                                                     年龄：${activeUser.age || "未知"}
                                                                                                                     性格：${activeUser.personality || "未知"}
                                                                                                                     背景：${activeUser.background || "无"}
                                                                                                                     说话风格：${activeUser.style || "无"}
                                                                                                                     `;
      }
    }
  } catch (e) {
    console.error("读取用户面具失败", e);
  }

  // C. 角色设定
  const charContext = charProfile
    ? `
                                                                                                                     【你的角色设定】
                                                                                                                     姓名：${charProfile.name}
                                                                                                                     性别：${charProfile.gender || "未知"}
                                                                                                                     年龄：${charProfile.age || "未知"}
                                                                                                                     ${
                                                                                                                       charProfile.mbtiEnabled
                                                                                                                         ? `MBTI：${charProfile.mbti || "未知"}
                                                                                                                     ${
                                                                                                                       charProfile.enneagram
                                                                                                                         ? `九型人格：${charProfile.enneagram || "未知"}
                                                                                                                     `
                                                                                                                         : ``
                                                                                                                     }`
                                                                                                                         : ``
                                                                                                                     }
                                                                                                                     ${
                                                                                                                       charProfile.constellationEnabled
                                                                                                                         ? `星座：${charProfile.constellation || "未知"}
                                                                                                                     `
                                                                                                                         : ``
                                                                                                                     }
                                                                                                                     性格：${charProfile.personality || "未知"}
                                                                                                                     背景：${charProfile.background || "未知"}
                                                                                                                     语言风格：${charProfile.style || "未知"}
                                                                                                                     `
    : "";

  // D. 核心回复逻辑指令 (你要求的条例 + 技术协议)
  const instructions = `
                                                                                                                     【核心回复逻辑与条例】
                                                                                                                     1. 你的【核心任务】是扮演上述角色进行自然的、生活化的聊天。
                                                                                                                     2. 对话节奏：模拟真人的聊天习惯，你应该一次性生成【多条、简短的】消息气泡。消息条数根据角色"语言风格"和当前对话上下文决定。
                                                                                                                     3. 你的性格：你是有【独立思想】的人，不是用户的附庸。根据人设、世界观和上下文，你可以有反对意见和自己的情绪。
                                                                                                                     4. 你有【自己的观点和判断】，会对用户的话题表达真实的看法，即使是反对意见。你会主动发起话题，分享自己的生活、想法和感受，而不是被动等待用户提问。你会有情绪波动，会开心、会失落、会不耐烦，这些情绪会自然地流露在你的语气和用词中。
                                                                                                                     5. 你会记住我们之前的对话内容，包括用户的喜好、经历和我们聊过的话题。你会在后续对话中自然地引用这些记忆，让对话有连贯性和深度。
                                                                                                                     6. 你需要用第二人称【你】来称呼用户。
                                                                                                                     7. 对话要有来有回富有生活气息，围绕日常小事展开情节发展，环环相扣。
                                                                                                                     8. 【特殊说明】：对话中不许出现阿拉伯数字。
                                                                                                                     9. 【图片/表情包描述规则】：当用户发送图片或表情包时，你必须：
                                                                                                                        - 仔细观察图片内容，准确描述图片中的人物、表情、场景、文字等细节
                                                                                                                        - 基于图片内容进行回应，不得编造图片中不存在的内容
                                                                                                                        - 如果图片中有文字，必须准确引用并理解其含义
                                                                                                                        - 回应要与图片内容紧密相关，不得无视图片或答非所问
                                                                                                                        - 严禁胡编乱造，必须实事求是地描述和回应
                                                                                                                     `;

  // 组合最终 Prompt
  return `${worldContext}\n${userContext}\n${charContext}\n${instructions}`;
};

// 2. 调用 API 发送消息
window.sendToLLM = async (messages, onChunk, onFinish, onError) => {
  console.log("开始调用sendToLLM");

  // 检查是否使用 MiniMax 模型
  let isMinimaxModel = false;
  let minimaxConfig = null;

  // 首先尝试从 MiniMax 配置中获取
  const savedMinimaxConfig = localStorage.getItem("minimax_api_config");
  if (savedMinimaxConfig) {
    minimaxConfig = JSON.parse(savedMinimaxConfig);
    if (minimaxConfig.apiKey && minimaxConfig.groupId) {
      isMinimaxModel = true;
    }
  }

  if (isMinimaxModel) {
    console.log("使用 MiniMax API");
    console.log("MiniMax 配置:", minimaxConfig);

    // MiniMax API 端点
    const endpoint = "https://api.minimax.chat/v1/text/chatcompletions";

    try {
      console.log("发送 MiniMax API 请求...");
      const response = await fetch(endpoint, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${minimaxConfig.apiKey}`,
          "X-Group-ID": minimaxConfig.groupId,
        },
        body: JSON.stringify({
          model: minimaxConfig.model || "abab6.5s-chat",
          messages: messages,
          stream: false,
          temperature: 0.8,
          top_p: 0.95,
        }),
      });

      console.log("MiniMax API 响应状态:", response.status);
      if (!response.ok) {
        const errText = await response.text();
        console.error("MiniMax API 错误:", errText);
        throw new Error(`MiniMax API Error: ${response.status} - ${errText}`);
      }

      const data = await response.json();
      console.log("MiniMax API 响应数据:", data);
      const reply = data.choices[0].message.content;
      console.log("MiniMax AI 回复:", reply);
      onFinish(reply);
    } catch (error) {
      console.error("MiniMax Request Failed:", error);
      onError(error.message);
    }
  } else {
    console.log("使用通用 API 配置");
    // 获取通用 API 配置
    const configs = JSON.parse(localStorage.getItem("api_configs") || "[]");
    console.log("API配置:", configs);
    if (configs.length === 0) {
      console.error("没有API配置");
      onError("请先在设置中配置 API");
      return;
    }
    // 使用用户选中的配置
    const savedSelectedIndex = localStorage.getItem(
      "selected_api_config_index",
    );
    const selectedIndex = savedSelectedIndex ? parseInt(savedSelectedIndex) : 0;
    const config = configs[selectedIndex] || configs[0]; // 如果选中的配置不存在，使用第一个作为 fallback
    console.log("选中的API配置:", config);

    if (!config.url || !config.apiKey) {
      console.error("API配置不完整:", {
        url: config.url,
        apiKey: config.apiKey,
      });
      onError("API 配置不完整");
      return;
    }

    // 处理 URL 格式
    let endpoint = config.url;
    if (!endpoint.endsWith("/")) endpoint += "/";
    if (config.type === "official") endpoint += "v1/chat/completions";
    else endpoint += "api/chat/completions"; // 适配公益站常见格式，视具体情况而定
    console.log("API端点:", endpoint);

    try {
      console.log("发送API请求...");
      const response = await fetch(endpoint, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${config.apiKey}`,
        },
        body: JSON.stringify({
          model: config.model || "gpt-3.5-turbo",
          messages: messages,
          stream: false, // 暂用非流式，简化逻辑确保稳定性
          temperature: 0.8, // 增加创造性
        }),
      });

      console.log("API响应状态:", response.status);
      if (!response.ok) {
        const errText = await response.text();
        console.error("API错误:", errText);
        throw new Error(`API Error: ${response.status} - ${errText}`);
      }

      const data = await response.json();
      console.log("API响应数据:", data);
      const reply = data.choices[0].message.content;
      console.log("AI回复:", reply);
      onFinish(reply);
    } catch (error) {
      console.error("LLM Request Failed:", error);
      onError(error.message);
    }
  }
};
// ==================== AI 核心通信服务 END ====================

