  const [userPersonas, setUserPersonas] = React.useState([]);
  const [userRoles, setUserRoles] = React.useState([]);
  const [worldBooks, setWorldBooks] = React.useState([]);
  // 加载状态
  const [loading, setLoading] = React.useState(true);
  // 表单状态
  const [formData, setFormData] = React.useState({
    identity: "",
    roles: [],
    worldBooks: [],
    description: "",
  });
  // 保存的区域数据
  const [savedAreas, setSavedAreas] = React.useState([]);
  // 显示保存的区域详情
  const [showSavedAreas, setShowSavedAreas] = React.useState(false);
  // 当前选中的区域
  const [currentSelectedArea, setCurrentSelectedArea] = React.useState(null);

  // 表单输入处理函数
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  // 处理多选角色
  const handleRoleChange = (roleId) => {
    setFormData((prev) => {
      const currentRoles = prev.roles;
      if (currentRoles.includes(roleId)) {
        return {
          ...prev,
          roles: currentRoles.filter((id) => id !== roleId),
        };
      } else {
        return {
          ...prev,
          roles: [...currentRoles, roleId],
        };
      }
    });
  };

  // 处理多选世界书
  const handleWorldBookChange = (bookId) => {
    setFormData((prev) => {
      const currentBooks = prev.worldBooks;
      if (currentBooks.includes(bookId)) {
        return {
          ...prev,
          worldBooks: currentBooks.filter((id) => id !== bookId),
        };
      } else {
        return {
          ...prev,
          worldBooks: [...currentBooks, bookId],
        };
      }
    });
  };

  // 光斑点击事件处理函数
  const handleOrbClick = (orb) => {
    // 重置表单状态
    setFormData({
      identity: "",
      roles: [],
      worldBooks: [],
      description: "",
    });
    setSelectedOrb(orb);
    setShowModal(true);
  };

  // 关闭弹窗
  const handleCloseModal = () => {
    setShowModal(false);
    setSelectedOrb(null);
  };

  // 保存弹窗内容
  const handleSave = () => {
    // 这里可以添加保存逻辑
    console.log("保存", {
      orb: selectedOrb,
      formData: formData,
    });

    // 创建保存的数据对象
    const savedArea = {
      id: selectedOrb.id,
      name: selectedOrb.name,
      color: selectedOrb.color,
      formData: formData,
      timestamp: new Date().toISOString(),
    };

    // 保存到状态
    setSavedAreas((prev) => {
      // 检查是否已存在该区域的数据
      const existingIndex = prev.findIndex(
        (area) => area.id === selectedOrb.id,
      );
      if (existingIndex >= 0) {
        // 更新已有数据
        const updated = [...prev];
        updated[existingIndex] = savedArea;
        return updated;
      } else {
        // 添加新数据
        return [...prev, savedArea];
      }
    });

    // 保存到 IndexedDB
    const saveAreaData = async () => {
      try {
        const areaStore = window.areaStore;
        if (areaStore) {
          try {
            const updatedAreas = [...savedAreas, savedArea];
            await areaStore.saveAreas(updatedAreas);
            console.log("区域数据保存到IndexedDB成功");
          } catch (e) {
            console.error("保存区域数据到IndexedDB失败:", e);
          }
        }
      } catch (e) {
        console.error("保存区域数据失败:", e);
      }
    };

    saveAreaData();

    // 更新当前选中的区域
    setCurrentSelectedArea(savedArea);

    // 显示保存成功提示
    alert("保存成功！");

    setShowModal(false);
    setSelectedOrb(null);
  };

  // 删除区域
  const handleDelete = () => {
    // 删除保存的区域数据
    setSavedAreas((prev) => prev.filter((area) => area.id !== selectedOrb.id));
    // 从 IndexedDB 中删除
    const deleteAreaData = async () => {
      try {
        const areaStore = window.areaStore;
        if (areaStore) {
          try {
            const updatedAreas = savedAreas.filter(
              (area) => area.id !== selectedOrb.id,
            );
            await areaStore.saveAreas(updatedAreas);
            console.log("区域数据从IndexedDB删除成功");
          } catch (e) {
            console.error("从IndexedDB删除区域数据失败:", e);
          }
        }
      } catch (e) {
        console.error("删除区域数据失败:", e);
      }
    };

    deleteAreaData();
    console.log("删除", selectedOrb);
    setShowModal(false);
    setSelectedOrb(null);
  };

  // 核心球体点击事件
  const handleCoreSphereClick = () => {
    setShowSavedAreas(!showSavedAreas);
  };

  // 修改保存的区域
  const handleEditArea = (area) => {
    // 关闭保存的区域详情
    setShowSavedAreas(false);
    // 找到对应的光斑
    const orb = orbs.find((o) => o.id === area.id);
    if (orb) {
      // 设置表单数据
      setFormData(area.formData);
      setSelectedOrb(orb);
      setShowModal(true);
    }
  };

  // 删除保存的区域
  const handleDeleteArea = (areaId) => {
    if (confirm("确定要删除这个保存的区域吗？")) {
      // 删除保存的区域数据
      setSavedAreas((prev) => prev.filter((area) => area.id !== areaId));
      // 从 IndexedDB 中删除
      const deleteAreaData = async () => {
        try {
          const areaStore = window.areaStore;
          if (areaStore) {
            try {
              const updatedAreas = savedAreas.filter(
                (area) => area.id !== areaId,
              );
              await areaStore.saveAreas(updatedAreas);
              console.log("区域数据从IndexedDB删除成功");
              // 清除localStorage中的旧数据
              localStorage.removeItem("saved_areas");
            } catch (e) {
              console.error("从IndexedDB删除区域数据失败:", e);
              // 失败时尝试从localStorage删除作为后备
              try {
                const updatedAreas = savedAreas.filter(
                  (area) => area.id !== areaId,
                );
                localStorage.setItem(
                  "saved_areas",
                  JSON.stringify(updatedAreas),
                );
                console.log("从localStorage删除区域数据作为后备");
              } catch (e) {
                console.error("删除区域数据失败:", e);
              }
            }
          } else {
            // 没有areaStore，从localStorage删除
            try {
              const updatedAreas = savedAreas.filter(
                (area) => area.id !== areaId,
              );
              localStorage.setItem("saved_areas", JSON.stringify(updatedAreas));
              console.log("从localStorage删除区域数据");
            } catch (e) {
              console.error("删除区域数据失败:", e);
            }
          }
        } catch (e) {
          console.error("删除区域数据失败:", e);
        }
      };

      deleteAreaData();
    }
  };

  // 进入区域详情页
