// T11 底部列表 (公告)
const T11FooterList = ({ notices }) => {
  // 从所有公告中随机选择三条
  const getRandomNotices = () => {
    if (!notices || notices.length === 0) {
      return [];
    }

    // 收集所有公告
    const allNotices = [];
    notices.forEach((tabNotices) => {
      if (Array.isArray(tabNotices)) {
        allNotices.push(...tabNotices);
      }
    });

    // 随机排序并选择前三条
    return [...allNotices].sort(() => 0.5 - Math.random()).slice(0, 3);
  };

  const randomNotices = getRandomNotices();

  return (
    <div className="fade-in">
      <div className="t11-list-section-title">
        <span>最新公告</span>
        <i
          className="ph ph-caret-right"
          style={{ fontSize: "14px", color: "#ccc" }}
        ></i>
      </div>
      {randomNotices.length > 0
        ? randomNotices.map((notice, index) => (
            <div
              key={notice.id || index}
              className="t11-simple-list-item click-effect"
            >
              <div
                style={{
                  width: "36px",
                  height: "36px",
                  background: "#F2F4F7",
                  borderRadius: "10px",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  marginRight: "12px",
                  flexShrink: 0,
                }}
              >
                <i
                  className="ph ph-file-text"
                  style={{ color: "#8FA4B5", fontSize: "18px" }}
                ></i>
              </div>
              <div style={{ flex: 1, overflow: "hidden" }}>
                <div
                  style={{
                    fontSize: "14px",
                    color: "#4A4F55",
                    fontWeight: "500",
                    marginBottom: "4px",
                    whiteSpace: "nowrap",
                    overflow: "hidden",
                    textOverflow: "ellipsis",
                  }}
                >
                  {notice.title}
                </div>
                <div style={{ fontSize: "12px", color: "#9DA3AE" }}>
                  更新于 {notice.time}
                </div>
              </div>
            </div>
          ))
        : // 当没有公告数据时显示默认内容
          [1, 2, 3].map((i) => (
            <div key={i} className="t11-simple-list-item click-effect">
              <div
                style={{
                  width: "36px",
                  height: "36px",
                  background: "#F2F4F7",
                  borderRadius: "10px",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  marginRight: "12px",
                  flexShrink: 0,
                }}
              >
                <i
                  className="ph ph-file-text"
                  style={{ color: "#8FA4B5", fontSize: "18px" }}
                ></i>
              </div>
              <div style={{ flex: 1, overflow: "hidden" }}>
                <div
                  style={{
                    fontSize: "14px",
                    color: "#4A4F55",
                    fontWeight: "500",
                    marginBottom: "4px",
                    whiteSpace: "nowrap",
                    overflow: "hidden",
                    textOverflow: "ellipsis",
                  }}
                >
                  关于各部考勤和请假的暂行规定 {i}
                </div>
                <div style={{ fontSize: "12px", color: "#9DA3AE" }}>
                  更新于 10:00 AM
                </div>
              </div>
            </div>
          ))}
    </div>
  );
};

