// 可爱的地鼠组件
const CuteMole = ({ themeIdx, hit }) => {
  const theme = MOLE_THEMES[themeIdx];
  return (
    <div
      style={{
        position: "absolute",
        bottom: "-5%",
        left: "10%",
        width: "80%",
        height: "90%",
        animation: hit ? "none" : "molePop 0.7s ease-out",
        transformOrigin: "bottom center",
        cursor: "pointer", // 增加点击手型
      }}
    >
      <svg
        viewBox="0 0 100 100"
        width="100%"
        height="100%"
        style={{ overflow: "visible" }}
      >
        {/* 身体 */}
        <path
          d="M15,100 C15,40 25,10 50,10 C75,10 85,40 85,100 Z"
          fill={theme.body}
        />
        {/* 肚皮 */}
        <ellipse
          cx="50"
          cy="80"
          rx="20"
          ry="18"
          fill={theme.belly}
          opacity="0.8"
        />

        {/* 耳朵 */}
        <circle cx="25" cy="20" r="8" fill={theme.body} />
        <circle cx="25" cy="20" r="4" fill={theme.belly} />
        <circle cx="75" cy="20" r="8" fill={theme.body} />
        <circle cx="75" cy="20" r="4" fill={theme.belly} />

        {/* 眼睛 (大眼睛更可爱) */}
        {hit ? (
          // 被击中的眼睛
          <>
            <circle cx="35" cy="45" r="5" fill="#333" />
            <path
              d="M32,43 L38,47"
              stroke="white"
              strokeWidth="2"
              strokeLinecap="round"
            />
            <path
              d="M38,43 L32,47"
              stroke="white"
              strokeWidth="2"
              strokeLinecap="round"
            />
            <circle cx="65" cy="45" r="5" fill="#333" />
            <path
              d="M62,43 L68,47"
              stroke="white"
              strokeWidth="2"
              strokeLinecap="round"
            />
            <path
              d="M68,43 L62,47"
              stroke="white"
              strokeWidth="2"
              strokeLinecap="round"
            />
          </>
        ) : (
          // 正常眼睛
          <>
            <circle cx="35" cy="45" r="5" fill="#333" />
            <circle cx="37" cy="43" r="1.5" fill="white" /> {/* 眼神光 */}
            <circle cx="65" cy="45" r="5" fill="#333" />
            <circle cx="67" cy="43" r="1.5" fill="white" />
          </>
        )}
        {/* 腮红 */}
        <ellipse
          cx="25"
          cy="55"
          rx="6"
          ry="3"
          fill={theme.blush}
          opacity="0.6"
        />
        <ellipse
          cx="75"
          cy="55"
          rx="6"
          ry="3"
          fill={theme.blush}
          opacity="0.6"
        />

        {/* 鼻子和嘴巴 */}
        <ellipse cx="50" cy="52" rx="6" ry="4" fill="#5a4d4d" />
        {hit ? (
          // 被击中的嘴巴
          <path
            d="M45,60 Q50,55 55,60"
            fill="none"
            stroke="#5a4d4d"
            strokeWidth="2"
            strokeLinecap="round"
          />
        ) : (
          // 正常嘴巴
          <path
            d="M45,60 Q50,65 55,60"
            fill="none"
            stroke="#5a4d4d"
            strokeWidth="2"
            strokeLinecap="round"
          />
        )}
      </svg>
    </div>
  );
};

// 精致的气锤组件
const FancyHammer = ({ x, y, state }) => {
  // 旋转角度：未点击 20度，点击 -40度
  const rotation = state === "down" ? -45 : 20;

  return (
    <div
      style={{
        position: "absolute",
        top: y,
        left: x,
        width: "120px",
        height: "120px",
        pointerEvents: "none",
        zIndex: 50,
        transform: `translate(-30%, -60%) rotate(${rotation}deg)`, // 调整中心点以便锤头对准鼠标
        transformOrigin: "bottom right",
        transition: "transform 0.1s cubic-bezier(0.175, 0.885, 0.32, 1.275)",
      }}
    >
      <svg
        viewBox="0 0 100 100"
        width="100%"
        height="100%"
        style={{
          overflow: "visible",
          filter: "drop-shadow(2px 4px 6px rgba(0,0,0,0.2))",
        }}
      >
        {/* 锤头主体 (圆柱形) */}
        <defs>
          <linearGradient id="headGrad" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#FFD93D" />
            <stop offset="100%" stopColor="#F4C724" />
          </linearGradient>
          <linearGradient id="handleGrad" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="#EEE" />
            <stop offset="100%" stopColor="#CCC" />
          </linearGradient>
          <radialGradient id="sideGrad">
            <stop offset="80%" stopColor="#FF6B6B" />
            <stop offset="100%" stopColor="#E05555" />
          </radialGradient>
        </defs>

        {/* 锤头中间 */}
        <rect
          x="20"
          y="20"
          width="60"
          height="40"
          rx="10"
          fill="url(#headGrad)"
        />
        {/* 锤头高光条纹 */}
        <path
          d="M35,25 L35,55"
          stroke="rgba(255,255,255,0.4)"
          strokeWidth="4"
          strokeLinecap="round"
        />
        <path
          d="M45,25 L45,55"
          stroke="rgba(255,255,255,0.4)"
          strokeWidth="4"
          strokeLinecap="round"
        />

        {/* 锤头两端 (打击面) */}
        <ellipse cx="20" cy="40" rx="8" ry="18" fill="url(#sideGrad)" />
        <ellipse cx="80" cy="40" rx="8" ry="18" fill="url(#sideGrad)" />

        {/* 装饰星星 */}
        <path
          d="M50,35 L52,40 L57,40 L53,43 L55,48 L50,45 L45,48 L47,43 L43,40 L48,40 Z"
          fill="#FFF"
          opacity="0.8"
        />

        {/* 手柄 - 移到锤头中间 */}
        <rect
          x="50"
          y="40"
          width="12"
          height="60"
          rx="6"
          fill="url(#handleGrad)"
          transform="rotate(-15 56 70)"
        />
      </svg>
    </div>
  );
};

// ==================== T11 部门人事子页面组件 (新增) ====================
// ==================== T11 部门人事子页面组件 - 打地鼠游戏 ====================
// ==================== T11 部门人事子页面组件 - 打地鼠游戏 (修复与美化版) ====================
const T11PersonnelSubPage = ({ onBack }) => {
  // ------------------- 状态管理 -------------------
  const [departmentScores, setDepartmentScores] = React.useState(
    MOLE_THEMES.map(() => 0),
  ); // 每个部门的KPI分数
  const [moles, setMoles] = React.useState(Array(MOLE_COUNT).fill(null)); // null=无, 对象=有地鼠(存颜色索引)
  const [hammerPosition, setHammerPosition] = React.useState({
    x: 0,
    y: 0,
  });
  const [hammerState, setHammerState] = React.useState("up"); // up, down, hit
  const [gameStarted, setGameStarted] = React.useState(false);
  const [gameTime, setGameTime] = React.useState(INITIAL_GAME_DURATION);
  const [currentMoleCount, setCurrentMoleCount] = React.useState(1); // 当前单次地鼠数量
  const [currentMoleDuration, setCurrentMoleDuration] = React.useState(
    INITIAL_MOLE_DURATION,
  ); // 当前地鼠时长
  const [danmakus, setDanmakus] = React.useState([]); // 弹幕列表
  const [missionEnabled, setMissionEnabled] = React.useState(false); // 任务模式开关
  const [currentMission, setCurrentMission] = React.useState(null); // 当前任务（指定打击的部门索引）

  // ------------------- 引用 -------------------
  const gameContainerRef = React.useRef(null);
  const moleTimerRef = React.useRef(null);
  const gameTimerRef = React.useRef(null);
  const danmakuTimerRef = React.useRef(null);
  const missionTimerRef = React.useRef(null); // 任务定时器引用
  const lastMoleIndexRef = React.useRef(null); // 使用useRef存储上一次生成地鼠的洞口索引，避免状态更新异步问题

  // ------------------- 游戏逻辑 -------------------

  // 弹幕生成函数
  const generateDanmaku = () => {
    if (!gameStarted) return;

    const randomChar =
      CHARACTERS[Math.floor(Math.random() * CHARACTERS.length)];
    const newDanmaku = {
      id: Date.now() + Math.random(),
      text: `${randomChar}前来围观`,
      y: Math.random() * 80 + 10, // 10-90% 的垂直位置
      color: MOLE_THEMES[Math.floor(Math.random() * MOLE_THEMES.length)].body,
    };

    setDanmakus((prev) => [...prev, newDanmaku]);

    // 弹幕结束后移除
    setTimeout(() => {
      setDanmakus((prev) => prev.filter((d) => d.id !== newDanmaku.id));
    }, DANMAKU_SPEED);
  };

  // 任务生成函数
  const generateMission = () => {
    if (!gameStarted || !missionEnabled) return;

    // 随机生成一个部门索引作为任务目标
    const randomDepartmentIndex = Math.floor(
      Math.random() * MOLE_THEMES.length,
    );
    setCurrentMission(randomDepartmentIndex);

    // 3秒后生成新任务
    missionTimerRef.current = setTimeout(generateMission, 3000);
  };

  // 切换任务模式
  const toggleMissionMode = () => {
    const newState = !missionEnabled;
    setMissionEnabled(newState);

    if (newState && gameStarted) {
      // 开启任务模式并生成第一个任务
      generateMission();
    } else {
      // 关闭任务模式，清除当前任务和定时器
      setCurrentMission(null);
      if (missionTimerRef.current) {
        clearTimeout(missionTimerRef.current);
        missionTimerRef.current = null;
      }
    }
  };

  // 核心修复：使用 useEffect 监听 gameStarted 来管理定时器
  React.useEffect(() => {
    if (gameStarted) {
      // 1. 启动倒计时
      gameTimerRef.current = setInterval(() => {
        setGameTime((prev) => {
          if (prev <= 1) {
            endGame();
            return 0;
          }

          // 计算剩余时间，用于判断难度递增
          const remainingTime = prev - 1;

          // 数量递增：每5秒递增1只，上限4只
          if (
            remainingTime % MOLE_COUNT_INCREMENT === 0 &&
            currentMoleCount < MAX_MOLE_COUNT
          ) {
            setCurrentMoleCount((prevCount) =>
              Math.min(prevCount + 1, MAX_MOLE_COUNT),
            );
          }

          // 速度递增：每6秒缩短0.2秒，下限0.4秒
          if (
            remainingTime % DURATION_DECREASE_INTERVAL === 0 &&
            currentMoleDuration > MIN_MOLE_DURATION
          ) {
            setCurrentMoleDuration((prevDuration) =>
              Math.max(prevDuration - DURATION_DECREASE, MIN_MOLE_DURATION),
            );
          }

          return remainingTime;
        });
      }, 1000);

      // 2. 启动地鼠生成循环
      const loop = () => {
        // 根据当前地鼠数量生成多个地鼠
        for (let i = 0; i < currentMoleCount; i++) {
          // 延迟生成，避免同时生成多个地鼠导致视觉混乱
          setTimeout(() => {
            generateMole();
          }, i * 200);
        }

        // 根据当前地鼠时长调整生成间隔
        const nextPopTime = Math.random() * 300 + currentMoleDuration * 0.6;
        moleTimerRef.current = setTimeout(loop, nextPopTime);
      };
      loop();

      // 3. 启动弹幕生成
      danmakuTimerRef.current = setInterval(generateDanmaku, DANMAKU_INTERVAL);

      // 4. 如果任务模式开启，启动任务生成
      if (missionEnabled) {
        generateMission();
      }
    } else {
      // 清理定时器
      clearInterval(gameTimerRef.current);
      clearTimeout(moleTimerRef.current);
      clearInterval(danmakuTimerRef.current);
      setDanmakus([]); // 清空弹幕
    }

    return () => {
      clearInterval(gameTimerRef.current);
      clearTimeout(moleTimerRef.current);
      clearInterval(danmakuTimerRef.current);
      clearTimeout(missionTimerRef.current);
    };
  }, [gameStarted, currentMoleCount, currentMoleDuration]);

  const startGame = () => {
    setDepartmentScores(MOLE_THEMES.map(() => 0)); // 重置所有部门的分数
    setGameTime(INITIAL_GAME_DURATION);
    setMoles(Array(MOLE_COUNT).fill(null));
    setCurrentMoleCount(1); // 重置为初始地鼠数量
    setCurrentMoleDuration(INITIAL_MOLE_DURATION); // 重置为初始地鼠时长
    setGameStarted(true);
  };

  const endGame = () => {
    setGameStarted(false);
    setMoles(Array(MOLE_COUNT).fill(null));
    // 使用函数式更新确保获取最新的departmentScores值
    setDepartmentScores((currentScores) => {
      // 构建每个部门的分数信息
      const scoreInfo = currentScores
        .map((score, index) => {
          return `${MOLE_THEMES[index].department}：${score}`;
        })
        .join("\n");
      alert(`时间到！绩效考核结束。\n各部门KPI得分：\n${scoreInfo}`);
      return currentScores; // 不改变scores值，只使用最新值
    });
  };

  const generateMole = () => {
    setMoles((currentMoles) => {
      // 检查当前活跃地鼠数量
      const activeMolesCount = currentMoles.filter(
        (mole) => mole !== null,
      ).length;

      // 限制最大活跃地鼠数量为当前地鼠数量的2倍，确保有足够的空洞生成新地鼠
      if (activeMolesCount >= currentMoleCount * 2) return currentMoles;

      // 找到所有空洞
      let emptyIndices = currentMoles
        .map((m, i) => (m === null ? i : null))
        .filter((i) => i !== null);

      if (emptyIndices.length === 0) return currentMoles;

      // 排除上一次的洞口索引
      if (lastMoleIndexRef.current !== null && emptyIndices.length > 1) {
        emptyIndices = emptyIndices.filter(
          (index) => index !== lastMoleIndexRef.current,
        );
      }

      // 随机选一个洞
      const randomIndex =
        emptyIndices[Math.floor(Math.random() * emptyIndices.length)];
      // 随机选一个颜色皮肤
      const themeIndex = Math.floor(Math.random() * MOLE_THEMES.length);

      const newMoles = [...currentMoles];
      newMoles[randomIndex] = { themeIdx: themeIndex, active: true };

      // 直接更新上一次的洞口索引，避免状态更新异步问题
      lastMoleIndexRef.current = randomIndex;

      // 设置自动消失 - 使用当前地鼠时长
      setTimeout(() => {
        setMoles((latestMoles) => {
          if (!latestMoles[randomIndex]) return latestMoles; // 已经被打了
          const updated = [...latestMoles];
          updated[randomIndex] = null;
          return updated;
        });
      }, currentMoleDuration);

      return newMoles;
    });
  };

  const handleMoleClick = (index) => {
    if (!gameStarted) return;

    // 先获取当前的任务模式状态，避免闭包问题
    const isMissionEnabled = missionEnabled;
    const currentTask = currentMission;

    // 使用函数式更新确保获取最新状态
    setMoles((currentMoles) => {
      // 检查地鼠是否存在
      if (currentMoles[index]) {
        // 获取地鼠的主题索引
        const themeIdx = currentMoles[index].themeIdx;

        // 任务模式逻辑
        if (isMissionEnabled && currentTask !== null) {
          if (themeIdx === currentTask) {
            // 击中指定颜色地鼠，计分
            setDepartmentScores((prevScores) => {
              const newScores = [...prevScores];
              newScores[themeIdx] += 10;
              return newScores;
            });
          } else {
            // 击中非指定颜色地鼠，算作失败，立刻结束游戏
            if (navigator.vibrate) navigator.vibrate(100);
            // 结束游戏
            endGame();
          }
        } else {
          // 正常模式，计分
          setDepartmentScores((prevScores) => {
            const newScores = [...prevScores];
            newScores[themeIdx] += 10;
            return newScores;
          });
        }

        // 标记地鼠为被击中状态，定住不动
        const newMoles = [...currentMoles];
        newMoles[index] = { ...currentMoles[index], hit: true };
        // 震动反馈
        if (navigator.vibrate) navigator.vibrate(50);

        // 2秒后将地鼠缩回去
        setTimeout(() => {
          setMoles((latestMoles) => {
            const updated = [...latestMoles];
            updated[index] = null;
            return updated;
          });
        }, 2000);

        return newMoles;
      }
      return currentMoles;
    });
  };

  // 锤子跟随逻辑
  const handleMouseMove = (e) => {
    // 只有在游戏容器内才更新锤子
    if (!gameContainerRef.current) return;
    const rect = gameContainerRef.current.getBoundingClientRect();

    // 兼容触摸和鼠标
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const clientY = e.touches ? e.touches[0].clientY : e.clientY;

    setHammerPosition({
      x: clientX - rect.left,
      y: clientY - rect.top,
    });
  };

  const handleMouseDown = () => setHammerState("down");
  const handleMouseUp = () => setHammerState("up");

  // ------------------- UI 组件 (SVG) -------------------
  // 组件已移至外部定义

  return (
    <div
      style={{
        position: "absolute",
        top: 0,
        left: 0,
        width: "100%",
        height: "100%",
        background: "#f9f7f5",
        zIndex: 20,
      }}
    >
      {/* 导航栏 */}
      <div className="t11-nav">
        <div className="back-btn" onClick={onBack}>
          <i className="ph ph-caret-left" style={{ fontSize: "24px" }}></i>
        </div>
        <div className="title">部门人事考核</div>
      </div>

      <div
        className="t11-subpage-container"
        style={{
          padding: "20px",
          height: "calc(100% - 60px)",
          display: "flex",
          flexDirection: "column",
        }}
      >
        {/* 仪表盘 */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            padding: "16px 24px",
            background: "white",
            borderRadius: "20px",
            boxShadow: "0 4px 20px rgba(140, 145, 123, 0.1)",
            marginBottom: "20px",
          }}
        >
          {/* 各部门KPI得分 */}
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              marginBottom: "16px",
            }}
          >
            {MOLE_THEMES.map((theme, index) => (
              <div key={index} style={{ textAlign: "center", flex: 1 }}>
                <div style={{ fontSize: "10px", color: "#999" }}>
                  {theme.department}
                </div>
                <div
                  style={{
                    fontSize: "18px",
                    fontWeight: "bold",
                    color: theme.body,
                    fontFamily: "Fredoka",
                  }}
                >
                  {departmentScores[index]}
                </div>
              </div>
            ))}
          </div>
          {/* 弹幕、任务和时间区域 */}
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              flexWrap: "wrap",
              gap: "12px",
            }}
          >
            {/* 左边弹幕 */}
            <div
              style={{
                flex: 2,
                height: "40px",
                position: "relative",
                overflow: "hidden",
                borderRadius: "20px",
                background: "#f9f7f5",
                marginRight: "12px",
              }}
            >
              {danmakus.map((danmaku) => (
                <div
                  key={danmaku.id}
                  style={{
                    position: "absolute",
                    left: "100%",
                    top: `${danmaku.y}%`,
                    transform: "translateY(-50%)",
                    whiteSpace: "nowrap",
                    padding: "6px 12px",
                    borderRadius: "16px",
                    backgroundColor: "rgba(255, 255, 255, 0.8)",
                    color: danmaku.color,
                    fontSize: "12px",
                    fontWeight: "500",
                    animation: "danmaku 8000ms linear forwards",
                    zIndex: 1,
                  }}
                >
                  {danmaku.text}
                </div>
              ))}
            </div>

            {/* 中间任务区域 */}
            <div
              style={{
                flex: 1.5,
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
              }}
            >
              {/* 任务要求 */}
              <div
                style={{
                  fontSize: "12px",
                  color: "#999",
                  marginBottom: "4px",
                }}
              >
                {missionEnabled ? "当前任务" : "任务模式"}
              </div>
              <div
                style={{
                  fontSize: "14px",
                  fontWeight: "bold",
                  color:
                    missionEnabled && currentMission !== null
                      ? MOLE_THEMES[currentMission].body
                      : "#5a5f4d",
                  fontFamily: "Fredoka",
                  textAlign: "center",
                }}
              >
                {missionEnabled && currentMission !== null
                  ? `打击${MOLE_THEMES[currentMission].department}地鼠`
                  : "关闭"}
              </div>
              {/* 任务模式开关 */}
              <div style={{ marginTop: "4px" }}>
                <label className="switch">
                  <input
                    type="checkbox"
                    checked={missionEnabled}
                    onChange={toggleMissionMode}
                  />
                  <span className="slider round"></span>
                </label>
              </div>
            </div>

            {/* 右边时间 */}
            <div style={{ flex: 1, textAlign: "right" }}>
              <div style={{ fontSize: "12px", color: "#999" }}>剩余时间</div>
              <div
                style={{
                  fontSize: "24px",
                  fontWeight: "bold",
                  color: "#5a5f4d",
                  fontFamily: "Fredoka",
                }}
              >
                {gameTime}s
              </div>
            </div>
          </div>
        </div>

        {/* 游戏主区域 */}
        <div
          ref={gameContainerRef}
          style={{
            flex: 1,
            background: "#EAE6D6", // 土壤颜色
            borderRadius: "24px",
            position: "relative",
            overflow: "hidden",
            boxShadow: "inset 0 0 20px rgba(0,0,0,0.05)",
            border: "8px solid #DED6C5",
            cursor: "none", // 隐藏默认鼠标，使用自定义锤子
            touchAction: "none", // 防止触摸滚动
          }}
          onMouseMove={handleMouseMove}
          onTouchMove={handleMouseMove}
          onMouseDown={handleMouseDown}
          onTouchStart={handleMouseDown}
          onMouseUp={handleMouseUp}
          onTouchEnd={handleMouseUp}
        >
          {/* 3x3 网格 */}
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(3, 1fr)",
              gridTemplateRows: "repeat(3, 1fr)",
              height: "100%",
              padding: "20px",
              gap: "10px",
            }}
          >
            {moles.map((moleData, index) => (
              <div
                key={index}
                style={{
                  position: "relative",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "flex-end",
                  overflow: "hidden",
                  borderRadius: "50%",
                  height: "100%",
                }}
              >
                {/* 洞口阴影 - 增强深度感 */}
                <div
                  style={{
                    position: "absolute",
                    bottom: "10%",
                    width: "80%",
                    height: "30px",
                    background: "rgba(0,0,0,0.2)",
                    borderRadius: "50%",
                    filter: "blur(5px)",
                  }}
                ></div>

                {/* 洞口内壁 - 增强深度感 */}
                <div
                  style={{
                    position: "absolute",
                    bottom: "0",
                    width: "90%",
                    height: "60%",
                    background: "linear-gradient(to top, #5D534A, #8B7E70)",
                    borderRadius: "50% 50% 50% 50% / 30% 30% 70% 70%",
                    zIndex: 1,
                  }}
                ></div>

                {/* 地鼠 */}
                <div
                  onClick={(e) => {
                    e.stopPropagation(); // 防止冒泡
                    handleMoleClick(index);
                    handleMouseDown(); // 触发锤子动画
                    setTimeout(handleMouseUp, 100);
                  }}
                  style={{
                    width: "100%",
                    height: "100%",
                    position: "relative",
                    zIndex: 3,
                  }}
                >
                  {moleData && (
                    <CuteMole themeIdx={moleData.themeIdx} hit={moleData.hit} />
                  )}
                </div>

                {/* 洞口边缘遮罩 - 调整z-index，确保不阻挡点击 */}
                <div
                  style={{
                    position: "absolute",
                    bottom: "0",
                    width: "100%",
                    height: "40%",
                    background:
                      "linear-gradient(to bottom, transparent, #EAE6D6)",
                    zIndex: 2,
                    borderRadius: "50%",
                    pointerEvents: "none", // 禁用点击事件，确保点击穿透到地鼠容器
                  }}
                ></div>
              </div>
            ))}
          </div>

          {/* 锤子 (仅在游戏开始且在区域内时显示) */}
          {gameStarted && (
            <FancyHammer
              x={hammerPosition.x}
              y={hammerPosition.y}
              state={hammerState}
            />
          )}
        </div>

        {/* 开始按钮 */}
        {!gameStarted && (
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              width: "100%",
              height: "100%",
              background: "rgba(255,255,255,0.4)",
              backdropFilter: "blur(4px)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              zIndex: 60,
            }}
          >
            <button
              onClick={startGame}
              className="active-press"
              style={{
                padding: "16px 48px",
                background: "linear-gradient(135deg, #A8C8BA 0%, #8FA99D 100%)",
                border: "none",
                borderRadius: "30px",
                color: "white",
                fontSize: "20px",
                fontWeight: "bold",
                boxShadow: "0 10px 25px rgba(168, 200, 186, 0.5)",
                cursor: "pointer",
              }}
            >
              {gameTime < INITIAL_GAME_DURATION ? "重新考核" : "开始考核"}
            </button>
          </div>
        )}
      </div>

      {/* 动画样式 - 优化弹出效果 */}
      <style>{`
                                                                                                                                  @keyframes molePop {
                                                                                                                                    0% { transform: translateY(100%); }
                                                                                                                                    100% { transform: translateY(0); }
                                                                                                                                  }

                                                                                                                                  @keyframes danmaku {
                                                                                                                                    0% { transform: translateX(0) translateY(-50%); }
                                                                                                                                    100% { transform: translateX(-100vw) translateY(-50%); }
                                                                                                                                  }

                                                                                                                                  /* 开关按钮样式 */
                                                                                                                                  .switch {
                                                                                                                                    position: relative;
                                                                                                                                    display: inline-block;
                                                                                                                                    width: 40px;
                                                                                                                                    height: 20px;
                                                                                                                                  }

                                                                                                                                  .switch input {
                                                                                                                                    opacity: 0;
                                                                                                                                    width: 0;
                                                                                                                                    height: 0;
                                                                                                                                  }

                                                                                                                                  .slider {
                                                                                                                                    position: absolute;
                                                                                                                                    cursor: pointer;
                                                                                                                                    top: 0;
                                                                                                                                    left: 0;
                                                                                                                                    right: 0;
                                                                                                                                    bottom: 0;
                                                                                                                                    background-color: #ccc;
                                                                                                                                    transition: .4s;
                                                                                                                                  }

                                                                                                                                  .slider:before {
                                                                                                                                    position: absolute;
                                                                                                                                    content: "";
                                                                                                                                    height: 16px;
                                                                                                                                    width: 16px;
                                                                                                                                    left: 2px;
                                                                                                                                    bottom: 2px;
                                                                                                                                    background-color: white;
                                                                                                                                    transition: .4s;
                                                                                                                                  }

                                                                                                                                  input:checked + .slider {
                                                                                                                                    background-color: #A8C8BA;
                                                                                                                                  }

                                                                                                                                  input:focus + .slider {
                                                                                                                                    box-shadow: 0 0 1px #A8C8BA;
                                                                                                                                  }

                                                                                                                                  input:checked + .slider:before {
                                                                                                                                    transform: translateX(20px);
                                                                                                                                  }

                                                                                                                                  .slider.round {
                                                                                                                                    border-radius: 20px;
                                                                                                                                  }

                                                                                                                                  .slider.round:before {
                                                                                                                                    border-radius: 50%;
                                                                                                                                  }
                                                                                                                                `}</style>
    </div>
  );
};
