// ==================== 公告编辑页面组件 ====================
const NoticeEditPage = ({
  onCancel,
  onPublish,
  MORANDI_COLORS,
  TABS,
  initialData,
}) => {
  // 在组件内部使用useState管理输入状态
  const [title, setTitle] = React.useState(initialData?.title || "");
  const [content, setContent] = React.useState(initialData?.content || "");
  const [selectedTab, setSelectedTab] = React.useState(
    initialData?.selectedTab || 0,
  );
  const [originalTabIndex, setOriginalTabIndex] = React.useState(
    initialData?.originalTabIndex || -1,
  );
  const [originalNoticeIndex, setOriginalNoticeIndex] = React.useState(
    initialData?.originalNoticeIndex || -1,
  );

  // 处理发布
  const handlePublish = () => {
    if (!title.trim() || !content.trim()) {
      alert("请填写标题和内容");
      return;
    }

    // 调用父组件的发布函数
    onPublish({
      title,
      content,
      selectedTab,
      originalTabIndex,
      originalNoticeIndex,
    });
  };

  return (
    <div
      style={{
        position: "absolute",
        top: 0,
        left: 0,
        width: "100%",
        height: "100%",
        background: MORANDI_COLORS.light,
        zIndex: 30,
      }}
    >
      {/* 导航栏 */}
      <div className="t11-nav">
        <div className="back-btn" onClick={onCancel}>
          <i className="ph ph-caret-left" style={{ fontSize: "24px" }}></i>
        </div>
        <div className="title">
          {originalTabIndex >= 0 ? "编辑公告" : "发布公告"}
        </div>
      </div>

      <div
        className="t11-subpage-container"
        style={{
          padding: "16px",
          height: "calc(100% - 60px)",
          display: "flex",
          flexDirection: "column",
        }}
      >
        {/* 标题输入框 */}
        <div style={{ marginBottom: "16px" }}>
          <label
            style={{
              display: "block",
              marginBottom: "8px",
              fontSize: "14px",
              color: MORANDI_COLORS.dark,
            }}
          >
            标题
          </label>
          <input
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="请输入公告标题"
            style={{
              width: "100%",
              padding: "12px",
              borderRadius: "12px",
              border: "1px solid #EAEAEA",
              fontSize: "14px",
              outline: "none",
              background: "#fff",
            }}
          />
        </div>

        {/* 内容输入框 */}
        <div style={{ marginBottom: "16px", height: "150px" }}>
          <label
            style={{
              display: "block",
              marginBottom: "8px",
              fontSize: "14px",
              color: MORANDI_COLORS.dark,
            }}
          >
            内容
          </label>
          <textarea
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="请输入公告内容"
            style={{
              width: "100%",
              height: "100%",
              padding: "12px",
              borderRadius: "12px",
              border: "1px solid #EAEAEA",
              fontSize: "14px",
              outline: "none",
              background: "#fff",
              resize: "none",
            }}
          />
        </div>

        {/* 板块选择区域 */}
        <div style={{ marginTop: "24px", marginBottom: "16px" }}>
          <label
            style={{
              display: "block",
              marginBottom: "8px",
              fontSize: "14px",
              color: MORANDI_COLORS.dark,
            }}
          >
            选择板块
          </label>
          <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
            {TABS.map((tab, index) => (
              <button
                key={index}
                onClick={() => setSelectedTab(index)}
                style={{
                  padding: "6px 12px",
                  borderRadius: "16px",
                  border: "none",
                  background:
                    selectedTab === index ? MORANDI_COLORS.primary : "#f0f0f0",
                  color: selectedTab === index ? "#fff" : "#999",
                  fontSize: "12px",
                  cursor: "pointer",
                  transition: "all 0.3s ease",
                }}
              >
                {tab}
              </button>
            ))}
          </div>
        </div>

        {/* 按钮区域 */}
        <div style={{ display: "flex", gap: "12px" }}>
          <button
            onClick={onCancel}
            style={{
              flex: 1,
              padding: "12px",
              borderRadius: "12px",
              border: "1px solid #EAEAEA",
              background: "#f0f0f0",
              color: "#999",
              fontSize: "14px",
              cursor: "pointer",
              transition: "all 0.3s ease",
            }}
          >
            取消
          </button>
          <button
            onClick={handlePublish}
            style={{
              flex: 1,
              padding: "12px",
              borderRadius: "12px",
              border: "none",
              background: MORANDI_COLORS.primary,
              color: "#fff",
              fontSize: "14px",
              cursor: "pointer",
              transition: "all 0.3s ease",
            }}
          >
            {originalTabIndex >= 0 ? "保存" : "发布"}
          </button>
        </div>
      </div>

      {/* 动画样式 */}
      <style>{`
                                                                                                                                  @keyframes fadeIn {
                                                                                                                                    from { opacity: 0; transform: translateY(10px); }
                                                                                                                                    to { opacity: 1; transform: translateY(0); }
                                                                                                                                  }
                                                                                                                                `}</style>
    </div>
  );
};

