// T13 休闲一刻主页面组件
const StarChartPage = ({ onBack }) => {
  // 生成随机星座的函数
  const generateRandomConstellation = (
    starCount = Math.floor(Math.random() * 7) + 6,
  ) => {
    const nodes = [];
    const links = [];

    for (let i = 0; i < starCount; i++) {
      const x = Math.random() * 200 + 100; // 100-300（缩小水平范围）
      const y = Math.random() * 305 + 125; // 180-430（缩小垂直范围，避开统计文本区域）
      const size = Math.random() * 3 + 2; // 2-5（缩小星星大小）
      nodes.push([x, y, size]);
    }

    const sortedNodes = [...nodes].map((node, index) => ({
      index,
      node,
    }));
    if (Math.random() > 0.5) {
      sortedNodes.sort((a, b) => a.node[0] - b.node[0]);
    } else {
      sortedNodes.sort((a, b) => a.node[1] - b.node[1]);
    }

    for (let i = 0; i < sortedNodes.length - 1; i++) {
      links.push([sortedNodes[i].index, sortedNodes[i + 1].index]);
    }

    for (let i = 0; i < nodes.length; i++) {
      if (Math.random() > 0.7) {
        const distances = [];
        for (let j = 0; j < nodes.length; j++) {
          if (i !== j) {
            const dx = nodes[i][0] - nodes[j][0];
            const dy = nodes[i][1] - nodes[j][1];
            const distance = Math.sqrt(dx * dx + dy * dy);
            const linkExists = links.some(
              (link) =>
                (link[0] === i && link[1] === j) ||
                (link[0] === j && link[1] === i),
            );
            if (!linkExists) {
              distances.push({ index: j, distance });
            }
          }
        }
        if (distances.length > 0) {
          distances.sort((a, b) => a.distance - b.distance);
          links.push([i, distances[0].index]);
        }
      }
    }

    return { nodes, links, starCount };
  };

  const [constellation, setConstellation] = React.useState(
    generateRandomConstellation(),
  );
  const [inputText, setInputText] = React.useState("");
  const [displayText, setDisplayText] = React.useState("");
  const [showText, setShowText] = React.useState(false);

  // 新增：AI及逝者相关状态
  const [isGenerating, setIsGenerating] = React.useState(false);
  const [statistics, setStatistics] = React.useState("");
  const [deceasedList, setDeceasedList] = React.useState([]);
  const [selectedDeceased, setSelectedDeceased] = React.useState(null);

  // ===== 新增：他人寄语相关状态 =====
  const [showTributesModal, setShowTributesModal] = React.useState(false);
  const [isGeneratingTributes, setIsGeneratingTributes] = React.useState(false);
  const [tributesList, setTributesList] = React.useState([]);

  // ===== 新增：处理生成他人寄语 =====
  const handleGenerateTributes = async () => {
    if (!selectedDeceased || isGeneratingTributes) return;

    setIsGeneratingTributes(true);
    setShowTributesModal(true); // 打开弹窗显示加载中
    setTributesList([]); // 清空旧数据

    try {
      // 1. 获取世界书设定
      const worldContext = window.getWorldBookContext
        ? await window.getWorldBookContext()
        : "无特定背景设定";

      // 2. 获取传讯角色 (排除群聊和装饰)
      let allChars = [];
      if (window.chatCharacterStore) {
        allChars = await window.chatCharacterStore.getAll();
      } else {
        allChars = JSON.parse(localStorage.getItem("t8_chat_list") || "[]");
      }
      const validChars = allChars.filter(
        (c) => !String(c.id).startsWith("group") && c.type !== "decor",
      );

      // 随机抽取 2 到 3 个现有的传讯角色
      const shuffled = [...validChars].sort(() => 0.5 - Math.random());
      const selectedChars = shuffled.slice(
        0,
        Math.max(2, Math.min(3, validChars.length)),
      );

      const charsInfo = selectedChars
        .map(
          (c) =>
            `【已有角色】姓名: ${c.name} | 身份/背景: ${c.profile?.background || "未知"} | 性格: ${c.profile?.personality || "无"} | 语言风格: ${c.profile?.style || "无"}`,
        )
        .join("\n");

      // 3. 构建 Prompt
      const sysPrompt =
        "你是一个深谙东汉末年历史与人情冷暖的文案生成器，擅长模拟不同身份人物的口吻表达对逝者的缅怀或态度。";
      const userPrompt = `
                            【世界设定】
                            ${worldContext}

                            【逝者信息】
                            姓名：${selectedDeceased.name}
                            年龄：${selectedDeceased.age}
                            身份/家族：${selectedDeceased.family} - ${selectedDeceased.profession}
                            死因：${selectedDeceased.death_cause}
                            生前最爱：${selectedDeceased.favorite}
                            生前愿景：${selectedDeceased.wish}

                            【必须包含的特定已知角色】
                            ${charsInfo}
                            (注意：必须使用上述列出的已有角色生成缅怀，并且寄语的语气必须严格符合他们的性格和语言风格)

                            【任务】
                            请生成 10 到 15 条针对该逝者的缅怀/寄语。
                            要求：
                            1. 评价的人中必须包含上面提供的【已有角色】（如果有的话）。
                            2. 其余评价人可以是随机生成的NPC（如当地人、客居者、家人、陌生人、甚至是坏人、仇人等）。
                            3. 每条寄语的语言风格必须符合评价人的身份和立场（如仇人可能冷嘲热讽，亲人悲痛欲绝，路人只作叹息）。
                            4. 严格返回纯 JSON 数组格式，不要包含任何 Markdown 标记（如 \`\`\`json ），直接以 [ 开头，] 结尾。

                            返回格式示例：
                            [
                              {
                                "name": "评价人名字",
                                "identity": "评价人身份（如：幽州商贩、死者长兄、或者是已有角色）",
                                "item": "带给逝者的东西（如：一壶浊酒、一束野花、一把残剑、甚至是一口唾沫）",
                                "message": "想告诉逝者的话"
                              }
                            ]
                        `;

      // 4. 调用大模型
      if (window.sendToLLM) {
        window.sendToLLM(
          [
            { role: "system", content: sysPrompt },
            { role: "user", content: userPrompt },
          ],
          null,
          (reply) => {
            try {
              const cleanJson = reply.replace(/```json|```/g, "").trim();
              const data = JSON.parse(cleanJson);
              if (Array.isArray(data) && data.length > 0) {
                setTributesList(data);
              } else {
                throw new Error("返回格式非数组");
              }
            } catch (e) {
              console.error("解析寄语失败:", e, reply);
              alert("获取寄语失败，请重试。");
              setShowTributesModal(false);
            } finally {
              setIsGeneratingTributes(false);
            }
          },
          (err) => {
            console.error(err);
            alert("网络波动，获取寄语失败。请检查API设置。");
            setIsGeneratingTributes(false);
            setShowTributesModal(false);
          },
        );
      } else {
        alert("未找到 API 接口，请先在设置中配置 API！");
        setIsGeneratingTributes(false);
        setShowTributesModal(false);
      }
    } catch (e) {
      console.error(e);
      setIsGeneratingTributes(false);
      setShowTributesModal(false);
    }
  };

  // 处理发送按钮点击 (接入大模型推演)
  const handleSend = async () => {
    if (!inputText.trim() || isGenerating) return;

    setIsGenerating(true);
    try {
      const worldContext = window.getWorldBookContext
        ? await window.getWorldBookContext()
        : "无特定背景设定";

      // 预先生成下一张星图，以确定需生成的逝者数量
      const newConstellation = generateRandomConstellation();
      const count = newConstellation.starCount;

      const sysPrompt =
        "你是一个沉浸式的东汉末年历史推演AI计算器，深谙世事沧桑与平民百态。";
      const userPrompt = `
                            【世界设定】
                            ${worldContext}

                            【发生的事件记录】
                            ${inputText}

                            【任务要求】
                            基于上述事件和世界观，推演这场事件造成的伤亡情况，并具体生成 ${count} 名在此事件中丧生的人物信息以点亮星象。
                            人物身份要多样（包括老者、孩童、士兵、士族、平民等），人物的性格、生前愿望和临终念头要严格符合其年龄、身份与当前的时代背景。

                            【输出格式严格要求】
                            必须直接输出纯JSON格式数据，绝对不要包含Markdown代码块（如 \`\`\`json ）。格式如下：
                            {
                              "statistics": "这段文字描述此次事件造成的总伤亡人数及职业/身份分布（如：此次事件造成共计xxx人伤亡，其中平民xx人，士兵xx人等。言简意赅）",
                              "deceased": [
                                {
                                  "name": "姓名",
                                  "family": "家族或出身（如：河内平民、颍川陈氏）",
                                  "profession": "职业/身份",
                                  "age": "年龄（包含单位，如'7岁'、'54岁'）",
                                  "death_cause": "死法（在三五句话以内，需要描述清楚）",
                                  "favorite": "生前喜欢的事物",
                                  "wish": "生前最大的愿望",
                                  "last_thought": "死之前的最后一个念头（以第一人称主观视角表达）"
                                }
                              ]
                            }
                            注：deceased 数组的长度必须严格等于 ${count}。
                        `;

      if (window.sendToLLM) {
        window.sendToLLM(
          [
            { role: "system", content: sysPrompt },
            { role: "user", content: userPrompt },
          ],
          null,
          (reply) => {
            try {
              const cleanJson = reply.replace(/```json|```/g, "").trim();
              const data = JSON.parse(cleanJson);

              setConstellation(newConstellation);
              setStatistics(data.statistics || "");

              const dList = data.deceased || [];
              // 兜底补齐，以防大模型生成数量不够导致报错
              while (dList.length < count) {
                dList.push({
                  name: "无名氏",
                  family: "未知",
                  profession: "平民",
                  age: "未知",
                  death_cause:
                    "今天是农历初三。父母放他出去玩。他找到了小伙伴，一起提着蹴鞠。但遇到了府兵，被殴打致死。",
                  favorite: "活着",
                  wish: "天下太平",
                  last_thought: "好冷...",
                });
              }
              setDeceasedList(dList);

              setDisplayText(inputText.trim());
              setShowText(true);
              setInputText("");
            } catch (e) {
              console.error("星轨数据解析失败:", e, reply);
              alert("星轨推演失败，请重试。");
            } finally {
              setIsGenerating(false);
            }
          },
          (err) => {
            console.error(err);
            alert("星轨推演请求失败，请检查API设置。");
            setIsGenerating(false);
          },
        );
      } else {
        alert("未找到 API 接口，请前往设置配置！");
        setIsGenerating(false);
      }
    } catch (e) {
      console.error(e);
      setIsGenerating(false);
    }
  };

  return (
    <div
      className="starchart-overlay open fade-in"
      style={{
        position: "absolute",
        inset: 0,
        zIndex: 900,
        background: "radial-gradient(circle at center, #1a1b3a 0%, #0a0b16 100%)",
        display: "flex",
        flexDirection: "column",
        overflow: "hidden",
        width: "100%",
        height: "100%",
      }}
    >
      <div className="flex justify-between p-6 items-center z-10">
        <div className="flex items-center gap-4 flex-1">
          <input
            type="text"
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            placeholder="记录灾厄、战乱或变故..."
            className="border-b-2 border-dashed border-white/30 flex-1 bg-transparent text-white placeholder-white/50 py-2 focus:outline-none"
            disabled={isGenerating}
          />
          <button
            onClick={handleSend}
            disabled={isGenerating}
            className="constellation-btn flex items-center justify-center"
          >
            <i className="ph ph-paper-plane text-white text-sm"></i>
          </button>
        </div>
        <i
          className="ph ph-x text-white text-2xl ml-6 cursor-pointer"
          onClick={onBack}
        ></i>
      </div>

      {/* 顶部统计数据展示区 */}
      {statistics && !isGenerating && (
        <div className="px-6 pb-2 text-white/80 text-sm text-center leading-relaxed z-10 font-serif">
          {statistics}
        </div>
      )}

      <div className="flex-1 relative w-full h-full min-h-[300px]">
        <svg viewBox="0 0 400 600" className="w-full h-full" style={{ width: "100%", height: "100%" }}>
          <defs>
            <filter id="starGlowFilter" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="3" result="blur" />
              <feComposite in="SourceGraphic" in2="blur" operator="over" />
            </filter>
          </defs>
          {/* 连线层 */}
          {constellation.links.map((link, i) => {
            const n1 = constellation.nodes[link[0]];
            const n2 = constellation.nodes[link[1]];
            if (!n1 || !n2) return null;
            return (
              <g key={`link-${i}`}>
                <line
                  className="star-glow"
                  x1={n1[0]}
                  y1={n1[1]}
                  x2={n2[0]}
                  y2={n2[1]}
                  stroke="rgba(255, 255, 255, 0.4)"
                  strokeWidth="4"
                  strokeLinecap="round"
                  filter="url(#starGlowFilter)"
                />
                <line
                  className="star-line"
                  x1={n1[0]}
                  y1={n1[1]}
                  x2={n2[0]}
                  y2={n2[1]}
                  stroke="rgba(255, 255, 255, 0.85)"
                  strokeWidth="1.5"
                  strokeLinecap="round"
                />
              </g>
            );
          })}
          {/* 节点层 (可点击查看逝者信息) */}
          {constellation.nodes.map((node, i) => (
            <circle
              key={i}
              className="star-node pulse-anim"
              cx={node[0]}
              cy={node[1]}
              r={Math.max(node[2] || 3, 3.5)}
              fill="#ffffff"
              style={{
                filter: "drop-shadow(0 0 6px rgba(255, 255, 255, 0.95))",
                animationDelay: `${i * 0.5}s`,
                cursor: deceasedList.length > 0 ? "pointer" : "default",
              }}
              onClick={() => {
                if (deceasedList[i]) {
                  setSelectedDeceased(deceasedList[i]);
                }
              }}
            />
          ))}
        </svg>

        {/* 加载状态遮罩 */}
        {isGenerating && (
          <div className="absolute inset-0 flex items-center justify-center bg-[#0a0b16]/70 z-20">
            <div className="text-white flex flex-col items-center gap-3">
              <iconify-icon
                icon="line-md:loading-twotone-loop"
                style={{ fontSize: "36px" }}
              ></iconify-icon>
              <span className="text-sm tracking-widest font-serif">
                星象交替，命轨推演中...
              </span>
            </div>
          </div>
        )}

        {/* 用户输入文字底部显示区域 */}
        {showText && !isGenerating && (
          <div className="absolute bottom-20 left-0 right-0 text-center pointer-events-none">
            <div
              className={`text-white font-serif text-lg transition-all duration-1000 ease-in-out ${
                showText ? "opacity-100 blur-0" : "opacity-0 blur-md"
              }`}
            >
              {displayText}
            </div>
          </div>
        )}
      </div>

      <div className="p-10 text-center text-white/30 text-xs tracking-widest font-serif italic">
        - 嘒彼小星 ，三五在东 -
      </div>

      {/* 逝者信息弹出卡片 */}
      {selectedDeceased && (
        <div className="fixed inset-x-0 bottom-0 bg-[#F9F7F5] rounded-t-3xl shadow-[0_-10px_40px_rgba(0,0,0,0.5)] z-50 animate-slide-up max-h-[85vh] flex flex-col">
          <div className="p-5 flex justify-between items-center border-b border-gray-200">
            <h3 className="text-xl font-bold text-[#1a1b3a] tracking-widest font-serif">
              命轨记录
            </h3>
            <button
              onClick={() => setSelectedDeceased(null)}
              className="w-8 h-8 rounded-full bg-gray-200 flex items-center justify-center text-gray-600 active:scale-95"
            >
              <i className="ph-bold ph-x"></i>
            </button>
          </div>

          <div className="flex-1 overflow-y-auto p-6 flex flex-col gap-4 text-[#4A4F55] no-scrollbar">
            <div className="flex items-end gap-3 mb-2">
              <h2 className="text-3xl font-bold text-[#1a1b3a] font-serif">
                {selectedDeceased.name}
              </h2>
              <span className="text-sm bg-gray-200 px-3 py-1 rounded-full text-gray-600 font-medium">
                {selectedDeceased.age}
              </span>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="bg-white p-3 rounded-xl shadow-sm border border-gray-100">
                <div className="text-xs text-gray-400 mb-1">家族 / 出身</div>
                <div className="font-medium text-[#1a1b3a]">
                  {selectedDeceased.family}
                </div>
              </div>
              <div className="bg-white p-3 rounded-xl shadow-sm border border-gray-100">
                <div className="text-xs text-gray-400 mb-1">职业 / 身份</div>
                <div className="font-medium text-[#1a1b3a]">
                  {selectedDeceased.profession}
                </div>
              </div>
            </div>

            <div className="bg-red-50 p-4 rounded-xl border-l-4 border-red-300">
              <div className="text-xs text-red-400 mb-1 font-bold">
                殒命之因
              </div>
              <div className="text-sm font-medium text-red-800 leading-relaxed">
                {selectedDeceased.death_cause}
              </div>
            </div>

            <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
              <div className="text-xs text-gray-400 mb-1">生前偏爱</div>
              <div className="font-medium text-[#4A4F55] leading-relaxed">
                {selectedDeceased.favorite}
              </div>
            </div>

            <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
              <div className="text-xs text-gray-400 mb-1">最大愿景</div>
              <div className="font-medium text-[#4A4F55] leading-relaxed">
                {selectedDeceased.wish}
              </div>
            </div>

            <div className="bg-[#1a1b3a]/5 p-5 rounded-xl mt-2 relative">
              <div className="absolute top-2 left-2 opacity-10 text-4xl font-serif">
                "
              </div>
              <div className="text-xs text-gray-500 mb-2 font-bold">
                临终执念
              </div>
              <div className="italic font-serif text-[#1a1b3a] text-base leading-relaxed relative z-10 px-2">
                {selectedDeceased.last_thought}
              </div>
            </div>
          </div>

          <div className="p-4 flex gap-3 border-t border-gray-200 bg-white">
            <button
              className="flex-1 py-3 rounded-xl bg-[#e8e5d9] text-[#5A5F4D] font-bold active:scale-95 transition-transform flex items-center justify-center"
              onClick={() => {
                const msg = prompt("写下你的寄语：");
                if (msg) {
                  alert("寄语已化作星光。");
                  alert("已送上白菊，愿逝者安息。");
                }
              }}
            >
              <iconify-icon
                icon="ph:flower-lotus-fill"
                style={{ marginRight: "8px", fontSize: "18px" }}
              ></iconify-icon>
              送花缅怀
            </button>
            <button
              className="flex-1 py-3 rounded-xl bg-[#1a1b3a] text-white font-bold active:scale-95 transition-transform flex items-center justify-center"
              onClick={handleGenerateTributes}
            >
              <iconify-icon
                icon="ph:paper-plane-tilt-fill"
                style={{ marginRight: "8px", fontSize: "18px" }}
              ></iconify-icon>
              他人寄语
            </button>
          </div>
        </div>
      )}

      {/* ===== 新增：他人寄语弹出卡片 ===== */}
      {showTributesModal && (
        <div className="fixed inset-x-0 bottom-0 bg-[#F9F7F5] rounded-t-3xl shadow-[0_-10px_40px_rgba(0,0,0,0.5)] z-[60] animate-slide-up max-h-[85vh] flex flex-col">
          <div className="p-5 flex justify-between items-center border-b border-gray-200">
            <h3 className="text-xl font-bold text-[#1a1b3a] tracking-widest font-serif flex items-center gap-2">
              <iconify-icon
                icon="ph:paper-plane-tilt-fill"
                style={{ color: "#D6724B" }}
              ></iconify-icon>
              众人寄语
            </h3>
            <button
              onClick={() => setShowTributesModal(false)}
              className="w-8 h-8 rounded-full bg-gray-200 flex items-center justify-center text-gray-600 active:scale-95"
            >
              <i className="ph-bold ph-x"></i>
            </button>
          </div>

          <div className="flex-1 overflow-y-auto p-5 bg-[#F9F7F5] no-scrollbar">
            {isGeneratingTributes ? (
              <div className="flex flex-col items-center justify-center h-48 text-[#8C917B] gap-3">
                <iconify-icon
                  icon="line-md:loading-twotone-loop"
                  style={{ fontSize: "36px", color: "#1a1b3a" }}
                ></iconify-icon>
                <span className="text-sm font-bold tracking-widest font-serif">
                  正在倾听世人的凭吊...
                </span>
              </div>
            ) : tributesList.length > 0 ? (
              <div className="flex flex-col gap-4 pb-8">
                {tributesList.map((tribute, idx) => (
                  <div
                    key={idx}
                    className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 relative"
                  >
                    <div className="flex justify-between items-start mb-2">
                      <div className="flex items-center gap-2">
                        <div className="w-8 h-8 rounded-full bg-[#1a1b3a] flex items-center justify-center text-white text-sm font-bold font-serif shadow-inner">
                          {tribute.name ? tribute.name.charAt(0) : "?"}
                        </div>
                        <div>
                          <div className="font-bold text-[#1a1b3a] text-sm leading-tight">
                            {tribute.name}
                          </div>
                          <div className="text-xs text-gray-500 mt-0.5">
                            {tribute.identity}
                          </div>
                        </div>
                      </div>
                    </div>

                    <div className="bg-[#fdfcf8] p-3 rounded-lg border-l-4 border-[#D6724B] mb-3 mt-2">
                      <div className="text-xs text-gray-400 font-bold mb-1">
                        <iconify-icon
                          icon="ph:gift-fill"
                          style={{ marginRight: "4px" }}
                        ></iconify-icon>
                        带来/献上了
                      </div>
                      <div className="text-sm text-[#4A4F55] font-medium">
                        {tribute.item}
                      </div>
                    </div>

                    <div className="text-sm text-[#4A4F55] leading-relaxed italic font-serif">
                      "{tribute.message}"
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="text-center text-gray-500 mt-10 font-serif">
                此处空空如也，风中再无余音。
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

// ==================== T13 蝴蝶效应页面组件 ====================

const ButterflyEffectPage = ({ onBack }) => {
  const { useState } = React;

  // 状态管理
  const [inputText, setInputText] = useState("");
  const [isEditing, setIsEditing] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [effectData, setEffectData] = useState([]); // 存储所有节点生成的推演数据
  const [selectedDot, setSelectedDot] = useState(null); // 当前选中的圆点数据
  const [showModal, setShowModal] = useState(false); // 控制卡片显示

  // 莫兰迪色值
  const colors = {
    white: "#FFFFFF",
    gray: "#A0A0A0",
    pink: "#FF9B9B",
  };

  // 16个圆点坐标及类型定义：8白(好结局), 7灰(坏结局), 1粉(转折点)
  const dots = [
    // 左环 (4白3灰)
    { id: 0, type: "好结局", x: -100, y: 0, color: colors.white },
    { id: 1, type: "好结局", x: -85, y: -45, color: colors.white },
    { id: 2, type: "好结局", x: -50, y: -65, color: colors.white },
    { id: 3, type: "好结局", x: -10, y: -45, color: colors.white },
    { id: 4, type: "坏结局", x: -10, y: 45, color: colors.gray },
    { id: 5, type: "坏结局", x: -45, y: 65, color: colors.gray },
    { id: 6, type: "坏结局", x: -82, y: 45, color: colors.gray },
    // 右环 (4白4灰)
    { id: 7, type: "坏结局", x: 100, y: -20, color: colors.gray },
    { id: 8, type: "坏结局", x: 85, y: -55, color: colors.gray },
    { id: 9, type: "坏结局", x: 50, y: -70, color: colors.gray },
    { id: 10, type: "坏结局", x: 10, y: -45, color: colors.gray },
    { id: 11, type: "好结局", x: 10, y: 45, color: colors.white },
    { id: 12, type: "好结局", x: 45, y: 70, color: colors.white },
    { id: 13, type: "好结局", x: 82, y: 55, color: colors.white },
    { id: 14, type: "好结局", x: 100, y: 20, color: colors.white },
    // 中心连接点 (1粉)
    {
      id: 15,
      type: "转折点",
      x: 0,
      y: 0,
      color: colors.pink,
      isCenter: true,
    },
  ];

  // 核心：调用 AI 生成蝴蝶效应
  const handleGenerate = async () => {
    if (!inputText.trim())
      return alert("请先输入您想要引发蝴蝶效应的起源文字！");
    if (isGenerating) return;

    setIsGenerating(true);
    setEffectData([]); // 清空旧数据

    try {
      // 获取世界书设定
      const worldContext = window.getWorldBookContext
        ? await window.getWorldBookContext()
        : "无特定背景设定";

      const sysPrompt = "你是一个精通东汉历史、蝴蝶效应推演及人性洞察的大师。";
      const userPrompt = `
                        【世界设定】
                        ${worldContext}

                        【起源事件】
                        ${inputText}

                        【推演任务】
                        基于上述起源，严格符合东汉史实推演蝴蝶效应的16个事件节点。
                        - 节点 15 是【转折点】：好坏都会经历的一环，直接承接起源事件，它是分歧的共同连接点。
                        - 节点 0,1,2,3,11,12,13,14 是【好结局线】：从左到右依次递进 (0->1->2->3->11->12->13->14)，后一个事件必须和前一个事件有关联，开端承接转折点15，最终导向一个相对圆满或给人希望的结局。
                        - 节点 4,5,6,7,8,9,10 是【坏结局线】：从左到右依次递进 (4->5->6->7->8->9->10)，后一个事件必须和前一个事件有关联，开端承接转折点15，最终导向一个残缺、悲惨或混乱的结局。

                        【重要提示】
                        - 事件可以是日常生活中的小事，也可以是大格局或重大历史事件
                        - 注重细节和真实感，让事件更贴近普通人的生活
                        - 保持东汉时期的背景设定。

                        【输出格式严格要求】
                        必须返回一个长度严格为 16 的纯 JSON 数组，数组对象的 id 必须是从 0 到 15。
                        请绝对不要包含 Markdown 代码块（如 \`\`\`json ），直接以 [ 开始，] 结尾。
                        数组每个对象的结构如下：
                        {
                          "id": 数字索引(0-15),
                          "name": "事件关联人（或物品）的姓名",
                          "identity": "关联人的身份",
                          "content": "事件具体内容（3到5句话，层层递进）",
                          "original": "原本走向（若起源未发生，本来的日常轨迹）",
                          "svgHtml": "一段表示此事件的简单几何SVG代码，宽高视口为 viewBox='0 0 100 100'，颜色建议符合该节点氛围，代码中可以加点行内CSS交互效果"
                        }
                        `;

      if (window.sendToLLM) {
        window.sendToLLM(
          [
            { role: "system", content: sysPrompt },
            { role: "user", content: userPrompt },
          ],
          null,
          (reply) => {
            try {
              const cleanJson = reply.replace(/```json|```/g, "").trim();
              const data = JSON.parse(cleanJson);
              if (Array.isArray(data) && data.length === 16) {
                // 将数据通过 id 排序以便匹配
                data.sort((a, b) => a.id - b.id);
                setEffectData(data);
                alert("蝴蝶效应推演完成！\n请点击页面上的圆点查看命运分歧。");
              } else {
                throw new Error("返回的数组长度不足或结构异常");
              }
            } catch (e) {
              console.error("解析AI返回数据失败:", e, reply);
              alert("天机受阻，推演失败，请重试！");
            } finally {
              setIsGenerating(false);
              setIsEditing(false);
            }
          },
          (err) => {
            console.error("请求失败:", err);
            alert("请求失败，请检查 API 接口配置！");
            setIsGenerating(false);
          },
        );
      } else {
        alert("未找到 API 接口，请先在设置中配置！");
        setIsGenerating(false);
      }
    } catch (e) {
      console.error(e);
      setIsGenerating(false);
    }
  };

  // 处理点击圆点
  const handleDotClick = (dot) => {
    if (effectData.length === 0) {
      alert("请先在底部的虚线上输入起源，并点击发送按钮引发推演！");
      return;
    }
    const data = effectData.find((item) => item.id === dot.id);
    if (data) {
      setSelectedDot({ ...data, type: dot.type });
      setShowModal(true);
    }
  };

  return (
    <div
      className="butterfly-effect-overlay open"
      style={{
        position: "absolute",
        inset: 0,
        zIndex: 900,
        backgroundColor: "#000000",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        width: "100%",
        height: "100%",
        overflow: "hidden",
      }}
    >
      {/* 顶部返回按钮 */}
      <div
        className="be-back-btn"
        onClick={onBack}
        style={{
          position: "absolute",
          top: "40px",
          right: "25px",
          color: "#ffffff",
          fontSize: "24px",
          cursor: "pointer",
          opacity: 0.8,
          zIndex: 20,
        }}
      >
        ✕
      </div>

      {/* 圆点排列舞台 */}
      <div
        className="be-infinity-container"
        style={{
          position: "relative",
          width: "320px",
          height: "160px",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          marginTop: "-60px",
        }}
      >
        {dots.map((dot, i) => (
          <div
            key={i}
            className="be-dot"
            onClick={() => handleDotClick(dot)}
            style={{
              position: "absolute",
              width: "36px",
              height: "36px",
              borderRadius: "50%",
              backgroundColor: dot.color,
              transform: `translate(${dot.x}px, ${dot.y}px) ${effectData.length > 0 && selectedDot?.id === dot.id ? "scale(1.3)" : "scale(1)"}`,
              boxShadow: dot.isCenter
                ? "0 0 18px rgba(255,155,155,0.95)"
                : effectData.length > 0
                  ? "0 0 12px rgba(255,255,255,0.8)"
                  : "0 0 6px rgba(255,255,255,0.4)",
              zIndex: dot.isCenter ? 10 : 1,
              cursor: effectData.length > 0 ? "pointer" : "default",
              border:
                effectData.length > 0
                  ? "2px solid rgba(255,255,255,0.9)"
                  : "none",
              transition: "all 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275)",
            }}
          />
        ))}
      </div>

      {/* 底部虚线输入和发送按钮 */}
      <div
        style={{
          position: "absolute",
          bottom: "100px",
          display: "flex",
          alignItems: "center",
          gap: "10px",
          width: "80%",
          maxWidth: "400px",
        }}
      >
        <div
          style={{
            flex: 1,
            borderBottom: "3px dashed white",
            position: "relative",
            height: "30px",
          }}
        >
          {isEditing ? (
            <input
              autoFocus
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              onBlur={() => setIsEditing(false)}
              onKeyDown={(e) => e.key === "Enter" && handleGenerate()}
              style={{
                width: "100%",
                background: "transparent",
                border: "none",
                color: "white",
                outline: "none",
                textAlign: "center",
                position: "absolute",
                bottom: "-5px",
                fontSize: "16px",
                fontFamily: "inherit",
              }}
            />
          ) : (
            <div
              onClick={() => !isGenerating && setIsEditing(true)}
              style={{
                width: "100%",
                height: "100%",
                cursor: isGenerating ? "not-allowed" : "text",
                color: "white",
                textAlign: "center",
                display: "flex",
                alignItems: "flex-end",
                justifyContent: "center",
                paddingBottom: "5px",
                fontSize: "15px",
                opacity: inputText ? 1 : 0.6,
                fontFamily: "inherit",
              }}
            >
              {inputText || "在此输入起源，扇动命运的翅膀..."}
            </div>
          )}
        </div>

        {/* 发送按钮 */}
        <div
          onClick={handleGenerate}
          style={{
            width: "42px",
            height: "42px",
            backgroundColor:
              inputText.trim() && !isGenerating
                ? "#FF9B9B"
                : "rgba(255, 155, 155, 0.3)",
            borderRadius: "50%",
            cursor:
              inputText.trim() && !isGenerating ? "pointer" : "not-allowed",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            boxShadow:
              inputText.trim() && !isGenerating
                ? "0 4px 12px rgba(255,155,155,0.4)"
                : "none",
            transition: "all 0.3s ease",
          }}
        >
          {isGenerating ? (
            <iconify-icon
              icon="line-md:loading-twotone-loop"
              style={{ color: "white", fontSize: "20px" }}
            ></iconify-icon>
          ) : (
            <iconify-icon
              icon="ph:paper-plane-tilt-fill"
              style={{ color: "white", fontSize: "20px" }}
            ></iconify-icon>
          )}
        </div>
      </div>

      {/* 弹出的卡片层 */}
      {showModal && selectedDot && (
        <div
          style={{
            position: "fixed",
            bottom: 0,
            left: 0,
            right: 0,
            background: "rgba(30, 30, 30, 0.95)",
            backdropFilter: "blur(12px)",
            borderTopLeftRadius: "24px",
            borderTopRightRadius: "24px",
            padding: "30px 24px",
            boxShadow: "0 -10px 40px rgba(0,0,0,0.5)",
            zIndex: 100,
            animation:
              "slideUp 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards",
            color: "#fff",
            maxHeight: "85vh",
            overflowY: "auto",
          }}
        >
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "flex-start",
              marginBottom: "20px",
            }}
          >
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                gap: "8px",
              }}
            >
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: "10px",
                }}
              >
                <span
                  style={{
                    background:
                      selectedDot.type === "好结局"
                        ? "#FFFFFF"
                        : selectedDot.type === "坏结局"
                          ? "#A0A0A0"
                          : "#FF9B9B",
                    color: selectedDot.type === "好结局" ? "#333" : "#FFF",
                    padding: "4px 12px",
                    borderRadius: "12px",
                    fontSize: "12px",
                    fontWeight: "bold",
                  }}
                >
                  {selectedDot.type}
                </span>
                <span
                  style={{
                    fontSize: "20px",
                    fontWeight: "bold",
                    fontFamily: "serif",
                    letterSpacing: "2px",
                  }}
                >
                  {selectedDot.name}
                </span>
              </div>
              <span
                style={{
                  fontSize: "12px",
                  color: "rgba(255,255,255,0.6)",
                }}
              >
                身份标签：{selectedDot.identity}
              </span>
            </div>
            <button
              onClick={() => setShowModal(false)}
              style={{
                background: "none",
                border: "none",
                color: "#fff",
                fontSize: "24px",
                cursor: "pointer",
                opacity: 0.7,
              }}
            >
              ✕
            </button>
          </div>

          <div
            style={{
              background: "rgba(255,255,255,0.08)",
              padding: "16px",
              borderRadius: "12px",
              marginBottom: "16px",
              borderLeft: "4px solid #FF9B9B",
            }}
          >
            <div
              style={{
                fontSize: "12px",
                color: "rgba(255,255,255,0.5)",
                marginBottom: "8px",
                fontWeight: "bold",
              }}
            >
              事件内容
            </div>
            <div
              style={{
                fontSize: "14px",
                lineHeight: "1.7",
                letterSpacing: "1px",
                color: "rgba(255,255,255,0.95)",
              }}
            >
              {selectedDot.content}
            </div>
          </div>

          <div
            style={{
              background: "rgba(255,255,255,0.05)",
              padding: "16px",
              borderRadius: "12px",
              marginBottom: "24px",
              borderLeft: "4px solid #A0A0A0",
            }}
          >
            <div
              style={{
                fontSize: "12px",
                color: "rgba(255,255,255,0.5)",
                marginBottom: "8px",
                fontWeight: "bold",
              }}
            >
              原本走向
            </div>
            <div
              style={{
                fontSize: "13px",
                lineHeight: "1.7",
                color: "rgba(255,255,255,0.7)",
              }}
            >
              {selectedDot.original}
            </div>
          </div>

          <div
            style={{
              textAlign: "center",
              marginTop: "10px",
              paddingBottom: "20px",
            }}
          >
            <div
              style={{
                fontSize: "12px",
                color: "rgba(255,255,255,0.4)",
                marginBottom: "12px",
                letterSpacing: "2px",
              }}
            >
              - 象形之意 -
            </div>
            <div
              style={{
                width: "100px",
                height: "100px",
                margin: "0 auto",
                background: "rgba(0,0,0,0.4)",
                borderRadius: "16px",
                padding: "15px",
                boxShadow: "inset 0 0 10px rgba(0,0,0,0.5)",
                cursor: "pointer",
                transition: "transform 0.3s ease",
              }}
              onMouseEnter={(e) =>
                (e.currentTarget.style.transform = "scale(1.1)")
              }
              onMouseLeave={(e) =>
                (e.currentTarget.style.transform = "scale(1)")
              }
              dangerouslySetInnerHTML={{ __html: selectedDot.svgHtml }}
            />
          </div>
        </div>
      )}
    </div>
  );
};

// ------------------- (插入位置6: const MasterApp = () => { 上方定义组件) -------------------

const SandTablePage = ({ onBack }) => {
  const [elements, setElements] = React.useState([]);
  const [navCollapsed, setNavCollapsed] = React.useState(false);
  const [scale, setScale] = React.useState(1);
  const [lastDistance, setLastDistance] = React.useState(0);
  const [selectedElement, setSelectedElement] = React.useState(null);
  const [showWriteModal, setShowWriteModal] = React.useState(false);
  const [writeContent, setWriteContent] = React.useState("");

  // --- 新增推演系统状态 ---
  const [simulationSteps, setSimulationSteps] = React.useState([]);
  const [currentStep, setCurrentStep] = React.useState(-1);
  const [showSimulationModal, setShowSimulationModal] = React.useState(false);
  const [isSimulating, setIsSimulating] = React.useState(false);
  const [simulationModalCollapsed, setSimulationModalCollapsed] =
    React.useState(false);

  // --- 沙盘拖动状态 ---
  const [isDragging, setIsDragging] = React.useState(false);
  const [dragStart, setDragStart] = React.useState({ x: 0, y: 0 });
  const [sandboxPosition, setSandboxPosition] = React.useState({
    x: 0,
    y: 0,
  });

  // 新增状态
  const [isGenerating, setIsGenerating] = React.useState(false);
  const [inventory, setInventory] = React.useState([]); // 底部物品栏数据
  const [detailItem, setDetailItem] = React.useState(null); // 当前查看详情的物品
  const [isConnecting, setIsConnecting] = React.useState(false); // 是否处于连接模式
  const [connections, setConnections] = React.useState([]); // 连接关系数组
  const [showConnections, setShowConnections] = React.useState(true); // 是否显示连接线

  // 添加物品到沙盘（同时扣除库存）
  const handleAddInventoryItem = (item) => {
    if (!item.isInfinite && item.quantity <= 0) {
      alert("该物资已耗尽！");
      return;
    }

    // 扣除库存
    if (!item.isInfinite) {
      setInventory((prev) =>
        prev.map((inv) =>
          inv.id === item.id ? { ...inv, quantity: inv.quantity - 1 } : inv,
        ),
      );
    }

    // 添加到沙盘
    const newElement = {
      id: Date.now() + Math.random(),
      invId: item.id, // 关联库存ID，方便删除时退回
      char: item.emoji,
      x: 150 + Math.random() * 50,
      y: 150 + Math.random() * 50,
      flipped: false,
      detailInfo: item, // 将详情信息一并存入实体
    };
    setElements([...elements, newElement]);
  };

  // 删除沙盘物品（退回库存）
  const handleDeleteElement = (id) => {
    const elToDelete = elements.find((el) => el.id === id);
    if (elToDelete) {
      // 退回库存
      setInventory((prev) =>
        prev.map((inv) =>
          inv.id === elToDelete.invId && !inv.isInfinite
            ? { ...inv, quantity: inv.quantity + 1 }
            : inv,
        ),
      );
    }
    // 删除相关的连接
    setConnections((prev) =>
      prev.filter((conn) => conn.source !== id && conn.target !== id),
    );
    setElements((prev) => prev.filter((el) => el.id !== id));
    setSelectedElement(null);
    setDetailItem(null); // 关闭可能打开的详情
  };

  // 查看详情
  const handleElementDetail = (id) => {
    const el = elements.find((e) => e.id === id);
    if (el) {
      setDetailItem(el.detailInfo);
    }
  };

  // 处理连接按钮点击
  const handleConnectElement = (id) => {
    if (isConnecting) {
      // 已经处于连接模式，完成连接
      completeConnection(id);
    } else {
      // 开始连接模式
      setIsConnecting(true);
      setSelectedElement(id);
    }
  };

  // 完成连接
  const completeConnection = (targetId) => {
    if (selectedElement && selectedElement !== targetId) {
      // 检查是否已经存在相同的连接
      const existingConnection = connections.find(
        (conn) => conn.source === selectedElement && conn.target === targetId,
      );

      if (!existingConnection) {
        // 添加新连接
        setConnections([
          ...connections,
          {
            id: Date.now(),
            source: selectedElement,
            target: targetId,
          },
        ]);
      }
    }
    // 退出连接模式
    setIsConnecting(false);
    setSelectedElement(null);
  };

  // 移除连接
  const removeConnection = (connectionId) => {
    setConnections(connections.filter((conn) => conn.id !== connectionId));
  };

  // --- 模拟推演核心逻辑 ---
  const handleSimulate = async () => {
    if (elements.length === 0) {
      alert("沙盘上空空如也，请先放置一些单位后再推演！");
      return;
    }

    setIsSimulating(true);
    setShowSimulationModal(true);
    setCurrentStep(-1);
    setSimulationSteps([]);

    try {
      const worldContext = window.getWorldBookContext
        ? await window.getWorldBookContext()
        : "无特定背景设定";

      // 提取元素简要信息供AI分析，以便明确有哪些可移动物体
      const elementsInfo = elements.map((el) => ({
        id: el.id,
        name: el.detailInfo.name,
        category: el.detailInfo.category,
        x: Math.round(el.x),
        y: Math.round(el.y),
      }));

      const connectionsInfo = connections.map((conn) => ({
        sourceId: conn.source,
        targetId: conn.target,
      }));

      const sysPrompt = "你是一个精通东汉末年兵法与沙盘推演的军师AI。";
      const userPrompt = `
            【世界设定】
            ${worldContext}

            【推演背景】
            ${writeContent || "无特定背景"}

            【沙盘当前单位】
            ${JSON.stringify(elementsInfo, null, 2)}

            【单位连线关系（从属/牵引关系，source带动target）】
            ${JSON.stringify(connectionsInfo, null, 2)}

            【推演任务】
            请基于当前沙盘单位分布、连线关系和背景，生成一场10到15步的定格动画模拟推演。
            要求：
            1. 考虑地形，自然类单位（如山脉、密林）通常不可移动。
            2. 让军队或武将相互靠近、绕后或交战。
            3. 如果有父子连线的元素，只需要给出父元素(sourceId)的移动坐标，系统会自动带动子元素。
            4. 每一步都要有对战局的描述，以及用诙谐专业的语气说明这步操作的兵法原因。
            5. 每一步返回发生移动的元素和他们的新绝对坐标 (targetX, targetY)。确保坐标在 0 到 1000 之间变动，每次移动距离建议在 30-100 之间。

            【输出格式】
            必须严格返回纯 JSON 数组，格式如下（绝对不要包裹在 \`\`\`json 中）：
            [
              {
                "step": 1,
                "description": "我方主帅带领小弟绕开密林，准备偷袭。",
                "reason": "老六兵法第一条，能苟绝不正面刚！",
                "moves": [
                  { "elementId": 123456789, "targetX": 150, "targetY": 250 }
                ]
              }
            ]
            `;

      if (window.sendToLLM) {
        window.sendToLLM(
          [
            { role: "system", content: sysPrompt },
            { role: "user", content: userPrompt },
          ],
          null,
          (reply) => {
            try {
              const cleanJson = reply.replace(/```json|```/g, "").trim();
              const data = JSON.parse(cleanJson);
              if (Array.isArray(data) && data.length > 0) {
                setSimulationSteps(data);
                setCurrentStep(0); // 开始第一步
              } else {
                throw new Error("解析数据为空");
              }
            } catch (e) {
              console.error("推演解析失败:", e, reply);
              alert("推演失败，军机受阻，请重新生成。");
              setShowSimulationModal(false);
            } finally {
              setIsSimulating(false);
            }
          },
          (err) => {
            console.error("生成推演失败:", err);
            setIsSimulating(false);
            setShowSimulationModal(false);
            alert("请求失败，请检查API配置");
          },
        );
      } else {
        alert("未配置API，请前往设置配置！");
        setIsSimulating(false);
        setShowSimulationModal(false);
      }
    } catch (error) {
      console.error(error);
      setIsSimulating(false);
      setShowSimulationModal(false);
    }
  };

  // 计算包含推演位移和父子联动后的实际元素坐标
  const getSimulatedElements = () => {
    let simElements = elements.map((el) => ({ ...el }));

    if (currentStep < 0 || !simulationSteps.length) return simElements;

    for (let i = 0; i <= currentStep; i++) {
      const stepData = simulationSteps[i];
      if (!stepData || !stepData.moves) continue;

      const displacements = {};

      // 1. 应用本步的主动绝对移动，并记录位移差 (dx, dy)
      stepData.moves.forEach((move) => {
        const elIndex = simElements.findIndex((e) => e.id === move.elementId);
        if (elIndex !== -1) {
          displacements[move.elementId] = {
            dx: move.targetX - simElements[elIndex].x,
            dy: move.targetY - simElements[elIndex].y,
          };
          simElements[elIndex].x = move.targetX;
          simElements[elIndex].y = move.targetY;
        }
      });

      // 2. 处理父子连带移动
      let changed = true;
      const propagated = { ...displacements };
      while (changed) {
        changed = false;
        connections.forEach((conn) => {
          const parentDisp = propagated[conn.source];
          if (parentDisp && !propagated[conn.target]) {
            const targetIndex = simElements.findIndex(
              (e) => e.id === conn.target,
            );
            if (targetIndex !== -1) {
              simElements[targetIndex].x += parentDisp.dx;
              simElements[targetIndex].y += parentDisp.dy;
              propagated[conn.target] = { ...parentDisp };
              changed = true;
            }
          }
        });
      }
    }
    return simElements;
  };

  const simulatedElements = getSimulatedElements();
  // --- 模拟推演核心逻辑结束 ---

  // AI生成物品清单核心逻辑
  const handleGenerateItems = async () => {
    if (!writeContent.trim()) {
      alert("请先书写战局背景或兵棋推演的需求！");
      return;
    }
    setIsGenerating(true);

    try {
      // 1. 获取世界书设定
      const worldContext = window.getWorldBookContext
        ? await window.getWorldBookContext()
        : "无特定背景设定";

      // 2. 构建 Prompt
      const sysPrompt = "你是一个专业的三国/古风沙盘兵棋推演组件生成器。";
      const userPrompt = `
                          【世界设定】
                          ${worldContext}

                          【统帅（用户）书写的推演背景】
                          ${writeContent}

                          【任务】
                          请根据以上背景，生成一场沙盘模拟所需的物品/地形清单，总数必须在 15 到 20 个之间。

                          【严格生成规则】
                          1. 必须包含的分类：
                             - 自然类(nature)：必须有（如河流、森林、山脉），属性 isInfinite 必须为 true，quantity 设为 -1。
                             - 工具类(tool)：必须有（如马车、船只、拒马），isInfinite 为 false，quantity 在 3-10 之间。
                             - 物资类(resource)：必须有（如粮草、辎重、箭矢），isInfinite 为 false，quantity 在 2-5 之间。
                             - 人物/建筑类(character/building)：（如斥候、城门、流民），isInfinite 为 false，quantity 根据常理设定。
                          2. 必须包含的高亮特殊物品：
                             - 必须生成且仅生成两个特殊标识（isSpecial 为 true）：一个代表【我方阵营】的emoji，一个代表【敌方阵营】的emoji。quantity 通常为 1 或 2。
                          3. 趣味详情：
                             - description：物品用途，必须用轻松、风趣、甚至带点吐槽的口吻编写（例如："一处被人遗弃的破碗，不知道有什么用，可能用来讨饭"）。
                             - scale：物品实际换算比例（例如："此处的1辆 ≈ 现实100辆" 或 "1个兵 ≈ 1个营"）。

                          【输出格式】
                          必须严格返回纯 JSON 数组，不要包裹在 \`\`\`json 之中，格式示例：
                          [
                            {"id": 1, "emoji": "🔵", "name": "我方主帅", "category": "faction", "quantity": 1, "isInfinite": false, "isSpecial": true, "description": "全村的希望，死了就直接Game Over。", "scale": "1人 ≈ 主帅本阵"},
                            {"emoji": "🔴", "name": "敌方主力", "category": "faction", "quantity": 3, "isInfinite": false, "isSpecial": true, "description": "看起来很凶的敌人，建议绕道走。", "scale": "1棋 ≈ 5000甲士"},
                            {"emoji": "🌲", "name": "密林", "category": "nature", "quantity": -1, "isInfinite": true, "isSpecial": false, "description": "藏污纳垢的好地方，适合老六埋伏。", "scale": "1树 ≈ 10亩林地"},
                            {"emoji": "🌾", "name": "粮草", "category": "resource", "quantity": 5, "isInfinite": false, "isSpecial": false, "description": "人是铁饭是钢，没这玩意儿兵要造反。", "scale": "1垛 ≈ 1000石"}
                          ]
                        `;

      if (window.sendToLLM) {
        window.sendToLLM(
          [
            { role: "system", content: sysPrompt },
            { role: "user", content: userPrompt },
          ],
          null,
          (reply) => {
            try {
              const cleanJson = reply.replace(/```json|```/g, "").trim();
              const data = JSON.parse(cleanJson);
              if (Array.isArray(data) && data.length >= 2) {
                // 补充唯一ID，防止重复
                const inventoryData = data.map((item, idx) => ({
                  ...item,
                  id: Date.now() + idx,
                }));
                setInventory(inventoryData);
                setShowWriteModal(false);
                alert("兵棋组件生成完毕，请在底部物品栏查看！");
              } else {
                throw new Error("数组为空或不符合要求");
              }
            } catch (e) {
              console.error("沙盘解析失败:", e, reply);
              alert("推演失败，军机受阻，请重新生成。");
            } finally {
              setIsGenerating(false);
            }
          },
          (err) => {
            console.error("生成沙盘物品失败:", err);
            setIsGenerating(false);
            alert("请求失败，请检查API配置");
          },
        );
      } else {
        alert("未配置API，请前往设置配置！");
        setIsGenerating(false);
      }
    } catch (error) {
      console.error(error);
      setIsGenerating(false);
    }
  };

  const handleDrag = (id, e) => {
    const clientX = e.clientX || e.touches[0].clientX;
    const clientY = e.clientY || e.touches[0].clientY;
    // 考虑缩放比例，确保物品拖动在不同缩放级别下都能正常工作
    setElements((prev) =>
      prev.map((el) =>
        el.id === id
          ? {
              ...el,
              x: (clientX - 20) * scale,
              y: (clientY - 80) * scale,
            }
          : el,
      ),
    );
  };

  const handleTouchStart = (e) => {
    if (e.touches.length === 2) {
      const dx = e.touches[0].clientX - e.touches[1].clientX;
      const dy = e.touches[0].clientY - e.touches[1].clientY;
      setLastDistance(Math.sqrt(dx * dx + dy * dy));
    }
  };

  const handleTouchMove = (e) => {
    if (e.touches.length === 2) {
      const dx = e.touches[0].clientX - e.touches[1].clientX;
      const dy = e.touches[0].clientY - e.touches[1].clientY;
      const distance = Math.sqrt(dx * dx + dy * dy);

      if (lastDistance > 0) {
        const scaleFactor = distance / lastDistance;
        const newScale = Math.max(0.1, Math.min(5, scale * scaleFactor));
        setScale(newScale);
      }

      setLastDistance(distance);
    }
  };

  const handleTouchEnd = () => {
    setLastDistance(0);
  };

  const handleWheel = (e) => {
    e.preventDefault();
    const scaleFactor = e.deltaY > 0 ? 0.9 : 1.1;
    const newScale = Math.max(0.1, Math.min(5, scale * scaleFactor));
    setScale(newScale);
  };

  // 沙盘拖动事件处理
  const handleSandboxMouseDown = (e) => {
    // 只有在鼠标左键点击且没有其他元素被选中时才开始拖动
    if (e.button === 0 && !isConnecting && !selectedElement) {
      setIsDragging(true);
      setDragStart({
        x: e.clientX - sandboxPosition.x,
        y: e.clientY - sandboxPosition.y,
      });
    }
  };

  const handleSandboxMouseMove = (e) => {
    if (isDragging) {
      setSandboxPosition({
        x: e.clientX - dragStart.x,
        y: e.clientY - dragStart.y,
      });
    }
  };

  const handleSandboxMouseUp = () => {
    setIsDragging(false);
  };

  const handleSandboxMouseLeave = () => {
    setIsDragging(false);
  };

  // 触摸事件处理
  const handleSandboxTouchStart = (e) => {
    if (e.touches.length === 1 && !isConnecting && !selectedElement) {
      setIsDragging(true);
      setDragStart({
        x: e.touches[0].clientX - sandboxPosition.x,
        y: e.touches[0].clientY - sandboxPosition.y,
      });
    }
  };

  const handleSandboxTouchMove = (e) => {
    if (isDragging && e.touches.length === 1) {
      setSandboxPosition({
        x: e.touches[0].clientX - dragStart.x,
        y: e.touches[0].clientY - dragStart.y,
      });
    }
  };

  const handleSandboxTouchEnd = () => {
    setIsDragging(false);
  };

  const handleElementClick = (id) => {
    setSelectedElement(id === selectedElement ? null : id);
  };

  const handleFlipElement = (id) => {
    setElements((prev) =>
      prev.map((el) => (el.id === id ? { ...el, flipped: !el.flipped } : el)),
    );
  };

  return (
    <div
      className="sand-table-overlay open fade-in"
      style={{
        position: "absolute",
        inset: 0,
        zIndex: 900,
        backgroundColor: "#f2ebe3",
        display: "flex",
        flexDirection: "column",
        overflow: "hidden",
        width: "100%",
        height: "100%",
      }}
    >
      {/* 顶部磨砂栏 */}
      <div className={`top-glass-nav ${navCollapsed ? "collapsed" : ""}`}>
        <button className="morandi-glass-btn" onClick={onBack}>
          撤离
        </button>
        <button className="morandi-glass-btn" onClick={() => setElements([])}>
          清空
        </button>
        <button
          className="morandi-glass-btn"
          onClick={() => setShowConnections(!showConnections)}
        >
          {showConnections ? "隐藏连线" : "显示连线"}
        </button>
        <button
          className="morandi-glass-btn"
          onClick={() => setNavCollapsed(true)}
        >
          收起
        </button>
      </div>
      {navCollapsed && (
        <div
          onClick={() => setNavCollapsed(false)}
          style={{
            position: "absolute",
            top: 10,
            left: "50%",
            transform: "translateX(-50%)",
            zIndex: 101,
            background: "rgba(255,255,255,0.5)",
            borderRadius: "50%",
            padding: "5px",
          }}
        >
          <i className="ph ph-caret-down"></i>
        </div>
      )}

      {/* 功能按钮栏 */}
      <div
        style={{
          position: "absolute",
          top: "80px",
          left: "50%",
          transform: navCollapsed
            ? "translate(-50%, -120px)"
            : "translateX(-50%)",
          width: "80%",
          maxWidth: "300px",
          padding: "12px",
          background: "rgba(255, 255, 255, 0.4)",
          backdropFilter: "blur(15px)",
          WebkitBackdropFilter: "blur(15px)",
          borderRadius: "30px",
          display: "flex",
          gap: "10px",
          zIndex: 99,
          opacity: navCollapsed ? 0 : 1,
          transition: "all 0.4s cubic-bezier(0.23, 1, 0.32, 1)",
        }}
      >
        <button
          className="morandi-glass-btn"
          onClick={() => setShowWriteModal(true)}
        >
          书写
        </button>
        <button
          className="morandi-glass-btn"
          onClick={() => alert("选择功能开发中")}
        >
          选择
        </button>
        <button className="morandi-glass-btn" onClick={handleSimulate}>
          推演
        </button>
      </div>

      {/* 大沙盘区域 */}
      <div
        className="sand-grid-container no-scrollbar"
        onTouchStart={(e) => {
          handleTouchStart(e);
          handleSandboxTouchStart(e);
        }}
        onTouchMove={(e) => {
          e.preventDefault();
          handleTouchMove(e);
          handleSandboxTouchMove(e);
        }}
        onTouchEnd={(e) => {
          handleTouchEnd(e);
          handleSandboxTouchEnd(e);
        }}
        onWheel={(e) => {
          e.preventDefault();
          handleWheel(e);
        }}
        onMouseDown={handleSandboxMouseDown}
        onMouseMove={handleSandboxMouseMove}
        onMouseUp={handleSandboxMouseUp}
        onMouseLeave={handleSandboxMouseLeave}
        style={{
          position: "relative",
          overflow: "hidden",
          cursor: isDragging ? "grabbing" : "grab",
          flex: 1,
          background: "#f2ebe3",
        }}
      >
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "200%",
            height: "200%",
            backgroundImage: `radial-gradient(#e8ded6 2px, transparent 2px), radial-gradient(#e8ded6 2px, #f2ebe3 2px)`,
            backgroundSize: `${40 * scale}px ${40 * scale}px`,
            backgroundPosition: `${sandboxPosition.x % (40 * scale)}px ${sandboxPosition.y % (40 * scale)}px`,
            backgroundRepeat: "repeat",
            transform: `translate(${sandboxPosition.x}px, ${sandboxPosition.y}px) scale(${scale})`,
            transformOrigin: "center center",
          }}
        >
          {/* 渲染连接线 */}
          {showConnections &&
            connections.map((conn) => {
              const sourceEl = elements.find((el) => el.id === conn.source);
              const targetEl = elements.find((el) => el.id === conn.target);
              if (sourceEl && targetEl) {
                const sourceX = sourceEl.x / scale + 20;
                const sourceY = sourceEl.y / scale + 20;
                const targetX = targetEl.x / scale + 20;
                const targetY = targetEl.y / scale + 20;

                return (
                  <svg
                    key={conn.id}
                    style={{
                      position: "absolute",
                      left: 0,
                      top: 0,
                      width: "100%",
                      height: "100%",
                      pointerEvents: "none",
                      zIndex: 5,
                    }}
                  >
                    <line
                      x1={sourceX}
                      y1={sourceY}
                      x2={targetX}
                      y2={targetY}
                      stroke="rgba(138, 166, 193, 0.6)"
                      strokeWidth="2"
                      strokeDasharray="5,5"
                    />
                    <circle
                      cx={targetX}
                      cy={targetY}
                      r="5"
                      fill="rgba(138, 166, 193, 0.8)"
                    />
                    <circle
                      cx={sourceX}
                      cy={sourceY}
                      r="5"
                      fill="rgba(214, 114, 75, 0.8)"
                    />
                  </svg>
                );
              }
              return null;
            })}

          {/* 渲染元素 */}
          {simulatedElements.map((el) => (
            <div
              key={el.id}
              className="placed-emoji"
              style={{
                left: el.x / scale,
                top: el.y / scale,
                fontSize: `${32 / scale}px`,
                transform: el.flipped ? "scaleX(-1)" : "none",
                border: isConnecting
                  ? el.id === selectedElement
                    ? "2px solid #D6724B"
                    : "2px dashed #8AA6C1"
                  : "none",
              }}
              onClick={() => {
                if (isConnecting) {
                  completeConnection(el.id);
                } else {
                  handleElementClick(el.id);
                }
              }}
              onTouchMove={(e) => handleDrag(el.id, e)}
              onMouseMove={(e) => e.buttons === 1 && handleDrag(el.id, e)}
            >
              {el.char}
              {selectedElement === el.id && (
                <div className="element-controls">
                  <div
                    className="control-btn flip-btn"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleFlipElement(el.id);
                    }}
                  >
                    翻转
                  </div>
                  <div
                    className="control-btn delete-btn"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleDeleteElement(el.id);
                    }}
                  >
                    删除
                  </div>
                  <div
                    className="control-btn detail-btn"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleElementDetail(el.id);
                    }}
                  >
                    详情
                  </div>
                  <div
                    className="control-btn connect-btn"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleConnectElement(el.id);
                    }}
                  >
                    连接
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* 下方物品栏 */}
      {/* 下方物品栏 */}
      <div
        className="item-bar-bottom no-scrollbar"
        style={{ alignItems: "center" }}
      >
        {inventory.length === 0 ? (
          <div style={{ color: "#999", fontSize: "13px", margin: "auto" }}>
            沙盘空空如也，请点击上方“书写”生成推演组件。
          </div>
        ) : (
          inventory.map((item) => (
            <div
              key={item.id}
              className="emoji-item active-press"
              style={{
                position: "relative",
                opacity: !item.isInfinite && item.quantity <= 0 ? 0.3 : 1,
                border: item.isSpecial ? "2px solid #D6724B" : "none",
                boxShadow: item.isSpecial
                  ? "0 0 8px rgba(214,114,75,0.4)"
                  : "none",
                flexShrink: 0,
              }}
              onClick={() => handleAddInventoryItem(item)}
            >
              <span style={{ fontSize: "28px" }}>{item.emoji}</span>

              {/* 数量角标 */}
              {!item.isInfinite && (
                <div
                  style={{
                    position: "absolute",
                    top: "-5px",
                    right: "-5px",
                    background: "#8AA6C1",
                    color: "white",
                    fontSize: "10px",
                    fontWeight: "bold",
                    borderRadius: "10px",
                    padding: "2px 6px",
                    boxShadow: "0 2px 4px rgba(0,0,0,0.2)",
                  }}
                >
                  {item.quantity}
                </div>
              )}
              {item.isInfinite && (
                <div
                  style={{
                    position: "absolute",
                    top: "-5px",
                    right: "-5px",
                    background: "#A8C8BA",
                    color: "white",
                    fontSize: "10px",
                    fontWeight: "bold",
                    borderRadius: "10px",
                    padding: "2px 6px",
                  }}
                >
                  ∞
                </div>
              )}
            </div>
          ))
        )}
      </div>

      {/* 书写弹窗 */}
      {showWriteModal && (
        <div
          className="modal-overlay"
          onClick={() => !isGenerating && setShowWriteModal(false)}
        >
          <div className="write-modal" onClick={(e) => e.stopPropagation()}>
            <h3 style={{ color: "#5A5F4D" }}>推演背景书写</h3>
            <div className="write-input-container">
              <textarea
                className="write-input"
                value={writeContent}
                onChange={(e) => setWriteContent(e.target.value)}
                placeholder="请输入当前局势背景，例如：曹操大军压境徐州，我方固守下邳城，需要粮草与水军支援..."
                rows={6}
                disabled={isGenerating}
              />
            </div>
            <button
              className="generate-btn"
              onClick={handleGenerateItems}
              disabled={isGenerating}
              style={{
                background: isGenerating
                  ? "#ccc"
                  : "linear-gradient(135deg, #A8C8BA 0%, #8FA99D 100%)",
                color: "white",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                gap: "8px",
              }}
            >
              {isGenerating ? (
                <>
                  <iconify-icon icon="line-md:loading-twotone-loop"></iconify-icon>
                  推演中...
                </>
              ) : (
                "开始推演"
              )}
            </button>
          </div>
        </div>
      )}

      {/* 物品详情弹窗（莫兰迪色温馨风格） */}
      {detailItem && (
        <div
          style={{
            position: "fixed",
            bottom: 0,
            left: 0,
            right: 0,
            background: "#FDFCF8",
            borderTopLeftRadius: "24px",
            borderTopRightRadius: "24px",
            padding: "24px",
            boxShadow: "0 -10px 40px rgba(0,0,0,0.1)",
            zIndex: 1000,
            animation:
              "slideUp 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards",
            borderTop: "1px solid #E8E5D9",
          }}
        >
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "flex-start",
              marginBottom: "16px",
            }}
          >
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: "12px",
              }}
            >
              <div
                style={{
                  width: "50px",
                  height: "50px",
                  background: detailItem.isSpecial ? "#FADBD8" : "#E8F1ED",
                  borderRadius: "14px",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  fontSize: "28px",
                  border: detailItem.isSpecial
                    ? "2px solid #D6724B"
                    : "1px solid #A8C8BA",
                }}
              >
                {detailItem.emoji}
              </div>
              <div>
                <h3
                  style={{
                    margin: 0,
                    fontSize: "18px",
                    color: "#5A5F4D",
                    fontWeight: "bold",
                  }}
                >
                  {detailItem.name}
                </h3>
                <span
                  style={{
                    fontSize: "12px",
                    color: "#8C917B",
                    background: "#F0F0F0",
                    padding: "2px 8px",
                    borderRadius: "10px",
                  }}
                >
                  {detailItem.category}
                </span>
              </div>
            </div>
            <button
              onClick={() => setDetailItem(null)}
              style={{
                background: "none",
                border: "none",
                fontSize: "24px",
                color: "#8C917B",
                cursor: "pointer",
              }}
            >
              ×
            </button>
          </div>

          <div
            style={{
              background: "#F9F7F5",
              padding: "16px",
              borderRadius: "12px",
              marginBottom: "16px",
              borderLeft: "4px solid #D6724B",
            }}
          >
            <div
              style={{
                fontSize: "12px",
                color: "#8C917B",
                fontWeight: "bold",
                marginBottom: "4px",
              }}
            >
              物品图鉴
            </div>
            <div
              style={{
                fontSize: "14px",
                color: "#5A5F4D",
                lineHeight: "1.6",
                fontStyle: "italic",
              }}
            >
              "{detailItem.description}"
            </div>
          </div>

          <div
            style={{
              background: "#F9F7F5",
              padding: "12px 16px",
              borderRadius: "12px",
              borderLeft: "4px solid #A8C8BA",
              display: "flex",
              alignItems: "center",
              gap: "8px",
            }}
          >
            <iconify-icon
              icon="ph:scales-fill"
              style={{ color: "#8FA99D", fontSize: "18px" }}
            ></iconify-icon>
            <span
              style={{
                fontSize: "13px",
                color: "#5A5F4D",
                fontWeight: "bold",
              }}
            >
              实地推演：
            </span>
            <span style={{ fontSize: "13px", color: "#666" }}>
              {detailItem.scale}
            </span>
          </div>
        </div>
      )}

      {/* 模拟推演底部控制卡片 */}
      {showSimulationModal && (
        <div
          style={{
            position: "fixed",
            bottom: 0,
            left: 0,
            right: 0,
            background: "#FDFCF8",
            borderTopLeftRadius: "24px",
            borderTopRightRadius: "24px",
            padding: "24px",
            boxShadow: "0 -10px 40px rgba(0,0,0,0.15)",
            zIndex: 1100,
            animation: "slideUp 0.3s ease-out forwards",
            borderTop: "1px solid #E8E5D9",
            transition: "all 0.3s ease",
            minHeight: simulationModalCollapsed ? "100px" : "auto",
          }}
        >
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "flex-start",
              marginBottom: "16px",
            }}
          >
            <h3
              style={{
                margin: 0,
                fontSize: "18px",
                color: "#5A5F4D",
                fontWeight: "bold",
              }}
            >
              沙盘定格推演
            </h3>
            <div
              style={{
                display: "flex",
                gap: "10px",
                alignItems: "center",
              }}
            >
              <button
                onClick={() =>
                  setSimulationModalCollapsed(!simulationModalCollapsed)
                }
                style={{
                  background: "none",
                  border: "none",
                  fontSize: "18px",
                  color: "#8C917B",
                  cursor: "pointer",
                }}
              >
                {simulationModalCollapsed ? "▲" : "▼"}
              </button>
              <button
                onClick={() => {
                  setShowSimulationModal(false);
                  setCurrentStep(-1);
                }}
                style={{
                  background: "none",
                  border: "none",
                  fontSize: "24px",
                  color: "#8C917B",
                  cursor: "pointer",
                }}
              >
                ×
              </button>
            </div>
          </div>

          {isSimulating ? (
            <div
              style={{
                textAlign: "center",
                padding: "20px",
                color: "#8FA99D",
                display: "flex",
                flexDirection: "column",
                gap: "10px",
                alignItems: "center",
              }}
            >
              <iconify-icon
                icon="line-md:loading-twotone-loop"
                style={{ fontSize: "36px" }}
              ></iconify-icon>
              <span style={{ fontWeight: "bold" }}>
                正在夜观天象，排兵布阵...
              </span>
            </div>
          ) : simulationSteps.length > 0 && currentStep >= 0 ? (
            <div>
              {/* 翻页控制栏 */}
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  marginBottom: simulationModalCollapsed ? "0" : "16px",
                }}
              >
                <button
                  disabled={currentStep <= 0}
                  onClick={() => setCurrentStep((prev) => prev - 1)}
                  style={{
                    padding: "8px 16px",
                    borderRadius: "12px",
                    border: "none",
                    background:
                      currentStep <= 0
                        ? "#E0E0E0"
                        : "linear-gradient(135deg, #A8C8BA 0%, #8FA99D 100%)",
                    color: "white",
                    cursor: currentStep <= 0 ? "not-allowed" : "pointer",
                    fontWeight: "bold",
                  }}
                >
                  ◀ 上一步
                </button>
                <span
                  style={{
                    fontSize: "14px",
                    color: "#8C917B",
                    fontWeight: "bold",
                  }}
                >
                  第 {currentStep + 1} / {simulationSteps.length} 步
                </span>
                <button
                  disabled={currentStep >= simulationSteps.length - 1}
                  onClick={() => setCurrentStep((prev) => prev + 1)}
                  style={{
                    padding: "8px 16px",
                    borderRadius: "12px",
                    border: "none",
                    background:
                      currentStep >= simulationSteps.length - 1
                        ? "#E0E0E0"
                        : "linear-gradient(135deg, #A8C8BA 0%, #8FA99D 100%)",
                    color: "white",
                    cursor:
                      currentStep >= simulationSteps.length - 1
                        ? "not-allowed"
                        : "pointer",
                    fontWeight: "bold",
                  }}
                >
                  下一步 ▶
                </button>
              </div>

              {!simulationModalCollapsed && (
                <>
                  {/* 兵情播报 */}
                  <div
                    style={{
                      background: "#F9F7F5",
                      padding: "16px",
                      borderRadius: "12px",
                      borderLeft: "4px solid #D6724B",
                      marginBottom: "10px",
                    }}
                  >
                    <div
                      style={{
                        fontSize: "12px",
                        color: "#8C917B",
                        fontWeight: "bold",
                        marginBottom: "4px",
                      }}
                    >
                      战况播报
                    </div>
                    <div
                      style={{
                        fontSize: "14px",
                        color: "#5A5F4D",
                        lineHeight: "1.6",
                      }}
                    >
                      {simulationSteps[currentStep].description}
                    </div>
                  </div>

                  {/* 军师点拨 */}
                  <div
                    style={{
                      background: "#F9F7F5",
                      padding: "12px 16px",
                      borderRadius: "12px",
                      borderLeft: "4px solid #A8C8BA",
                      display: "flex",
                      alignItems: "flex-start",
                      gap: "8px",
                    }}
                  >
                    <iconify-icon
                      icon="ph:lightbulb-fill"
                      style={{
                        color: "#8FA99D",
                        fontSize: "18px",
                        marginTop: "2px",
                      }}
                    ></iconify-icon>
                    <div>
                      <div
                        style={{
                          fontSize: "12px",
                          color: "#8C917B",
                          fontWeight: "bold",
                          marginBottom: "4px",
                        }}
                      >
                        军师锐评
                      </div>
                      <div
                        style={{
                          fontSize: "13px",
                          color: "#666",
                          fontStyle: "italic",
                          lineHeight: "1.5",
                        }}
                      >
                        "{simulationSteps[currentStep].reason}"
                      </div>
                    </div>
                  </div>
                </>
              )}
            </div>
          ) : (
            <div
              style={{
                textAlign: "center",
                color: "#999",
                padding: "20px",
              }}
            >
              天机混沌，暂无推演结果
            </div>
          )}
        </div>
      )}
    </div>
  );
};

// T9 情侣空间页面组件


const T13Page = ({
  setIsStarChartOpen,
  setIsButterflyEffectOpen,
  setIsSandTableOpen,
  setIsRelativeOpen,
  setIsFarmOpen,
}) => {
  const { useState } = React;
  const [activeTab, setActiveTab] = useState("game");
  const [showStats, setShowStats] = useState(false);
  const [showMap, setShowMap] = useState(false);
  const [showFortune, setShowFortune] = useState(false);
  const [showEmperor, setShowEmperor] = useState(false);
  const [showGambling, setShowGambling] = useState(false);
  const [showLearning, setShowLearning] = useState(false);
  const [showTraining, setShowTraining] = useState(false);
  const [showStarChart, setShowStarChart] = useState(false);
  const [showButterflyEffect, setShowButterflyEffect] = useState(false);
  const [showSandTable, setShowSandTable] = useState(false);
  const [showRelative, setShowRelative] = useState(false);
  const [showFarm, setShowFarm] = useState(false);

  const getContentByTab = () => {
    switch (activeTab) {
      case "game":
        return T13_GAMES;
      case "tool":
        return T13_TOOLS;
      case "other":
        return T13_OTHERS;
      default:
        return T13_GAMES;
    }
  };

  const currentContent = getContentByTab();

  return (
    <div className="t13-container" style={{ position: "relative", width: "100%", height: "100%", overflow: "hidden" }}>
      {showGambling && (
        <T13GamblingPage onBack={() => setShowGambling(false)} />
      )}
      {showTraining && <T13TrainingPage onBack={() => setShowTraining(false)} />}
      {showStats && <T13StatisticsPage onBack={() => setShowStats(false)} />}
      {showMap && <T13MapPage onBack={() => setShowMap(false)} />}
      {showFortune && <T13FortunePage onBack={() => setShowFortune(false)} />}
      {showEmperor && <T13EmperorPage onBack={() => setShowEmperor(false)} />}
      {showLearning && (
        <T13LearningPage onBack={() => setShowLearning(false)} />
      )}
      {showStarChart && (
        <StarChartPage onBack={() => { setShowStarChart(false); if (setIsStarChartOpen) setIsStarChartOpen(false); }} />
      )}
      {showButterflyEffect && (
        <ButterflyEffectPage onBack={() => { setShowButterflyEffect(false); if (setIsButterflyEffectOpen) setIsButterflyEffectOpen(false); }} />
      )}
      {showSandTable && (
        <SandTablePage onBack={() => { setShowSandTable(false); if (setIsSandTableOpen) setIsSandTableOpen(false); }} />
      )}
      {showRelative && (
        <RelativeDeductionPage onBack={() => { setShowRelative(false); if (setIsRelativeOpen) setIsRelativeOpen(false); }} />
      )}
      {showFarm && (
        <OddFarmPage onBack={() => { setShowFarm(false); if (setIsFarmOpen) setIsFarmOpen(false); }} />
      )}
      <div className="scroll-container hide-scrollbar">
        <T13Header />

        <main className="relative">
          <T13TabSection activeTab={activeTab} setActiveTab={setActiveTab} />

          <div className="pt-2 pb-8 min-h-[500px]">
            {currentContent.map((item) => (
              <div
                key={item.id}
                onClick={() => {
                  if (item.title === "修武扬文" || item.title.includes("修武")) {
                    setShowTraining(true);
                  } else if (item.title === "通灵赌坊" || item.title.includes("赌坊")) {
                    setShowGambling(true);
                  } else if (item.title === "州郡统计年表" || item.title === "金库统计" || item.title.includes("统计")) {
                    setShowStats(true);
                  } else if (item.title === "东汉驿路通" || item.title.includes("驿路通") || item.title.includes("路通")) {
                    setShowMap(true);
                  } else if (item.title === "谶纬小摊" || item.title === "八卦测算" || item.title.includes("测算") || item.title.includes("小摊")) {
                    setShowFortune(true);
                  } else if (item.title === "献帝晴雨表" || item.title.includes("晴雨表") || item.title.includes("献帝") || item.title.includes("皇帝")) {
                    setShowEmperor(true);
                  } else if (item.title === "列星" || item.title === "星象图" || item.title.includes("星")) {
                    setShowStarChart(true);
                    if (setIsStarChartOpen) setIsStarChartOpen(true);
                  } else if (item.title === "蝴蝶效应" || item.title.includes("效应")) {
                    setShowButterflyEffect(true);
                    if (setIsButterflyEffectOpen) setIsButterflyEffectOpen(true);
                  } else if (item.title === "沙盘模拟器" || item.title === "沙盘推演" || item.title.includes("沙盘")) {
                    setShowSandTable(true);
                    if (setIsSandTableOpen) setIsSandTableOpen(true);
                  } else if (item.title === "相对演绎" || item.actionId === "re_deduction") {
                    setShowRelative(true);
                    if (setIsRelativeOpen) setIsRelativeOpen(true);
                  } else if (item.title === "古怪农场" || item.title.includes("农场")) {
                    setShowFarm(true);
                    if (setIsFarmOpen) setIsFarmOpen(true);
                  } else if (item.title === "学习系统" || item.title.includes("学习")) {
                    setShowLearning(true);
                  }
                }}
              >
                <T13GameCard item={item} />
              </div>
            ))}
          </div>
        </main>
      </div>

      <T13BottomNav />
    </div>
  );
};
const SlotMachineSelector = ({ options, onSelect, onClose }) => {
  const [selectedIndex, setSelectedIndex] = React.useState(0);
  const itemHeight = 60; // 每一项的高度，需要和 CSS 高度对应

  const handleScroll = (e) => {
    const scrollTop = e.target.scrollTop;
    // 减去顶部内边距60px，因为容器有padding: "60px 0"
    const adjustedScrollTop = Math.max(0, scrollTop - 60);
    const index = Math.round(adjustedScrollTop / itemHeight);
    if (index !== selectedIndex && index >= 0 && index < options.length) {
      setSelectedIndex(index);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4 animate-fadeIn">
      <div className="bg-[#FDFCF8] rounded-2xl w-full max-w-sm p-6 shadow-2xl flex flex-col items-center">
        <h3 className="text-[#5A5F4D] text-lg font-bold mb-4 tracking-widest">
          向下滑动拨拨盘
        </h3>

        <div
          className="relative w-full h-[180px] overflow-hidden rounded-xl border border-[#EAEAEA] bg-[#F9F7F5] shadow-inner"
          style={{ perspective: "800px" }}
        >
          {/* 选中框的高亮遮罩条 */}
          <div className="absolute top-[60px] left-0 w-full h-[60px] border-t-2 border-b-2 border-[#89A89A] bg-[#89A89A]/10 pointer-events-none z-20"></div>

          <div
            className="w-full h-full overflow-y-auto no-scrollbar snap-y snap-mandatory relative z-10"
            onScroll={handleScroll}
            style={{ scrollBehavior: "smooth", padding: "60px 0" }}
          >
            {options.map((opt, i) => {
              const distance = i - selectedIndex;
              const absDistance = Math.abs(distance);
              // 根据距离计算 3D 变换参数
              const scale = Math.max(0.7, 1 - absDistance * 0.1);
              const opacity = Math.max(0.2, 1 - absDistance * 0.5);
              const rotateX = distance * -25;
              const translateZ = absDistance * -30;

              return (
                <div
                  key={i}
                  className="h-[60px] w-full flex flex-col items-center justify-center snap-center transition-all duration-150"
                  style={{
                    transform: `rotateX(${rotateX}deg) translateZ(${translateZ}px) scale(${scale})`,
                    opacity: opacity,
                    transformOrigin: "center center -60px",
                  }}
                >
                  <div className="font-bold text-[#5A5F4D] truncate w-full text-center px-4">
                    {opt.title}
                  </div>
                  <div className="text-xs text-[#8C917B] truncate w-full text-center px-4 mt-1">
                    {opt.text}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        <div className="flex gap-4 mt-6 w-full">
          <button
            onClick={onClose}
            className="flex-1 py-3 rounded-xl border border-[#D4AB90] text-[#D4AB90] font-bold active:scale-95 transition-transform"
          >
            取消
          </button>
          <button
            onClick={() => onSelect(options[selectedIndex])}
            className="flex-1 py-3 rounded-xl bg-[#E8C3A8] text-white font-bold shadow-md active:scale-95 transition-transform"
          >
            择定此卷
          </button>
        </div>
      </div>
    </div>
  );
};

// ==================== 相对演绎页面组件 ====================
const RelativeDeductionPage = ({ onBack }) => {
  const { useState, useEffect } = React;
  const [isOpen, setIsOpen] = useState(false);
  const [isFlipped, setIsFlipped] = useState(false);

  // --- 新增状态 ---
  const [showContentMenu, setShowContentMenu] = useState(false);
  const [showActorMenu, setShowActorMenu] = useState(false);

  const [allActors, setAllActors] = useState([]);
  const [selectedActors, setSelectedActors] = useState([]);

  const [contentOptions, setContentOptions] = useState([]);
  const [showWheel, setShowWheel] = useState(false);
  const [showCustomInput, setShowCustomInput] = useState(false);
  const [customText, setCustomText] = useState("");

  const [selectedContent, setSelectedContent] = useState(null);
  const [isLoadingContent, setIsLoadingContent] = useState(false);

  // --- 新增：AI 剧本生成与播放状态 ---
  const [scriptPages, setScriptPages] = useState([]); // 存储生成的剧本页 [{ lines: [], choices: [] }]
  const [currentScriptPage, setCurrentScriptPage] = useState(0); // 当前正在查看的页码
  const [isGeneratingScript, setIsGeneratingScript] = useState(false); // 生成中状态

  // --- 场景配置状态 ---
  const [sceneConfig, setSceneConfig] = useState({
    mainSprites: [], // {id, name, url}
    activeMainId: null,
    enableOtherSprites: false,
    otherSprites: [], // {id, name, url}
    activeOtherId: null,
    backgrounds: [], // {id, name, url}
    activeBgId: null,
  });

  // --- 加载角色 ---
  useEffect(() => {
    const loadActors = async () => {
      let chars = [];
      try {
        if (window.chatCharacterStore) {
          chars = await window.chatCharacterStore.getAll();
        } else {
          chars = JSON.parse(localStorage.getItem("t8_chat_list") || "[]");
        }
        // 过滤掉群组和装饰
        const validChars = chars.filter(
          (c) => !String(c.id).startsWith("group") && c.type !== "decor",
        );
        setAllActors(validChars);
      } catch (e) {
        console.error("加载角色失败:", e);
      }
    };
    loadActors();
  }, []);

  // --- 新增：调用 AI 生成剧本逻辑 ---
  const handleGenerateScript = async (userChoice = "") => {
    if (!selectedContent || selectedActors.length === 0) {
      alert("请先选定剧本（演绎内容）并点拨将领（演绎者）！");
      return;
    }
    if (isGeneratingScript) return;

    setIsGeneratingScript(true);

    try {
      // 1. 获取世界书设定
      const worldContext = window.getWorldBookContext
        ? await window.getWorldBookContext()
        : "无特定设定";

      // 2. 获取用户身份设定
      let userContext = "";
      try {
        const savedPersonas = JSON.parse(
          localStorage.getItem("user_personas") || "[]",
        );
        const activeId = localStorage.getItem("active_persona_id");
        if (activeId) {
          const activeUser = savedPersonas.find((p) => p.id == activeId);
          if (activeUser) {
            userContext = `【用户/导演设定】\n姓名:${activeUser.name}\n性格:${activeUser.personality || "未知"}\n背景:${activeUser.background || "无"}`;
          }
        }
      } catch (e) {}

      // 3. 获取演员设定
      const actorsInfo = selectedActors
        .map(
          (a) =>
            `【演员：${a.name}】性格：${(a.profile && a.profile.personality) || "未知"}；说话风格：${(a.profile && a.profile.style) || "未知"}`,
        )
        .join("\n");

      // 4. 构建上下文记忆（把前面生成的几页作为前情提要）
      let previousStory = "";
      if (scriptPages.length > 0) {
        // 为了节省 token，只取最近的两页作为上下文
        const recentPages = scriptPages.slice(-2);
        previousStory =
          "【前情提要】\n" +
          recentPages
            .map((page) =>
              page.lines
                .map((line) =>
                  line.type === "narration"
                    ? `旁白：${line.text}`
                    : `${line.speaker}：${line.text}`,
                )
                .join("\n"),
            )
            .join("\n\n");
        if (userChoice) {
          previousStory += `\n\n【最新剧情走向】：观众/导演选择了 -> "${userChoice}"\n请顺着这个选择继续往下演。`;
        }
      }

      // 【新增】：提取当前用户已上传的立绘和背景名称，告诉AI有哪些可用
      const availableBgs =
        sceneConfig.backgrounds.map((b) => b.name).join("、") || "无特定背景";
      const availableSprites =
        [...sceneConfig.mainSprites, ...sceneConfig.otherSprites]
          .map((s) => s.name)
          .join("、") || "无特定立绘";

      // 5. 提示词构建
      const sysPrompt =
        "你是一个深谙东汉历史、极具幽默感且脑洞大开的顶级视觉小说剧本构作。你擅长结合世界观设定和特定文风，写出令人惊艳的Galgame剧本。";
      const userPrompt = `
                          【世界观大背景】
                          ${worldContext}

                          ${userContext}

                          【演员阵容与人设】（他们说话必须严格符合此设定！）
                          ${actorsInfo}

                          【当前可用的背景资源标签】：${availableBgs}
                          【当前可用的立绘表情标签】：${availableSprites}

                          【本次演绎的原作基础】
                          篇名：${selectedContent.title}
                          原文：${selectedContent.text}

                          ${previousStory}

                          【任务与要求】
                          1. 请基于以上信息，${scriptPages.length === 0 ? "作为剧本的开篇，开始" : "顺着前情提要继续"}生成一段约 500-700 字的魔改演绎剧本。
                          2. 剧情要有趣、有梗，背景必须基于开启的世界书设定。
                          3. 必须在剧本末尾，给出现场观众/导演可以决定的 2 到 3 个“下一步剧情走向”选项。
                          4. 必须严格输出纯 JSON 格式！不要包裹 \`\`\`json，直接输出以 { 开头，} 结尾的 JSON 对象。

                          【JSON 输出格式严格要求】(请在每一句 dialogue 增加 emotion 和 bgKeyword 字段)
                          {
                            "lines": [
                              {
                                "type": "narration",
                                "text": "（旁白内容）",
                                "bgKeyword": "根据剧情氛围，从【当前可用的背景资源标签】中选一个最符合的填入，没有填空"
                              },
                              {
                                "type": "dialogue",
                                "speaker": "演员姓名",
                                "text": "台词内容",
                                "emotion": "根据语气，从【当前可用的立绘表情标签】中选一个最符合的填入",
                                "bgKeyword": "同上"
                              }
                            ],
                            "choices": [
                              "走向选项1",
                              "走向选项2"
                            ]
                          }
                        `;

      // 6. 调用 LLM
      if (window.sendToLLM) {
        window.sendToLLM(
          [
            { role: "system", content: sysPrompt },
            { role: "user", content: userPrompt },
          ],
          null,
          (reply) => {
            try {
              const cleanJson = reply.replace(/```json|```/g, "").trim();
              const data = JSON.parse(cleanJson);

              if (data.lines && data.choices) {
                setScriptPages((prev) => {
                  const newPages = [...prev, data];
                  setCurrentScriptPage(newPages.length - 1); // 自动跳到最新一页
                  return newPages;
                });
              } else {
                throw new Error("JSON 缺少 lines 或 choices 字段");
              }
            } catch (e) {
              console.error("剧本解析失败:", e, reply);
              alert("剧本生成出现了分歧，演员们忘词了，请重试！");
            } finally {
              setIsGeneratingScript(false);
            }
          },
          (err) => {
            console.error(err);
            alert("灵感枯竭，网络不通，请检查 API 配置！");
            setIsGeneratingScript(false);
          },
        );
      } else {
        alert("未配置 API 接口，请前往设置配置！");
        setIsGeneratingScript(false);
      }
    } catch (error) {
      console.error(error);
      setIsGeneratingScript(false);
    }
  };

  // --- 调用 AI 生成内容 ---
  const fetchContentOptions = async (type) => {
    setShowContentMenu(false);
    setIsLoadingContent(true);
    setShowWheel(false);

    try {
      const worldContext = window.getWorldBookContext
        ? await window.getWorldBookContext()
        : "";
      const actorNames = selectedActors.map((a) => a.name).join("、");
      const actorPrompt = actorNames
        ? `请结合以下待演绎角色的特点进行综合分析来挑选合适的${type}：${actorNames}。`
        : "请根据经典东汉及先秦风格进行选择。";

      const sysPrompt =
        "你是一个深谙中国古代文学（特别是东汉及先秦文学）的国学大师与剧本构作。";
      const userPrompt = `
                          【世界设定】
                          ${worldContext}

                          【任务】
                          请为"相对演绎"生成 5 到 7 个东汉时期或东汉以前的${type}片段（必须是东汉及以前的作品，如《诗经》、《楚辞》、汉乐府、古诗十九首、先秦诸子散文等）。
                          ${actorPrompt}
                          要求：
                          1. 严格确保时代在东汉或东汉之前，绝对不能出现唐宋及以后的作品！
                          2. 每个选项包含：title (标题+作者), text (具体内容片段或全诗)。
                          3. 必须严格返回纯 JSON 数组格式，不要包含 Markdown 标记（如 \`\`\`json ），直接以 [ 开头，] 结尾。

                          返回格式示例：
                          [
                            { "title": "《关雎》- 诗经", "text": "关关雎鸠，在河之洲。窈窕淑女，君子好逑。" }
                          ]
                        `;

      if (window.sendToLLM) {
        window.sendToLLM(
          [
            { role: "system", content: sysPrompt },
            { role: "user", content: userPrompt },
          ],
          null,
          (reply) => {
            try {
              const cleanJson = reply.replace(/```json|```/g, "").trim();
              const data = JSON.parse(cleanJson);
              if (Array.isArray(data) && data.length > 0) {
                setContentOptions(data);
                setShowWheel(true);
              } else {
                throw new Error("返回数据非数组或为空");
              }
            } catch (e) {
              console.error("解析古文/古诗失败:", e, reply);
              alert("浩瀚古籍检索失败，请重试。");
            } finally {
              setIsLoadingContent(false);
            }
          },
          (err) => {
            console.error(err);
            alert("请求失败，请检查 API 设置");
            setIsLoadingContent(false);
          },
        );
      } else {
        alert("未配置 API 接口，请前往设置配置！");
        setIsLoadingContent(false);
      }
    } catch (e) {
      console.error(e);
      setIsLoadingContent(false);
    }
  };

  const handleOpenBook = () => {
    setIsOpen(true);
    setTimeout(() => setIsFlipped(true), 800);
  };

  return (
    <div className="fixed inset-0 z-[600] bg-[#F9F7F5] flex flex-col fade-in">
      <div className="t11-nav">
        <div className="back-btn" onClick={onBack}>
          <i className="ph ph-caret-left" style={{ fontSize: "24px" }}></i>
        </div>
        <div className="title">相对演绎</div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-6 relative">
        {!isFlipped ? (
          <div className="re-book-container">
            <div
              className={`re-book ${isOpen ? "open" : ""}`}
              onClick={handleOpenBook}
            >
              <div className="re-book-cover">
                <h4>相对演绎</h4>
                <div style={{ marginTop: "20px", opacity: 0.6 }}>
                  <i className="ph ph-leaf-fill"></i>
                </div>
              </div>
              <div className="re-book-page"></div>
            </div>
          </div>
        ) : (
          <div className="w-full h-full flex flex-col animate-slide-up">
            {/* 顶部操作按钮栏 */}
            <div className="flex justify-between gap-2 mb-6 relative">
              {/* 演绎内容 按钮与下拉 */}
              <div className="flex-1 relative">
                <button
                  className="duo-btn w-full duo-btn-green"
                  onClick={() => {
                    setShowContentMenu(!showContentMenu);
                    setShowActorMenu(false);
                  }}
                >
                  <div className="truncate px-1">
                    {selectedContent ? "换剧本" : "演绎内容"}
                  </div>
                </button>

                {showContentMenu && (
                  <div className="absolute top-[3.2rem] left-0 w-full bg-white rounded-xl shadow-lg border border-[#EAEAEA] overflow-hidden z-20 animate-slide-up">
                    <div
                      className="p-3 text-sm text-[#5A5F4D] hover:bg-[#F2F7F4] cursor-pointer text-center font-bold"
                      onClick={() => fetchContentOptions("古文")}
                    >
                      典籍古文
                    </div>
                    <div className="border-b border-gray-100"></div>
                    <div
                      className="p-3 text-sm text-[#5A5F4D] hover:bg-[#F2F7F4] cursor-pointer text-center font-bold"
                      onClick={() => fetchContentOptions("古诗")}
                    >
                      汉乐古诗
                    </div>
                    <div className="border-b border-gray-100"></div>
                    <div
                      className="p-3 text-sm text-[#5A5F4D] hover:bg-[#F2F7F4] cursor-pointer text-center font-bold"
                      onClick={() => {
                        setShowContentMenu(false);
                        setShowCustomInput(true);
                      }}
                    >
                      自定义
                    </div>
                  </div>
                )}
              </div>

              {/* 演绎者 按钮 */}
              <div className="flex-1 relative">
                <button
                  className="duo-btn w-full duo-btn-green"
                  onClick={() => {
                    setShowActorMenu(true);
                    setShowContentMenu(false);
                  }}
                >
                  {selectedActors.length > 0
                    ? `优伶(${selectedActors.length})`
                    : "点兵点将"}
                </button>
              </div>

              {/* 开始演绎 按钮 */}
              <button
                className="duo-btn flex-1"
                style={{
                  backgroundColor: "#E8C3A8",
                  color: "white",
                  borderBottomColor: "#D4AB90",
                }}
                onClick={() => handleGenerateScript()}
                disabled={isGeneratingScript}
              >
                {isGeneratingScript
                  ? "构思剧本中..."
                  : scriptPages.length > 0
                    ? "重新演绎"
                    : "开始演绎"}
              </button>
            </div>

            {/* 预览舞台 */}
            <div className="w-full h-[calc(100vh-200px)] bg-white rounded-3xl p-6 border-2 border-[#EAEAEA] shadow-inner flex flex-col overflow-hidden relative">
              {/* 左翻页按钮 */}
              {scriptPages.length > 1 && currentScriptPage > 0 && (
                <button
                  onClick={() => setCurrentScriptPage((prev) => prev - 1)}
                  className="absolute left-2 top-1/2 -translate-y-1/2 w-8 h-8 bg-gray-100 rounded-full flex items-center justify-center text-gray-500 shadow-md z-10 active:scale-90 opacity-70 hover:opacity-100"
                >
                  <i className="ph-bold ph-caret-left"></i>
                </button>
              )}

              {/* 右翻页按钮 */}
              {scriptPages.length > 1 &&
                currentScriptPage < scriptPages.length - 1 && (
                  <button
                    onClick={() => setCurrentScriptPage((prev) => prev + 1)}
                    className="absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 bg-gray-100 rounded-full flex items-center justify-center text-gray-500 shadow-md z-10 active:scale-90 opacity-70 hover:opacity-100"
                  >
                    <i className="ph-bold ph-caret-right"></i>
                  </button>
                )}

              {/* 如果正在生成且没有历史数据，显示大 Loading */}
              {isGeneratingScript && scriptPages.length === 0 ? (
                <div className="flex-1 flex flex-col items-center justify-center opacity-80 animate-pulse">
                  <iconify-icon
                    icon="line-md:loading-twotone-loop"
                    style={{
                      fontSize: "60px",
                      color: "#89A89A",
                      marginBottom: "20px",
                    }}
                  ></iconify-icon>
                  <h3 className="text-[#5A5F4D] text-xl font-bold tracking-widest">
                    大幕拉开，好戏酝酿中...
                  </h3>
                </div>
              ) : scriptPages.length > 0 ? (
                /* 渲染生成的剧本 */
                <div className="w-full text-left flex flex-col h-full overflow-y-auto no-scrollbar px-6">
                  <h3 className="text-[#5A5F4D] text-lg font-bold mb-4 border-b border-[#EAEAEA] pb-2 text-center font-serif">
                    {selectedContent.title} - 第 {currentScriptPage + 1} 幕
                  </h3>

                  <div className="flex-1">
                    {scriptPages[currentScriptPage].lines.map((line, idx) => {
                      if (line.type === "narration") {
                        return (
                          <div
                            key={idx}
                            className="bg-[#F9F7F5] border border-[#EAEAEA] p-4 text-center text-[#8C917B] rounded-xl my-4 shadow-sm font-serif leading-relaxed text-sm"
                          >
                            {line.text}
                          </div>
                        );
                      } else {
                        // 匹配演员头像颜色
                        const actor = selectedActors.find(
                          (a) => a.name === line.speaker,
                        );
                        const avatarColor = actor?.avatarColor || "#D4AB90";

                        return (
                          <div key={idx} className="mb-4 flex flex-col">
                            <div className="flex items-center gap-2 mb-1">
                              <div
                                className="w-5 h-5 rounded-full text-white flex items-center justify-center text-[10px] font-bold shadow-inner"
                                style={{ backgroundColor: avatarColor }}
                              >
                                {line.speaker[0]}
                              </div>
                              <span className="text-xs font-bold text-[#89A89A]">
                                {line.speaker}
                              </span>
                            </div>
                            <div className="text-[#5A5F4D] text-[15px] leading-relaxed pl-7">
                              {line.text}
                            </div>
                          </div>
                        );
                      }
                    })}
                  </div>

                  {/* 如果是最新一页，显示分支选项 */}
                  {currentScriptPage === scriptPages.length - 1 && (
                    <div className="mt-8 pt-4 border-t border-dashed border-[#C9C9C1]">
                      <div className="text-xs text-center text-[#8C917B] mb-3">
                        —— 请选择接下来的剧情走向 ——
                      </div>
                      <div className="flex flex-col gap-3">
                        {scriptPages[currentScriptPage].choices.map(
                          (choice, cIdx) => (
                            <button
                              key={cIdx}
                              onClick={() => handleGenerateScript(choice)}
                              disabled={isGeneratingScript}
                              className="w-full text-left bg-white border-2 border-[#E8C3A8] text-[#5A5F4D] p-3 rounded-xl text-sm font-bold active:scale-[0.98] transition-transform shadow-sm hover:bg-[#FDFCF8] disabled:opacity-50"
                            >
                              {isGeneratingScript ? "续写中..." : choice}
                            </button>
                          ),
                        )}
                      </div>
                    </div>
                  )}
                </div>
              ) : selectedContent ? (
                /* 原作预览模式（剧本生成前） */
                <div className="w-full text-left flex flex-col h-full overflow-y-auto no-scrollbar">
                  <div className="flex-1">
                    <h3 className="text-[#5A5F4D] text-xl font-bold mb-3 border-b border-[#EAEAEA] pb-3 tracking-widest text-center font-serif">
                      {selectedContent.title}
                    </h3>
                    <p className="text-[#5A5F4D] text-base leading-loose whitespace-pre-wrap font-serif mt-4 indent-8">
                      {selectedContent.text}
                    </p>
                  </div>

                  <div className="mt-8 pt-5 border-t border-dashed border-[#C9C9C1]">
                    <h4 className="text-xs font-bold text-[#89A89A] mb-3 tracking-widest">
                      <i className="ph-fill ph-users mr-1"></i> 今日班底：
                    </h4>
                    <div className="flex gap-2 flex-wrap">
                      {selectedActors.length > 0 ? (
                        selectedActors.map((a) => (
                          <span
                            key={a.id}
                            className="bg-[#F2F7F4] text-[#5A8F6D] px-3 py-1.5 rounded-full text-xs font-bold shadow-sm border border-[#E4EFE9] flex items-center gap-1"
                          >
                            <div
                              className="w-4 h-4 rounded-full bg-black text-white flex items-center justify-center text-[8px]"
                              style={{
                                backgroundColor: a.avatarColor || "#ccc",
                              }}
                            >
                              {a.name[0]}
                            </div>
                            {a.name}
                          </span>
                        ))
                      ) : (
                        <span className="text-xs text-gray-400 italic">
                          尚未定角...
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              ) : (
                /* 空白初始页 */
                <div className="flex-1 flex flex-col items-center justify-center opacity-80">
                  <div
                    style={{
                      fontSize: "60px",
                      marginBottom: "20px",
                      filter: "drop-shadow(0 4px 6px rgba(0,0,0,0.1))",
                    }}
                  >
                    🎭
                  </div>
                  <h3 className="text-[#5A5F4D] text-xl font-bold mb-4 tracking-widest">
                    戏说东汉
                  </h3>
                  <p className="text-[#8C917B] text-sm leading-relaxed text-center px-4">
                    翻开书页，命运的齿轮已为你选定。
                    <br />
                    请于上方择取<b>剧本</b>与<b>优伶</b>，
                    <br />
                    共同完成一场"相对"的演出。
                  </p>
                </div>
              )}
            </div>
          </div>
        )}

        {/* ===== 各类弹窗 ===== */}

        {/* 1. 自定义输入弹窗 */}
        {showCustomInput && (
          <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4 animate-fadeIn">
            <div className="bg-[#FDFCF8] rounded-2xl w-full max-w-sm p-6 shadow-2xl flex flex-col">
              <h3 className="text-[#5A5F4D] text-lg font-bold mb-4">
                挥毫泼墨 (自定义剧本)
              </h3>
              <input
                type="text"
                className="w-full p-3 border border-[#EAEAEA] rounded-xl bg-white text-[#5A5F4D] outline-none mb-3 font-bold"
                placeholder="赐一个响亮的篇名..."
                onChange={(e) => {
                  // 利用 dataset 暂存 title 供确认时使用
                  e.target.dataset.title = e.target.value;
                }}
              />
              <textarea
                className="w-full h-32 p-3 border border-[#EAEAEA] rounded-xl bg-white text-[#5A5F4D] outline-none resize-none mb-6 leading-relaxed"
                placeholder="写下你想让他们演绎的文段..."
                value={customText}
                onChange={(e) => setCustomText(e.target.value)}
              />
              <div className="flex gap-4 w-full">
                <button
                  onClick={() => setShowCustomInput(false)}
                  className="flex-1 py-3 rounded-xl border border-[#D4AB90] text-[#D4AB90] font-bold active:scale-95 transition-transform"
                >
                  拂袖而去
                </button>
                <button
                  onClick={(e) => {
                    const titleInput =
                      e.target.parentElement.parentElement.querySelector(
                        "input",
                      );
                    const tTitle = titleInput.dataset.title || "佚名手稿";
                    if (customText.trim()) {
                      setSelectedContent({
                        title: tTitle,
                        text: customText.trim(),
                      });
                      setShowCustomInput(false);
                    } else {
                      alert("不可交白卷！");
                    }
                  }}
                  className="flex-1 py-3 rounded-xl bg-[#E8C3A8] text-white font-bold shadow-md active:scale-95 transition-transform"
                >
                  落笔定稿
                </button>
              </div>
            </div>
          </div>
        )}

        {/* 2. 演绎者选择弹窗 */}
        {showActorMenu && (
          <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4 animate-fadeIn">
            <div className="bg-[#FDFCF8] rounded-2xl w-full max-w-sm p-6 shadow-2xl flex flex-col max-h-[75vh]">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-[#5A5F4D] text-lg font-bold tracking-widest">
                  钦定优伶
                </h3>
                <span className="text-xs text-[#89A89A] bg-[#F2F7F4] px-2 py-1 rounded-md font-bold">
                  已选 {selectedActors.length} 人
                </span>
              </div>

              <div className="flex-1 overflow-y-auto no-scrollbar flex flex-col gap-3 py-2">
                {allActors.length > 0 ? (
                  allActors.map((actor) => (
                    <label
                      key={actor.id}
                      className={`flex items-center gap-3 p-3 rounded-xl border transition-all cursor-pointer ${
                        selectedActors.some((a) => a.id === actor.id)
                          ? "bg-[#F2F7F4] border-[#89A89A] shadow-sm"
                          : "bg-white border-[#EAEAEA]"
                      }`}
                    >
                      <input
                        type="checkbox"
                        className="w-5 h-5 accent-[#89A89A] rounded-sm"
                        checked={selectedActors.some((a) => a.id === actor.id)}
                        onChange={(e) => {
                          if (e.target.checked)
                            setSelectedActors([...selectedActors, actor]);
                          else
                            setSelectedActors(
                              selectedActors.filter((a) => a.id !== actor.id),
                            );
                        }}
                      />
                      <div
                        className="w-10 h-10 rounded-full flex items-center justify-center text-white text-sm font-bold shadow-inner"
                        style={{
                          backgroundColor: actor.avatarColor || "#ccc",
                        }}
                      >
                        {(actor.name && actor.name[0]) || "?"}
                      </div>
                      <div className="flex flex-col">
                        <span className="text-[#5A5F4D] font-bold">
                          {actor.name}
                        </span>
                        <span className="text-xs text-[#8C917B] truncate max-w-[150px]">
                          {(actor.profile && actor.profile.personality) ||
                            "此人极度神秘"}
                        </span>
                      </div>
                    </label>
                  ))
                ) : (
                  <div className="text-center text-gray-400 py-10 text-sm">
                    楼里空空如也，请先在传讯中添加名士。
                  </div>
                )}
              </div>

              <button
                onClick={() => setShowActorMenu(false)}
                className="mt-5 w-full py-3 rounded-xl bg-[#89A89A] text-white font-bold shadow-lg active:scale-95 transition-transform tracking-widest"
              >
                结班
              </button>
            </div>
          </div>
        )}

        {/* 3. AI 加载动画 */}
        {isLoadingContent && (
          <div className="fixed inset-0 bg-black/60 z-[100] flex flex-col items-center justify-center p-4">
            <div className="w-16 h-16 bg-white/10 rounded-2xl flex items-center justify-center mb-4 shadow-[0_0_15px_rgba(232,195,168,0.3)] border border-white/20">
              <iconify-icon
                icon="line-md:loading-twotone-loop"
                style={{ fontSize: "40px", color: "#E8C3A8" }}
              ></iconify-icon>
            </div>
            <div className="text-white tracking-widest font-bold font-serif text-lg">
              正在翻阅浩瀚古籍...
            </div>
          </div>
        )}

        {/* 4. 滚轮选择器 (老虎机) */}
        {showWheel && contentOptions.length > 0 && (
          <SlotMachineSelector
            options={contentOptions}
            onSelect={(opt) => {
              setSelectedContent(opt);
              setShowWheel(false);
            }}
            onClose={() => setShowWheel(false)}
          />
        )}
      </div>
    </div>
  );
};

// ==================== 古怪农场页面组件 ====================
const OddFarmPage = ({ onBack }) => {
  const { useState, useEffect } = React;

  // --- 新增：金钱、订单和果实名称映射 ---
  const [coins, setCoins] = useState(() =>
    parseInt(localStorage.getItem("farm_coins") || "500"),
  );
  const [orders, setOrders] = useState([]);
  const [showOrderModal, setShowOrderModal] = useState(false);
  const [isGeneratingOrders, setIsGeneratingOrders] = useState(false);

  const FRUIT_NAMES = {
    1: "看似普通的麦子",
    2: "奇怪的笠形坚果",
    3: "被迫营业的连体薯",
    4: "凑数出来的花团",
    5: "KPI附体大萝卜",
    6: "强颜欢笑的限时玉米",
  };

  // 持久化金钱
  useEffect(() => {
    localStorage.setItem("farm_coins", coins.toString());
  }, [coins]);

  // 订单倒计时逻辑
  useEffect(() => {
    if (orders.length === 0) return;
    const timer = setInterval(() => {
      setOrders((prev) =>
        prev
          .map((o) => ({ ...o, timeLeft: o.timeLeft - 1 }))
          .filter((o) => o.timeLeft > 0),
      );
    }, 1000);
    return () => clearInterval(timer);
  }, [orders]);

  // --- 新增：调用 AI 生成订单 ---
  const handleGenerateOrders = async () => {
    setShowOrderModal(true);
    if (orders.length >= 5) return; // 最多保持5个订单
    setIsGeneratingOrders(true);

    try {
      const worldContext = window.getWorldBookContext
        ? await window.getWorldBookContext()
        : "无特定背景设定";

      let allChars = [];
      if (window.chatCharacterStore) {
        allChars = await window.chatCharacterStore.getAll();
      } else {
        allChars = JSON.parse(localStorage.getItem("t8_chat_list") || "[]");
      }
      const validChars = allChars.filter(
        (c) => !String(c.id).startsWith("group") && c.type !== "decor",
      );
      const charsInfo = validChars
        .slice(0, 5)
        .map(
          (c) =>
            `【${c.name}】性格：${c.profile?.personality || "无"}，说话风格：${c.profile?.style || "无"}`,
        )
        .join("\n");

      const sysPrompt = "你是一个东汉末年背景下的古风奇幻农场订单生成器。";
      const userPrompt = `
                      【世界设定】
                      ${worldContext}

                      【可能来采购的熟人】
                      ${charsInfo}

                      【农场可供果实清单】
                      ID: 1 - 看似普通的麦子：看似普通的麦子，实际也是普通的麦子。但不同的人总会宣扬它有不同的功效
                      ID: 2 - 奇怪的笠形坚果：外壳坚硬如铁，内部也坚硬如铁。何尝不是一种表里如一呢？
                      ID: 3 - 被迫营业的连体薯：本来说好要分家的番薯，却被绣衣楼的某人强行粘在一起营业。
                      ID: 4 - 凑数出来的花团：看起来乖巧实际完全没用的果实。据说最初培育人是个杨桃爱好者，还是《植株大战五斗米》的忠实玩家......
                      ID: 5 - KPI附体大萝卜：袁氏家主，绣衣楼副官力荐美食！指标完成全靠它，不赶DDL!
                      ID: 6 - 强颜欢笑的限时玉米：永远在倒计时里焦虑，生怕自己超时成熟。

                      【任务】
                      请生成3到5个农场作物的采购订单。订货人可以是上述【熟人】之一（语气必须严格符合其人设），也可以是五湖四海随机生成的东汉NPC（如：洛阳贵妇、幽州散仙、南蛮商人等）。
                      要求：
                      1. 描述(desc)必须是对所求果实的生动描述、具体或抽象的用途，充满网感或古风魔幻感（如"拿去炼丹急用，家人们谁懂啊"、"主公近日气血亏虚，需此物大补"）。
                      2. 严格返回纯 JSON 数组，不能有 Markdown 代码块符号 \`\`\`json 等，直接以 [ 开头，] 结尾。

                      JSON 格式要求：
                      [
                        {
                          "buyer": "订货人名字",
                          "isNpc": true或false,
                          "itemId": 在1到6中选一个数字,
                          "itemName": "对应的果实名称",
                          "desc": "对果实的描述及用途，20-40字以内",
                          "quantity": 1到3的整数,
                          "price": 50到300之间的整数,
                          "timeLeft": 60到300的整数(秒)
                        }
                      ]
                      `;

      if (window.sendToLLM) {
        window.sendToLLM(
          [
            { role: "system", content: sysPrompt },
            { role: "user", content: userPrompt },
          ],
          null,
          (reply) => {
            try {
              const cleanJson = reply.replace(/```json|```/g, "").trim();
              const data = JSON.parse(cleanJson);
              if (Array.isArray(data)) {
                const newOrders = data.map((o, idx) => ({
                  ...o,
                  id: Date.now() + idx,
                }));
                setOrders((prev) => [...prev, ...newOrders].slice(0, 6));
              }
            } catch (e) {
              console.error("订单解析失败:", e, reply);
            } finally {
              setIsGeneratingOrders(false);
            }
          },
          (err) => {
            console.error("生成订单失败:", err);
            setIsGeneratingOrders(false);
          },
        );
      } else {
        alert("请先在设置中配置API");
        setIsGeneratingOrders(false);
      }
    } catch (e) {
      console.error(e);
      setIsGeneratingOrders(false);
    }
  };

  // --- 新增：果实详情弹窗 ---
  const [showFruitDetail, setShowFruitDetail] = useState(false);
  const [selectedFruit, setSelectedFruit] = useState(null);

  // 果实简介
  const FRUIT_DESCRIPTIONS = {
    1: "看似普通的麦子，实际也是普通的麦子。但不同的人总会宣扬它有不同的功效",
    2: "外壳坚硬如铁，内部也坚硬如铁。何尝不是一种表里如一呢？",
    3: "本来说好要分家的番薯，却被绣衣楼的某人强行粘在一起营业。",
    4: "看起来乖巧实际完全没用的果实。据说最初培育人是个杨桃爱好者，还是《植株大战五斗米》的忠实玩家......",
    5: "袁氏家主，绣衣楼副官力荐美食！指标完成全靠它，不赶DDL!",
    6: "永远在倒计时里焦虑，生怕自己超时成熟。",
  };

  // 根据果实ID获取对应的图片URL
  const getFruitImage = (id) => {
    switch (parseInt(id)) {
      case 1:
        return "https://image2url.com/r2/default/images/1774944350785-84b516e7-a079-44ec-a75b-03aa550bee0b.png";
      case 2:
        return "https://image2url.com/r2/default/images/1775368048902-9a007bcf-4125-4e10-8c20-e89ee45bf945.png";
      case 3:
        return "https://image2url.com/r2/default/images/1775368185285-7f473326-7a60-4b14-bf74-49de83cfaafb.png";
      case 4:
        return "https://image2url.com/r2/default/images/1775368231949-500a1545-2d0a-4e65-b90e-b4d3ff3b0cee.png";
      case 5:
        return "https://image2url.com/r2/default/images/1775368263344-90ba8387-ac06-4f01-96ea-6cd113dbed50.png";
      case 6:
        return "https://image2url.com/r2/default/images/1775368348605-c101514d-c018-45d9-b49a-02622c609ed2.png";
      default:
        return "https://image2url.com/r2/default/images/1774944350785-84b516e7-a079-44ec-a75b-03aa550bee0b.png";
    }
  };

  // 处理果实点击事件
  const handleFruitClick = (fruitId) => {
    setSelectedFruit({
      id: fruitId,
      name: FRUIT_NAMES[fruitId],
      image: getFruitImage(fruitId),
      description: FRUIT_DESCRIPTIONS[fruitId],
    });
    setShowFruitDetail(true);
  };

  const [drawerOpen, setDrawerOpen] = useState(false);
  const [activeTab, setActiveTab] = useState("seeds");
  const [field, setField] = useState(Array(9).fill(null));
  const [draggedItem, setDraggedItem] = useState(null);
  const [animatingPatch, setAnimatingPatch] = useState(null);
  const [shovelPosition, setShovelPosition] = useState(null);
  const [sicklePosition, setSicklePosition] = useState(null);
  const [wateringPosition, setWateringPosition] = useState(null);
  const [countdowns, setCountdowns] = useState({});
  const [bloomingCountdowns, setBloomingCountdowns] = useState({});
  const [fruitingCountdowns, setFruitingCountdowns] = useState({});
  const [wiltTimers, setWiltTimers] = useState({});
  const [germinatingPatch, setGerminatingPatch] = useState(null);
  const [bloomingPatch, setBloomingPatch] = useState(null);
  const [fruitingPatch, setFruitingPatch] = useState(null);
  const [wiltingPatch, setWiltingPatch] = useState(null);
  const [recoveringPatch, setRecoveringPatch] = useState(null);
  const [inventory, setInventory] = useState({}); // 物品栏，存储果实及其数量

  // ================= 新增：查看他人农场状态 =================
  const [isViewingOther, setIsViewingOther] = useState(false);
  const [viewingCharacter, setViewingCharacter] = useState(null);
  const [otherFarmData, setOtherFarmData] = useState(Array(9).fill(null));
  const [otherCoins, setOtherCoins] = useState(0);
  const [otherCompletedOrders, setOtherCompletedOrders] = useState(0);
  const [showCharSelectForFarm, setShowCharSelectForFarm] = useState(false);
  const [availableFarmChars, setAvailableFarmChars] = useState([]);
  const [isBlurring, setIsBlurring] = useState(false);
  const [isLoadingOtherFarm, setIsLoadingOtherFarm] = useState(false);
  const [showOtherCropDetail, setShowOtherCropDetail] = useState(false);
  const [selectedOtherCrop, setSelectedOtherCrop] = useState(null);
  // =========================================================

  // 唤起角色选择列表
  const handleOpenViewSelect = async () => {
    try {
      let allChars = [];
      if (window.chatCharacterStore) {
        allChars = await window.chatCharacterStore.getAll();
      } else {
        allChars = JSON.parse(localStorage.getItem("t8_chat_list") || "[]");
      }
      const validChars = allChars.filter(
        (c) => !String(c.id).startsWith("group") && c.type !== "decor",
      );
      if (validChars.length === 0) {
        alert("传讯中暂无角色，请先添加名士！");
        return;
      }
      setAvailableFarmChars(validChars);
      setShowCharSelectForFarm(true);
    } catch (e) {
      console.error("加载角色失败:", e);
    }
  };

  // 调用 AI 生成对方农场数据
  const handleSelectCharacterToView = async (char) => {
    setShowCharSelectForFarm(false);
    setIsLoadingOtherFarm(true);
    setIsBlurring(true); // 触发模糊过度效果

    try {
      const worldContext = window.getWorldBookContext
        ? await window.getWorldBookContext()
        : "无特定背景设定";

      const sysPrompt =
        "你是一个东汉末年奇幻农场的数据生成器，精通东汉历史与角色扮演。";
      const userPrompt = `
                    【世界设定】
                    ${worldContext}

                    【农场主人（被查看的角色）】
                    姓名：${char.name}
                    性格：${char.profile?.personality || "未知"}
                    语言风格：${char.profile?.style || "未知"}

                    【任务】
                    请为该角色生成一片3x3的农场（共9个地块）。
                    可选果实ID：1(麦子), 2(坚果), 3(连体薯), 4(花团), 5(大萝卜), 6(限时玉米)。
                    地块状态可选：empty(空地), seed(种子), germinated(发芽), blooming(开花), fruiting(结果)。

                    要求：
                    1. 必须严格返回纯 JSON 格式，不要包含 \`\`\`json 等Markdown标记。
                    2. 随机生成 9 个地块的数据。如果有作物，必须包含该角色来查探作物时的一句自言自语（monologue，必须符合其人设和东汉用词），以及探查时间（logTime，如"辰时二刻"）。
                    3. 生成角色的金钱数量(coins)和已完成订单数(completedOrders)。

                    JSON格式示例：
                    {
                      "coins": 1500,
                      "completedOrders": 12,
                      "farm": [
                        null,
                        { "id": 1, "stage": "fruiting", "logTime": "辰时", "monologue": "这麦子长势喜人，足可充作军粮。" },
                        null,
                        { "id": 5, "stage": "blooming", "logTime": "午正", "monologue": "此等硕根萝卜，当进献于主公。" },
                        null, null, null, null, null
                      ]
                    }
                  `;

      if (window.sendToLLM) {
        window.sendToLLM(
          [
            { role: "system", content: sysPrompt },
            { role: "user", content: userPrompt },
          ],
          null,
          (reply) => {
            try {
              const cleanJson = reply.replace(/```json|```/g, "").trim();
              const data = JSON.parse(cleanJson);

              // 将 AI 输出的 stage 转化为组件可读的 boolean 状态
              const parsedField = data.farm.map((item) => {
                if (!item) return null;
                return {
                  id: item.id,
                  germinated: item.stage !== "seed",
                  blooming:
                    item.stage === "blooming" || item.stage === "fruiting",
                  fruiting: item.stage === "fruiting",
                  wilted: false,
                  logTime: item.logTime,
                  monologue: item.monologue,
                };
              });

              setOtherCoins(data.coins || 0);
              setOtherCompletedOrders(data.completedOrders || 0);
              setOtherFarmData(parsedField);
              setViewingCharacter(char);
              setIsViewingOther(true);
            } catch (e) {
              console.error("解析农场数据失败:", e);
              alert("跨越虚空失败，农场数据损坏。");
            } finally {
              setIsLoadingOtherFarm(false);
              setTimeout(() => setIsBlurring(false), 500); // 延迟移除模糊
            }
          },
          (err) => {
            console.error(err);
            alert("无法连接到该名士的农场。");
            setIsLoadingOtherFarm(false);
            setIsBlurring(false);
          },
        );
      } else {
        alert("请先配置 API！");
        setIsLoadingOtherFarm(false);
        setIsBlurring(false);
      }
    } catch (error) {
      console.error(error);
      setIsLoadingOtherFarm(false);
      setIsBlurring(false);
    }
  };

  // 退出他人农场
  const handleReturnHome = () => {
    setIsBlurring(true);
    setTimeout(() => {
      setIsViewingOther(false);
      setViewingCharacter(null);
      setIsBlurring(false);
      setDraggedItem(null); // 清空手中工具
    }, 500);
  };

  const handlePatchClick = (index) => {
    // ============ 新增：查看他人农场的交互逻辑 ============
    if (isViewingOther) {
      const item = otherFarmData[index];

      // 如果手里拿着镰刀，且对方作物已经成熟，触发偷菜
      if (draggedItem === "sickle" && item && item.fruiting) {
        // 东汉抓获偷窃判定：50%概率被抓
        const isCaught = Math.random() < 0.5;

        setSicklePosition(index); // 播放挥镰刀动画
        setTimeout(() => {
          setSicklePosition(null);
          if (isCaught) {
            alert(
              `【警报】你偷割灵植时，惊动了${viewingCharacter.name}部下的暗哨！\n按大汉律例，以盗窃论处，罚铜五十铢！`,
            );
            setCoins((prev) => {
              const newBalance = Math.max(0, prev - 50);
              window.addTransactionRecord("expense", 50, `偷割灵植被抓罚款`);
              return newBalance;
            });
          } else {
            alert(
              `【大丰收】手法利落！你神不知鬼不觉地顺走了一株【${FRUIT_NAMES[item.id]}】。`,
            );
            // 存入自己背包
            setInventory((prev) => ({
              ...prev,
              [item.id]: (prev[item.id] || 0) + 1,
            }));
            // 把对方地块清空
            const newOtherField = [...otherFarmData];
            newOtherField[index] = null;
            setOtherFarmData(newOtherField);
          }
        }, 300);
      } else if (item) {
        // 手里没拿镰刀，或者未成熟，则查看作物的留言心声
        setSelectedOtherCrop(item);
        setShowOtherCropDetail(true);
      }
      return; // 拦截结束，不执行原有的种植/收割逻辑
    }
    // =======================================================

    if (draggedItem === "shovel") {
      // 使用铲子清除种子
      // 添加动画效果
      setAnimatingPatch(index);
      setShovelPosition(index);
      setTimeout(() => {
        const newField = [...field];
        newField[index] = null;
        setField(newField);
        setDraggedItem(null); // 清除后清除手中物品
        setAnimatingPatch(null);
        setShovelPosition(null);
        // 清除倒计时
        const newCountdowns = { ...countdowns };
        delete newCountdowns[index];
        setCountdowns(newCountdowns);
        // 清除开花倒计时
        const newBloomingCountdowns = { ...bloomingCountdowns };
        delete newBloomingCountdowns[index];
        setBloomingCountdowns(newBloomingCountdowns);
        // 清除果实倒计时
        const newFruitingCountdowns = { ...fruitingCountdowns };
        delete newFruitingCountdowns[index];
        setFruitingCountdowns(newFruitingCountdowns);
        // 清除枯萎定时器
        if (wiltTimers[index]) {
          clearTimeout(wiltTimers[index]);
          const newWiltTimers = { ...wiltTimers };
          delete newWiltTimers[index];
          setWiltTimers(newWiltTimers);
        }
        // 不清除手中工具，允许连续使用
        // setDraggedItem(null); // 清除后清除手中物品
      }, 300);
    } else if (draggedItem === "sickle") {
      // 使用镰刀收割成熟果实
      const item = field[index];
      if (
        item &&
        typeof item === "object" &&
        (item.fruiting || item.blooming || item.wilted)
      ) {
        // 清除枯萎定时器
        if (wiltTimers[index]) {
          clearTimeout(wiltTimers[index]);
          setWiltTimers((prev) => {
            const newTimers = { ...prev };
            delete newTimers[index];
            return newTimers;
          });
        }
        // 添加镰刀动画效果
        setSicklePosition(index);
        setTimeout(() => {
          const newField = [...field];
          newField[index] = null;
          setField(newField);
          // 不清除手中工具，允许连续使用
          // setDraggedItem(null); // 清除后清除手中物品
          setSicklePosition(null);
          // 添加果实到物品栏
          setInventory((prev) => {
            const newInventory = { ...prev };
            const fruitId = item.id;
            newInventory[fruitId] = (newInventory[fruitId] || 0) + 1;
            return newInventory;
          });
        }, 300);
      }
    } else if (draggedItem === "watering") {
      // 使用浇水工具恢复枯萎的果实
      const item = field[index];
      if (item && typeof item === "object" && item.wilted) {
        // 添加浇水动画效果
        setWateringPosition(index);
        // 恢复果实到上一步正常的样子
        setTimeout(() => {
          // 添加恢复动画
          setRecoveringPatch(index);
          setTimeout(() => setRecoveringPatch(null), 300);
          const newField = [...field];
          // 移除枯萎状态，恢复到结果状态
          newField[index] = {
            ...item,
            wilted: false,
          };
          setField(newField);
          // 不清除手中工具，允许连续使用
          // setDraggedItem(null); // 清除后清除手中物品
          setWateringPosition(null);
        }, 300);
      }
    } else if (draggedItem && !field[index]) {
      // 种植种子
      const newField = [...field];
      newField[index] = draggedItem;
      setField(newField);
      // 不清除手中物品，允许连续种植
      // setDraggedItem(null); // 种植后清除手中物品
    } else if (
      field[index] &&
      field[index] !== "germinated" &&
      !countdowns[index]
    ) {
      // 点击种子开始倒计时
      setCountdowns({ ...countdowns, [index]: 3 });

      // 倒计时逻辑
      const interval = setInterval(() => {
        setCountdowns((prev) => {
          const newCountdowns = { ...prev };
          if (newCountdowns[index] > 1) {
            newCountdowns[index]--;
            return newCountdowns;
          } else {
            clearInterval(interval);
            // 倒计时结束，变为发芽状态
            setField((prevField) => {
              const newField = [...prevField];
              // 为不同的种子设置不同的发芽状态
              const seedItem = prevField[index];
              if (typeof seedItem === "object" && seedItem.id) {
                newField[index] = { ...seedItem, germinated: true };
              } else {
                newField[index] = "germinated";
              }
              return newField;
            });
            // 添加发芽动画
            setGerminatingPatch(index);
            setTimeout(() => setGerminatingPatch(null), 300);
            // 清除倒计时
            delete newCountdowns[index];
            return newCountdowns;
          }
        });
      }, 1000);
    }
  };

  return (
    <div className="farm-overlay open animate-fadeIn">
            {/* 顶部清晰返回导航按钮 */}
      <div
        className="active-press"
        onClick={onBack}
        style={{
          position: "absolute",
          top: 16,
          left: 16,
          zIndex: 100,
          width: "38px",
          height: "38px",
          borderRadius: "50%",
          background: "rgba(255, 255, 255, 0.9)",
          backdropFilter: "blur(8px)",
          boxShadow: "0 2px 10px rgba(0, 0, 0, 0.15)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          cursor: "pointer",
        }}
      >
        <iconify-icon
          icon="line-md:arrow-left"
          style={{ fontSize: "22px", color: "#5a5f4d" }}
        ></iconify-icon>
      </div>

      {/* 主内容区域，增加模糊过渡 */}
      <div
        style={{
          transition: "filter 0.5s ease",
          filter: isBlurring ? "blur(10px) brightness(0.8)" : "none",
          height: "100%",
          width: "100%",
          position: "relative",
        }}
      >
        {/* 右上角金钱显示 (根据是否拜访他人切换) */}
        <div
          style={{
            position: "absolute",
            top: 20,
            right: 20,
            zIndex: 100,
            background: "rgba(255,255,255,0.85)",
            backdropFilter: "blur(4px)",
            padding: "6px 16px",
            borderRadius: "20px",
            display: "flex",
            alignItems: "center",
            gap: "6px",
            color: "#5a5f4d",
            fontWeight: "bold",
            fontSize: "14px",
            boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
          }}
        >
          <iconify-icon
            icon="ph:coin-vertical-fill"
            style={{ color: "#E8C3A8", fontSize: "20px" }}
          ></iconify-icon>
          {isViewingOther
            ? `${otherCoins} 铢 (历史订单:${otherCompletedOrders})`
            : `${coins} 铢`}
        </div>

        {/* 如果在看别人，在上方显示正在拜访谁 */}
        {isViewingOther && (
          <div
            style={{
              position: "absolute",
              top: 80,
              left: "50%",
              transform: "translateX(-50%)",
              background: "rgba(0,0,0,0.6)",
              color: "white",
              padding: "8px 20px",
              borderRadius: "20px",
              fontSize: "14px",
              zIndex: 10,
              letterSpacing: "2px",
              display: "flex",
              alignItems: "center",
              gap: "8px",
            }}
          >
            <iconify-icon
              icon="ph:eye-fill"
              style={{ color: "#A8C8BA" }}
            ></iconify-icon>
            正在暗中观察【{viewingCharacter?.name}】的农场
          </div>
        )}

        {/* 3x3 土地 (将 field.map 替换为根据状态切换) */}
        <div className="soil-container">
          {(isViewingOther ? otherFarmData : field).map((item, i) => (
            <div
              key={i}
              className={`soil-patch ${animatingPatch === i ? "shovel-animation" : ""}`}
              onClick={() => handlePatchClick(i)}
            >
              {item &&
                (item === "germinated" ||
                  (typeof item === "object" && item.germinated)) && (
                  <img
                    src={(() => {
                      if (typeof item === "object" && item.germinated) {
                        if (item.wilted) {
                          return `https://image2url.com/r2/default/images/1775300359341-796a2b21-66dd-42c9-9541-a28834d48cb7.png`;
                        } else if (item.id === 1 && item.fruiting) {
                          return `https://image2url.com/r2/default/images/1774944350785-84b516e7-a079-44ec-a75b-03aa550bee0b.png`;
                        } else if (item.id === 2 && item.fruiting) {
                          return `https://image2url.com/r2/default/images/1775368048902-9a007bcf-4125-4e10-8c20-e89ee45bf945.png`;
                        } else if (item.id === 3 && item.fruiting) {
                          return `https://image2url.com/r2/default/images/1775368185285-7f473326-7a60-4b14-bf74-49de83cfaafb.png`;
                        } else if (item.id === 4 && item.fruiting) {
                          return `https://image2url.com/r2/default/images/1775368231949-500a1545-2d0a-4e65-b90e-b4d3ff3b0cee.png`;
                        } else if (item.id === 5 && item.fruiting) {
                          return `https://image2url.com/r2/default/images/1775368263344-90ba8387-ac06-4f01-96ea-6cd113dbed50.png`;
                        } else if (item.id === 6 && item.fruiting) {
                          return `https://image2url.com/r2/default/images/1775368348605-c101514d-c018-45d9-b49a-02622c609ed2.png`;
                        } else if (item.id === 1 && item.blooming) {
                          return `https://image2url.com/r2/default/images/1774944332656-80c54732-f455-4e61-bc49-d9fa94c0656f.png`;
                        } else if (item.id === 2 && item.blooming) {
                          return `https://image2url.com/r2/default/images/1775287231328-6a37e646-06bf-4feb-9e63-d8b7c0dd5edd.png`;
                        } else if (item.id === 3 && item.blooming) {
                          return `https://image2url.com/r2/default/images/1775287284813-e4e7d830-c501-4e7a-b52a-c92168e71331.png`;
                        } else if (item.id === 4 && item.blooming) {
                          return `https://image2url.com/r2/default/images/1775287317330-4336de08-a5bb-4bb3-907d-d05800dfdcd5.png`;
                        } else if (item.id === 5 && item.blooming) {
                          return `https://image2url.com/r2/default/images/1775287356380-06e590c6-af35-443a-8861-1937c71b9765.png`;
                        } else if (item.id === 6 && item.blooming) {
                          return `https://image2url.com/r2/default/images/1775287405920-8381c149-b877-4aca-9dd2-9cb997a8b57d.png`;
                        }
                        switch (item.id) {
                          case 1:
                            return `https://image2url.com/r2/default/images/1775278905349-5a2d8ba1-9f92-48a6-95e2-fd0521baeae6.png`;
                          case 2:
                            return `https://image2url.com/r2/default/images/1775281857694-fc6f78f8-526a-4891-b477-46410970e6e5.png`;
                          case 3:
                            return `https://image2url.com/r2/default/images/1775281895277-a3f8cde6-4cba-4514-936e-7d33d492afb5.png`;
                          case 4:
                            return `https://image2url.com/r2/default/images/1775282290627-ba738923-c095-4182-829e-5d50c1f7f21a.png`;
                          case 5:
                            return `https://image2url.com/r2/default/images/1775282349910-b1a4970a-d9d4-4bd0-9170-59ba0ab1cfc5.png`;
                          case 6:
                            return `https://image2url.com/r2/default/images/1775282380340-1fde3733-4470-4c37-b0ca-f3d33c400679.png`;
                          default:
                            return `https://image2url.com/r2/default/images/1775278905349-5a2d8ba1-9f92-48a6-95e2-fd0521baeae6.png`;
                        }
                      } else {
                        return `https://image2url.com/r2/default/images/1775278905349-5a2d8ba1-9f92-48a6-95e2-fd0521baeae6.png`;
                      }
                    })()}
                    className={`planted-seed ${germinatingPatch === i || bloomingPatch === i || fruitingPatch === i || wiltingPatch === i || recoveringPatch === i ? "seedPop" : ""}`}
                    onClick={(e) => {
                      e.stopPropagation(); // 阻止事件冒泡
                      const currentIndex = i;

                      // 查看他人农场时，点击作物触发心声弹窗或偷菜
                      if (isViewingOther) {
                        if (item && typeof item === "object") {
                          // 如果手里拿着镰刀，且对方作物已经成熟，触发偷菜
                          if (draggedItem === "sickle" && item.fruiting) {
                            // 东汉抓获偷窃判定：50%概率被抓
                            const isCaught = Math.random() < 0.5;

                            setSicklePosition(currentIndex); // 播放挥镰刀动画
                            setTimeout(() => {
                              setSicklePosition(null);
                              if (isCaught) {
                                alert(
                                  `【警报】你偷割灵植时，惊动了${viewingCharacter?.name || "未知"}部下的暗哨！\n按大汉律例，以盗窃论处，罚铜五十铢！`,
                                );
                                setCoins((prev) => {
                                  const newBalance = Math.max(0, prev - 50);
                                  window.addTransactionRecord(
                                    "expense",
                                    50,
                                    `偷割灵植被抓罚款`,
                                  );
                                  return newBalance;
                                });
                              } else {
                                alert(
                                  `【大丰收】手法利落！你神不知鬼不觉地顺走了一株【${FRUIT_NAMES[item.id]}】。`,
                                );
                                // 存入自己背包
                                setInventory((prev) => ({
                                  ...prev,
                                  [item.id]: (prev[item.id] || 0) + 1,
                                }));
                                // 把对方地块清空
                                const newOtherField = [...otherFarmData];
                                newOtherField[currentIndex] = null;
                                setOtherFarmData(newOtherField);
                              }
                            }, 300);
                          } else {
                            // 手里没拿镰刀，或者未成熟，则查看作物的留言心声
                            setSelectedOtherCrop(item);
                            setShowOtherCropDetail(true);
                          }
                        }
                        return;
                      }

                      if (draggedItem === "sickle") {
                        // 使用镰刀收割成熟果实或枯萎果实
                        if (
                          item &&
                          typeof item === "object" &&
                          (item.fruiting || item.blooming || item.wilted)
                        ) {
                          // 清除枯萎定时器
                          if (wiltTimers[currentIndex]) {
                            clearTimeout(wiltTimers[currentIndex]);
                            setWiltTimers((prev) => {
                              const newTimers = { ...prev };
                              delete newTimers[currentIndex];
                              return newTimers;
                            });
                          }
                          // 添加镰刀动画效果
                          setSicklePosition(currentIndex);
                          setTimeout(() => {
                            const newField = [...field];
                            newField[currentIndex] = null;
                            setField(newField);
                            setDraggedItem(null); // 清除后清除手中物品
                            setSicklePosition(null);
                            // 添加果实到物品栏
                            setInventory((prev) => {
                              const newInventory = { ...prev };
                              const fruitId = item.id;
                              newInventory[fruitId] =
                                (newInventory[fruitId] || 0) + 1;
                              return newInventory;
                            });
                          }, 300);
                        }
                      } else if (
                        typeof item === "object" &&
                        item.germinated &&
                        item.id >= 1 &&
                        item.id <= 6 &&
                        !item.blooming
                      ) {
                        // 点击发芽图片，5秒后开花
                        setBloomingCountdowns({
                          ...bloomingCountdowns,
                          [currentIndex]: 5,
                        });

                        // 倒计时逻辑
                        const interval = setInterval(() => {
                          setBloomingCountdowns((prev) => {
                            const newCountdowns = { ...prev };
                            if (newCountdowns[currentIndex] > 1) {
                              newCountdowns[currentIndex]--;
                              return newCountdowns;
                            } else {
                              clearInterval(interval);
                              // 添加开花动画
                              setBloomingPatch(currentIndex);
                              setTimeout(() => setBloomingPatch(null), 300);
                              // 倒计时结束，变为开花状态
                              setField((prevField) => {
                                const newField = [...prevField];
                                newField[currentIndex] = {
                                  ...newField[currentIndex],
                                  blooming: true,
                                };
                                return newField;
                              });
                              // 清除倒计时
                              delete newCountdowns[currentIndex];
                              return newCountdowns;
                            }
                          });
                        }, 1000);
                      } else if (
                        typeof item === "object" &&
                        item.germinated &&
                        (item.id === 1 ||
                          item.id === 2 ||
                          item.id === 3 ||
                          item.id === 4 ||
                          item.id === 5 ||
                          item.id === 6) &&
                        item.blooming &&
                        !item.fruiting
                      ) {
                        // 点击开花图片，10秒后结果
                        setFruitingCountdowns({
                          ...fruitingCountdowns,
                          [currentIndex]: 10,
                        });

                        // 倒计时逻辑
                        const interval = setInterval(() => {
                          setFruitingCountdowns((prev) => {
                            const newCountdowns = { ...prev };
                            if (newCountdowns[currentIndex] > 1) {
                              newCountdowns[currentIndex]--;
                              return newCountdowns;
                            } else {
                              clearInterval(interval);
                              // 添加结果动画
                              setFruitingPatch(currentIndex);
                              setTimeout(() => setFruitingPatch(null), 300);
                              // 倒计时结束，变为结果状态
                              setField((prevField) => {
                                const newField = [...prevField];
                                newField[currentIndex] = {
                                  ...newField[currentIndex],
                                  fruiting: true,
                                };
                                return newField;
                              });
                              // 启动枯萎定时器，7秒后如果没有被收割，果实会枯萎
                              const wiltTimer = setTimeout(() => {
                                // 先设置枯萎动画
                                setWiltingPatch(currentIndex);
                                setTimeout(() => setWiltingPatch(null), 300);
                                setField((prevField) => {
                                  const newField = [...prevField];
                                  const item = newField[currentIndex];
                                  if (
                                    item &&
                                    typeof item === "object" &&
                                    item.fruiting &&
                                    !item.wilted
                                  ) {
                                    newField[currentIndex] = {
                                      ...item,
                                      wilted: true,
                                    };
                                    // 启动消失定时器，3秒后如果没有被收割，枯萎的果实会消失
                                    setTimeout(() => {
                                      setField((prevField2) => {
                                        const newField2 = [...prevField2];
                                        const item2 = newField2[currentIndex];
                                        if (
                                          item2 &&
                                          typeof item2 === "object" &&
                                          item2.wilted
                                        ) {
                                          newField2[currentIndex] = null;
                                        }
                                        return newField2;
                                      });
                                    }, 3000);
                                  }
                                  return newField;
                                });
                                // 清除枯萎定时器
                                setWiltTimers((prev) => {
                                  const newTimers = { ...prev };
                                  delete newTimers[currentIndex];
                                  return newTimers;
                                });
                              }, 7000);
                              // 保存枯萎定时器
                              setWiltTimers((prev) => ({
                                ...prev,
                                [currentIndex]: wiltTimer,
                              }));
                              // 清除倒计时
                              delete newCountdowns[currentIndex];
                              return newCountdowns;
                            }
                          });
                        }, 1000);
                      }
                    }}
                  />
                )}
              {item &&
                item !== "germinated" &&
                !(typeof item === "object" && item.germinated) && (
                  <img
                    src={typeof item === "object" ? item.url : item}
                    className="planted-seed"
                  />
                )}
              {countdowns[i] && (
                <div
                  style={{
                    position: "absolute",
                    top: "10%",
                    left: "50%",
                    transform: "translate(-50%, -50%)",
                    fontSize: "20px",
                    fontWeight: "bold",
                    color: "white",
                    textShadow: "1px 1px 2px rgba(0,0,0,0.5)",
                    backgroundColor: "rgba(0,0,0,0.5)",
                    padding: "5px 10px",
                    borderRadius: "15px",
                  }}
                >
                  {countdowns[i]}
                </div>
              )}
              {bloomingCountdowns[i] && (
                <div
                  style={{
                    position: "absolute",
                    top: "10%",
                    left: "50%",
                    transform: "translate(-50%, -50%)",
                    fontSize: "20px",
                    fontWeight: "bold",
                    color: "white",
                    textShadow: "1px 1px 2px rgba(0,0,0,0.5)",
                    backgroundColor: "rgba(0,0,0,0.5)",
                    padding: "5px 10px",
                    borderRadius: "15px",
                  }}
                >
                  {bloomingCountdowns[i]}
                </div>
              )}
              {fruitingCountdowns[i] && (
                <div
                  style={{
                    position: "absolute",
                    top: "10%",
                    left: "50%",
                    transform: "translate(-50%, -50%)",
                    fontSize: "20px",
                    fontWeight: "bold",
                    color: "white",
                    textShadow: "1px 1px 2px rgba(0,0,0,0.5)",
                    backgroundColor: "rgba(0,0,0,0.5)",
                    padding: "5px 10px",
                    borderRadius: "15px",
                  }}
                >
                  {fruitingCountdowns[i]}
                </div>
              )}
              {shovelPosition === i && (
                <img
                  src="https://image2url.com/r2/default/images/1774958372764-021089df-3a0f-4e77-9063-0f3b4b43c74a.png"
                  className="planted-seed"
                  style={{
                    animation: "shovelAnimation 0.3s ease-in-out",
                  }}
                />
              )}
              {sicklePosition === i && (
                <img
                  src="https://image2url.com/r2/default/images/1775290847546-f44045f1-ba6f-4a92-bb52-79ec29b64a28.png"
                  className="planted-seed"
                  style={{
                    animation: "shovelAnimation 0.3s ease-in-out",
                  }}
                />
              )}
              {wateringPosition === i && (
                <img
                  src="https://image2url.com/r2/default/images/1775303880268-d5073e49-3d13-4127-82de-2c3d2d044e19.png"
                  className="planted-seed"
                  style={{
                    animation: "shovelAnimation 0.3s ease-in-out",
                  }}
                />
              )}
            </div>
          ))}
        </div>
      </div>

      {/* 栅栏 */}
      <div style={{ margin: "20px 0", textAlign: "center" }}>
        <div
          style={{
            display: "flex",
            gap: "5px",
            justifyContent: "center",
          }}
        >
          <img
            src="https://image2url.com/r2/default/images/1774949078503-fa3166fe-fe73-4776-ab49-616832a8d65d.png"
            style={{ width: "70px", height: "auto" }}
          />
          <img
            src="https://image2url.com/r2/default/images/1774949078503-fa3166fe-fe73-4776-ab49-616832a8d65d.png"
            style={{ width: "70px", height: "auto" }}
          />
          <img
            src="https://image2url.com/r2/default/images/1774949078503-fa3166fe-fe73-4776-ab49-616832a8d65d.png"
            style={{ width: "70px", height: "auto" }}
          />
          <img
            src="https://image2url.com/r2/default/images/1774949078503-fa3166fe-fe73-4776-ab49-616832a8d65d.png"
            style={{ width: "70px", height: "auto" }}
          />
        </div>
      </div>

      {/* 底部按钮 */}
      <div className="farm-footer">
        <div className="farm-btn" onClick={() => setDrawerOpen(!drawerOpen)}>
          物品
        </div>
        <div className="farm-btn" onClick={() => setShowOrderModal(true)}>
          订单
        </div>
        {isViewingOther ? (
          <div
            className="farm-btn"
            style={{ background: "#D99E82", borderColor: "#fff" }}
            onClick={handleReturnHome}
          >
            归家
          </div>
        ) : (
          <div className="farm-btn" onClick={handleOpenViewSelect}>
            查看
          </div>
        )}
      </div>

      {/* 物品栏抽屉 */}
      <div className={`item-drawer ${drawerOpen ? "open" : ""}`}>
        <div className="flex">
          <div
            className={`drawer-tab ${activeTab === "seeds" ? "active" : ""}`}
            onClick={() => setActiveTab("seeds")}
          >
            种子
          </div>
          <div
            className={`drawer-tab ${activeTab === "fruits" ? "active" : ""}`}
            onClick={() => setActiveTab("fruits")}
          >
            果实
          </div>
          <div
            className={`drawer-tab ${activeTab === "tools" ? "active" : ""}`}
            onClick={() => setActiveTab("tools")}
          >
            工具
          </div>
        </div>

        <div className="item-grid">
          {activeTab === "seeds" ? (
            <>
              <div
                className="farm-item-card"
                onClick={() => {
                  setDraggedItem({
                    id: 1,
                    url: "https://image2url.com/r2/default/images/1774944197887-3a46d3b4-1684-46a5-bfda-cff3ad21a363.png",
                  });
                  setDrawerOpen(false);
                }}
              >
                <img
                  src="https://image2url.com/r2/default/images/1774944197887-3a46d3b4-1684-46a5-bfda-cff3ad21a363.png"
                  style={{ width: 50 }}
                />
              </div>
              <div
                className="farm-item-card"
                onClick={() => {
                  setDraggedItem({
                    id: 2,
                    url: "https://image2url.com/r2/default/images/1774953582959-b3b0282b-75fe-450e-a7eb-92c391f795b3.png",
                  });
                  setDrawerOpen(false);
                }}
              >
                <img
                  src="https://image2url.com/r2/default/images/1774953582959-b3b0282b-75fe-450e-a7eb-92c391f795b3.png"
                  style={{ width: 50 }}
                />
              </div>
              <div
                className="farm-item-card"
                onClick={() => {
                  setDraggedItem({
                    id: 3,
                    url: "https://image2url.com/r2/default/images/1774953616454-f7a02321-ddcf-4ee6-b638-7c9d2b78f9da.png",
                  });
                  setDrawerOpen(false);
                }}
              >
                <img
                  src="https://image2url.com/r2/default/images/1774953616454-f7a02321-ddcf-4ee6-b638-7c9d2b78f9da.png"
                  style={{ width: 50 }}
                />
              </div>
              <div
                className="farm-item-card"
                onClick={() => {
                  setDraggedItem({
                    id: 4,
                    url: "https://image2url.com/r2/default/images/1774953655279-468b216d-3a91-4e40-b8ae-6b6638c66cde.png",
                  });
                  setDrawerOpen(false);
                }}
              >
                <img
                  src="https://image2url.com/r2/default/images/1774953655279-468b216d-3a91-4e40-b8ae-6b6638c66cde.png"
                  style={{ width: 50 }}
                />
              </div>
              <div
                className="farm-item-card"
                onClick={() => {
                  setDraggedItem({
                    id: 5,
                    url: "https://image2url.com/r2/default/images/1774953701803-667af9eb-f526-4adf-ae46-f3079ce807c9.png",
                  });
                  setDrawerOpen(false);
                }}
              >
                <img
                  src="https://image2url.com/r2/default/images/1774953701803-667af9eb-f526-4adf-ae46-f3079ce807c9.png"
                  style={{ width: 50 }}
                />
              </div>
              <div
                className="farm-item-card"
                onClick={() => {
                  setDraggedItem({
                    id: 6,
                    url: "https://image2url.com/r2/default/images/1774953800484-e9e68ac6-1423-42fe-84bb-92eba32a7f60.png",
                  });
                  setDrawerOpen(false);
                }}
              >
                <img
                  src="https://image2url.com/r2/default/images/1774953800484-e9e68ac6-1423-42fe-84bb-92eba32a7f60.png"
                  style={{ width: 50 }}
                />
              </div>
            </>
          ) : activeTab === "fruits" ? (
            Object.entries(inventory).map(([fruitId, count]) => {
              // 根据果实ID获取对应的图片URL
              const getFruitImage = (id) => {
                switch (parseInt(id)) {
                  case 1:
                    return "https://image2url.com/r2/default/images/1774944350785-84b516e7-a079-44ec-a75b-03aa550bee0b.png";
                  case 2:
                    return "https://image2url.com/r2/default/images/1775368048902-9a007bcf-4125-4e10-8c20-e89ee45bf945.png";
                  case 3:
                    return "https://image2url.com/r2/default/images/1775368185285-7f473326-7a60-4b14-bf74-49de83cfaafb.png";
                  case 4:
                    return "https://image2url.com/r2/default/images/1775368231949-500a1545-2d0a-4e65-b90e-b4d3ff3b0cee.png";
                  case 5:
                    return "https://image2url.com/r2/default/images/1775368263344-90ba8387-ac06-4f01-96ea-6cd113dbed50.png";
                  case 6:
                    return "https://image2url.com/r2/default/images/1775368348605-c101514d-c018-45d9-b49a-02622c609ed2.png";
                  default:
                    return "https://image2url.com/r2/default/images/1774944350785-84b516e7-a079-44ec-a75b-03aa550bee0b.png";
                }
              };

              return (
                <div
                  key={fruitId}
                  className="farm-item-card"
                  style={{ position: "relative", cursor: "pointer" }}
                  onClick={() => handleFruitClick(fruitId)}
                >
                  <img src={getFruitImage(fruitId)} style={{ width: 50 }} />
                  {count > 1 && (
                    <div
                      style={{
                        position: "absolute",
                        top: "-5px",
                        right: "-5px",
                        backgroundColor: "#ff6b6b",
                        color: "white",
                        borderRadius: "50%",
                        width: "20px",
                        height: "20px",
                        fontSize: "12px",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        fontWeight: "bold",
                      }}
                    >
                      {count}
                    </div>
                  )}
                </div>
              );
            })
          ) : (
            <>
              <div
                className="farm-item-card"
                onClick={() => {
                  setDraggedItem("shovel");
                  setDrawerOpen(false);
                }}
              >
                <img
                  src="https://image2url.com/r2/default/images/1774958372764-021089df-3a0f-4e77-9063-0f3b4b43c74a.png"
                  style={{ width: 50 }}
                />
              </div>
              <div
                className="farm-item-card"
                onClick={() => {
                  setDraggedItem("sickle");
                  setDrawerOpen(false);
                }}
              >
                <img
                  src="https://image2url.com/r2/default/images/1775290847546-f44045f1-ba6f-4a92-bb52-79ec29b64a28.png"
                  style={{ width: 50 }}
                />
              </div>
              <div
                className="farm-item-card"
                onClick={() => {
                  setDraggedItem("watering");
                  setDrawerOpen(false);
                }}
              >
                <img
                  src="https://image2url.com/r2/default/images/1775303880268-d5073e49-3d13-4127-82de-2c3d2d044e19.png"
                  style={{ width: 50 }}
                />
              </div>
            </>
          )}
        </div>

        {draggedItem && (
          <div
            style={{
              marginTop: 15,
              fontSize: 12,
              color: "#89a89a",
              textAlign: "center",
            }}
          >
            {draggedItem === "shovel" && "已选中铲子，请点击土地清除种子"}
            {draggedItem === "sickle" && "已选中镰刀，请点击土地收割成熟果实"}
            {draggedItem === "watering" &&
              "已选中浇水工具，请点击枯萎的果实进行恢复"}
            {typeof draggedItem === "object" &&
              "已选中种子，请点击土地进行种植"}
          </div>
        )}
      </div>

      {/* 点击背景关闭抽屉 */}
      {drawerOpen && (
        <div
          style={{ position: "absolute", inset: 0, zIndex: 999 }}
          onClick={() => setDrawerOpen(false)}
        ></div>
      )}

      {/* ==== 新增：订单系统弹窗 ==== */}
      {showOrderModal && (
        <div className="fixed inset-x-0 bottom-0 bg-[#FDFCF8] rounded-t-3xl shadow-2xl z-[1000] animate-slide-up h-[75vh] flex flex-col font-sans">
          {/* 弹窗头部 */}
          <div className="p-5 flex justify-between items-center bg-white rounded-t-3xl shadow-sm z-10 border-b border-[#F2EFDE]">
            <h3 className="text-xl font-bold text-[#5A5F4D] tracking-wide flex items-center gap-2">
              <iconify-icon
                icon="ph:scroll-fill"
                style={{ color: "#D99E82" }}
              ></iconify-icon>
              商行订单
            </h3>
            <div className="flex gap-3">
              <button
                onClick={handleGenerateOrders}
                disabled={isGeneratingOrders || orders.length >= 5}
                className="px-4 py-1.5 bg-[#E8C3A8] text-white rounded-full text-xs font-bold active:scale-95 disabled:opacity-50 transition-all shadow-sm"
              >
                {isGeneratingOrders ? "飞鹰寻单中..." : "招揽新客"}
              </button>
              <button
                onClick={() => setShowOrderModal(false)}
                className="w-8 h-8 rounded-full bg-[#f0f0f0] flex items-center justify-center text-[#8C8C8C] active:scale-90 transition-transform"
              >
                <i className="ph-bold ph-x"></i>
              </button>
            </div>
          </div>

          {/* 订单列表内容 */}
          <div className="flex-1 overflow-y-auto p-4 bg-[#FDFCF8] no-scrollbar">
            {isGeneratingOrders && orders.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full text-[#8C917B] gap-3">
                <iconify-icon
                  icon="line-md:loading-twotone-loop"
                  style={{ fontSize: "36px", color: "#D99E82" }}
                ></iconify-icon>
                <span className="text-sm font-bold tracking-widest">
                  正在四海散播仙果消息...
                </span>
              </div>
            ) : orders.length > 0 ? (
              <div className="flex flex-col gap-4 pb-10">
                {orders.map((order) => (
                  <div
                    key={order.id}
                    className="bg-white rounded-2xl p-4 shadow-sm border border-[#F2EFDE] flex flex-col relative overflow-hidden"
                  >
                    <div className="flex justify-between items-start mb-2">
                      <div className="flex items-center gap-2">
                        <div className="w-9 h-9 rounded-full bg-[#A8C8BA] flex items-center justify-center text-white font-bold text-sm shadow-inner">
                          {order.buyer.charAt(0)}
                        </div>
                        <div>
                          <div className="font-bold text-[#5A5F4D] text-sm">
                            {order.buyer}
                          </div>
                          <div className="text-[10px] text-[#8C917B]">
                            {order.isNpc ? "游商 / 散客" : "传讯挚友"}
                          </div>
                        </div>
                      </div>
                      <div className="text-xs font-bold text-[#D6724B] flex items-center gap-1 bg-[#FFF5F3] px-2 py-1 rounded-md border border-[#FADBD8]">
                        <iconify-icon icon="ph:timer-bold"></iconify-icon>
                        {Math.floor(order.timeLeft / 60)}:
                        {(order.timeLeft % 60).toString().padStart(2, "0")}
                      </div>
                    </div>

                    <div className="bg-[#F9F7F5] p-3 rounded-xl mb-3 border-l-4 border-[#D99E82]">
                      <div className="text-[11px] font-bold text-[#8C917B] mb-1">
                        需求留言：
                      </div>
                      <div className="text-[13px] text-[#5A5F4D] italic leading-snug">
                        "{order.desc}"
                      </div>
                    </div>

                    <div className="flex justify-between items-center mt-auto pt-3 border-t border-dashed border-[#EAEAEA]">
                      <div className="flex items-center gap-4">
                        <div className="flex flex-col">
                          <span className="text-[10px] text-[#8C917B] font-bold">
                            需求物品
                          </span>
                          <span className="text-sm font-bold text-[#5A5F4D]">
                            {order.itemName}{" "}
                            <span className="text-[#D99E82]">
                              x{order.quantity}
                            </span>
                          </span>
                        </div>
                        <div className="flex flex-col">
                          <span className="text-[10px] text-[#8C917B] font-bold">
                            赏金报酬
                          </span>
                          <span className="text-sm font-bold text-[#E8C3A8]">
                            {order.price} 铢
                          </span>
                        </div>
                      </div>

                      <button
                        onClick={async () => {
                          const currentStock = inventory[order.itemId] || 0;
                          if (currentStock >= order.quantity) {
                            // 1. 扣除库存
                            setInventory((prev) => ({
                              ...prev,
                              [order.itemId]:
                                prev[order.itemId] - order.quantity,
                            }));

                            // 2. 处理收益捐逻辑
                            let actualEarn = order.price;
                            let totalDonate = 0;
                            const subsStr = localStorage.getItem(
                              "charity_income_subs",
                            );

                            if (subsStr) {
                              const subs = JSON.parse(subsStr);
                              const farmSubs = subs.filter(
                                (s) => s.source === "古怪农场",
                              );

                              if (farmSubs.length > 0) {
                                const savedProjects = JSON.parse(
                                  (await dbManager.get("charity_projects")) ||
                                    "[]",
                                );
                                let updatedProjects = [...savedProjects];

                                for (const sub of farmSubs) {
                                  const donateAmount = Math.floor(
                                    order.price * (sub.percentage / 100),
                                  );
                                  if (donateAmount > 0) {
                                    totalDonate += donateAmount;
                                    if (window.addTransactionRecord) {
                                      window.addTransactionRecord(
                                        "expense",
                                        donateAmount,
                                        `收益捐代扣：${sub.projectName}`,
                                      );
                                    }

                                    updatedProjects = updatedProjects.map(
                                      (p) => {
                                        if (p.title === sub.projectName) {
                                          return {
                                            ...p,
                                            raised: p.raised + donateAmount,
                                            donors: p.donors + 1,
                                            history: [
                                              ...(p.history || []),
                                              {
                                                date: "刚刚",
                                                event: `古怪农场收益捐自动拨入 ${donateAmount} 铢`,
                                              },
                                            ],
                                          };
                                        }
                                        return p;
                                      },
                                    );
                                  }
                                }

                                if (totalDonate > 0) {
                                  await dbManager.set(
                                    "charity_projects",
                                    JSON.stringify(updatedProjects),
                                  );
                                  actualEarn = Math.max(
                                    0,
                                    order.price - totalDonate,
                                  );

                                  setTimeout(() => {
                                    alert(
                                      `本次农场订单总收益 ${order.price} 铢，其中 ${totalDonate} 铢已根据您的【收益捐】设置自动捐出。\n实际入账 ${actualEarn} 铢！感恩您的善举。`,
                                    );
                                  }, 500);
                                }
                              }
                            }

                            // 3. 增加实际入账金钱
                            setCoins((prev) => {
                              if (window.addTransactionRecord) {
                                window.addTransactionRecord(
                                  "income",
                                  actualEarn,
                                  `农场商单交易`,
                                );
                              }
                              return prev + actualEarn;
                            });

                            // 4. 移除订单
                            setOrders((prev) =>
                              prev.filter((o) => o.id !== order.id),
                            );

                            if (totalDonate === 0) {
                              alert(`交易成功！获得 ${order.price} 铢`);
                            }
                          } else {
                            alert(
                              `仓库库存不足！还差 ${order.quantity - currentStock} 个 ${order.itemName}`,
                            );
                          }
                        }}
                        className={`px-5 py-2.5 rounded-xl font-bold text-sm transition-all active:scale-95 ${
                          (inventory[order.itemId] || 0) >= order.quantity
                            ? "bg-gradient-to-r from-[#A8C8BA] to-[#8FA99D] text-white shadow-[0_4px_10px_rgba(168,200,186,0.4)]"
                            : "bg-[#F5F5F5] text-[#B0B0B0] cursor-not-allowed border border-[#EAEAEA]"
                        }`}
                      >
                        {(inventory[order.itemId] || 0) >= order.quantity
                          ? "交付物资"
                          : "库存不足"}
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="text-center text-[#8C917B] mt-24">
                <i className="ph-fill ph-scroll text-6xl mb-4 opacity-40"></i>
                <p className="font-bold text-lg text-[#5A5F4D]">悬赏榜单暂空</p>
                <p className="text-sm mt-2 opacity-80">
                  快去劳作一番，点击上方按钮招揽买家吧
                </p>
              </div>
            )}
          </div>
        </div>
      )}

      {/* ==== 新增：果实详情弹窗 ==== */}
      {showFruitDetail && selectedFruit && (
        <div className="fixed inset-0 bg-black/50 z-[1100] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md animate-slide-up">
            {/* 弹窗头部 */}
            <div className="p-5 flex justify-between items-center border-b border-gray-100">
              <h3 className="text-xl font-bold text-[#5A5F4D]">果实详情</h3>
              <button
                onClick={() => setShowFruitDetail(false)}
                className="w-8 h-8 rounded-full bg-[#f0f0f0] flex items-center justify-center text-[#8C8C8C] active:scale-90 transition-transform"
              >
                <i className="ph-bold ph-x"></i>
              </button>
            </div>

            {/* 果实信息 */}
            <div className="p-6">
              <div className="flex items-center gap-4 mb-4">
                {/* 左上角果实图片 */}
                <div className="w-20 h-20 rounded-xl bg-[#F9F7F5] flex items-center justify-center shadow-inner">
                  <img
                    src={selectedFruit.image}
                    style={{ width: 60 }}
                    alt={selectedFruit.name}
                  />
                </div>
                {/* 旁边是名称 */}
                <div>
                  <h4 className="text-lg font-bold text-[#5A5F4D]">
                    {selectedFruit.name}
                  </h4>
                  <p className="text-sm text-[#8C917B] mt-1">点击查看详情</p>
                </div>
              </div>

              {/* 下面是该果实的简介 */}
              <div className="mt-4 bg-[#F9F7F5] p-4 rounded-xl border-l-4 border-[#D99E82]">
                <h5 className="text-sm font-bold text-[#8C917B] mb-2">
                  果实简介
                </h5>
                <p className="text-sm text-[#5A5F4D] leading-relaxed">
                  {selectedFruit.description}
                </p>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ==== 新增：选择查看他人农场的侧滑菜单 ==== */}
      {showCharSelectForFarm && (
        <div className="fixed inset-x-0 bottom-0 bg-[#FDFCF8] rounded-t-3xl shadow-2xl z-[1000] animate-slide-up h-[60vh] flex flex-col">
          <div className="p-5 flex justify-between items-center border-b border-[#F2EFDE]">
            <h3 className="text-lg font-bold text-[#5A5F4D]">潜入谁的农场？</h3>
            <button
              onClick={() => setShowCharSelectForFarm(false)}
              className="text-[#8C8C8C] text-xl"
            >
              ×
            </button>
          </div>
          <div className="flex-1 overflow-y-auto p-4 flex flex-col gap-3">
            {(availableFarmChars || []).map((char) => (
              <div
                key={char.id}
                onClick={() => handleSelectCharacterToView(char)}
                className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 flex items-center gap-4 cursor-pointer active:scale-95 transition-transform"
              >
                <div
                  className="w-12 h-12 rounded-full text-white flex items-center justify-center font-bold text-lg"
                  style={{
                    backgroundColor: char.avatarColor || "#D99E82",
                  }}
                >
                  {(char.name || "")[0] || "?"}
                </div>
                <div className="flex flex-col">
                  <span className="font-bold text-[#5A5F4D]">{char.name}</span>
                  <span className="text-xs text-gray-400 mt-1 truncate w-48">
                    性格：{char.profile?.personality || "高深莫测"}
                  </span>
                </div>
                <i className="ph-bold ph-caret-right ml-auto text-gray-300"></i>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ==== 新增：加载他人农场的全屏遮罩 ==== */}
      {isLoadingOtherFarm && (
        <div className="fixed inset-0 z-[2000] bg-black/60 backdrop-blur-md flex flex-col items-center justify-center text-white">
          <iconify-icon
            icon="line-md:loading-twotone-loop"
            style={{ fontSize: "50px", color: "#A8C8BA" }}
          ></iconify-icon>
          <p className="mt-4 font-serif tracking-widest text-lg">
            正在施展缩地成寸之术...
          </p>
        </div>
      )}

      {/* ==== 新增：查看他人作物的心声面板 ==== */}
      {showOtherCropDetail && selectedOtherCrop && (
        <div
          className="fixed inset-0 bg-black/50 z-[1100] flex items-center justify-center p-4"
          onClick={() => setShowOtherCropDetail(false)}
        >
          <div
            className="bg-[#FDFCF8] rounded-3xl shadow-2xl w-full max-w-sm animate-popIn p-6 border-2 border-[#D99E82]"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between mb-4 pb-3 border-b border-gray-200">
              <div className="flex items-center gap-2">
                <div className="w-8 h-8 rounded-full bg-[#A8C8BA] text-white flex items-center justify-center text-xs font-bold">
                  {(viewingCharacter?.name || "")[0] || "?"}
                </div>
                <span className="font-bold text-[#5A5F4D]">
                  {viewingCharacter?.name} 的作物
                </span>
              </div>
              <span className="text-xs bg-[#F5F5F5] px-2 py-1 rounded text-gray-500 font-mono">
                记载于：{selectedOtherCrop.logTime}
              </span>
            </div>

            <div className="flex items-center gap-4 mb-4">
              <div className="w-16 h-16 bg-white rounded-xl shadow-inner flex items-center justify-center border border-gray-100 p-2">
                <img
                  src={getFruitImage(selectedOtherCrop.id)}
                  style={{
                    width: "100%",
                    height: "100%",
                    objectFit: "contain",
                  }}
                />
              </div>
              <div className="flex flex-col">
                <span className="font-bold text-[#D6724B]">
                  {FRUIT_NAMES[selectedOtherCrop.id]}
                </span>
                <span className="text-xs text-gray-400 mt-1">
                  状态：
                  {selectedOtherCrop.fruiting
                    ? "已成熟 (可使用镰刀偷取)"
                    : "生长中"}
                </span>
              </div>
            </div>

            <div className="bg-white p-4 rounded-xl border-l-4 border-[#A8C8BA] shadow-sm relative">
              <i className="ph-fill ph-quotes text-gray-200 text-3xl absolute -top-2 -left-2"></i>
              <p className="text-sm text-[#5A5F4D] italic leading-relaxed relative z-10 pl-2">
                {selectedOtherCrop.monologue}
              </p>
            </div>

            <button
              onClick={() => setShowOtherCropDetail(false)}
              className="mt-6 w-full py-3 bg-[#E8C3A8] text-white font-bold rounded-xl active:scale-95 transition-transform shadow-md"
            >
              阅毕
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

