  // 将现代时间转换为古代时间说法
  const convertToAncientTime = (timeStr) => {
    try {
      // 解析时间字符串，格式为 "HH:MM"
      const [hour, minute] = timeStr.split(":").map(Number);

      // 时辰名称
      const timeNames = [
        "子时",
        "丑时",
        "寅时",
        "卯时",
        "辰时",
        "巳时",
        "午时",
        "未时",
        "申时",
        "酉时",
        "戌时",
        "亥时",
      ];

      // 计算时辰索引（子时对应23-1点，所以需要调整）
      let timeIndex = Math.floor((hour + 1) / 2) % 12;

      // 计算刻数（每刻15分钟）
      const quarter = Math.floor(minute / 15) + 1;

      // 计算剩余分钟
      const remainingMinutes = minute % 15;

      // 构建古代时间说法
      let ancientTime = timeNames[timeIndex];

      if (quarter > 0) {
        ancientTime += `${quarter}刻`;
      }

      if (remainingMinutes > 0) {
        ancientTime += "多";
      }

      return ancientTime;
    } catch (error) {
      console.error("时间转换错误:", error);
      return timeStr;
    }
  };

