                    borderRadius: msg.isMe ? "14px 2px 14px 14px" : "2px 14px 14px 14px",
                    maxWidth: "85%",
                    wordBreak: "break-word",
                    boxShadow: "0 3px 12px rgba(0, 0, 0, 0.35)",
                    border: "1px solid rgba(255, 255, 255, 0.6)",
