                  background:
                    "linear-gradient(to right, #b88d55 0%, #e1c48e 15%, #fdf5d6 40%, #fdf5d6 60%, #e1c48e 90%, #7a5a30 100%)",
                  boxShadow:
                    "2px 2px 6px rgba(0, 0, 0, 0.15), inset 1px 0px 2px rgba(255, 255, 255, 0.6)",
                  position: "relative",
