// ==================== 用户身份 (Persona) 管理组件 START ====================

const UserProfilePage = ({ onClose, onUpdateActiveUser }) => {
  const { useState, useEffect, useRef } = React;
  const fileInputRef = useRef(null);

  // 默认空表单数据
  const initialForm = {
    id: null,
    name: "",
    avatar: "", // Base64 string
    gender: "",
    age: "",
    personality: "",
    background: "",
    style: "",
  };

  const [personas, setPersonas] = useState([]);
  const [activeId, setActiveId] = useState(null);
  const [formData, setFormData] = useState(initialForm);
  const [isEditing, setIsEditing] = useState(false); // true=编辑/新建模式, false=列表模式

  // 初始化加载
  useEffect(() => {
    try {
      const savedPersonas = JSON.parse(
        localStorage.getItem("user_personas") || "[]",
      );
      const savedActiveId = localStorage.getItem("active_persona_id");

      setPersonas(savedPersonas);
      if (savedActiveId) {
        setActiveId(Number(savedActiveId));
      } else if (savedPersonas.length > 0) {
        // 如果没有选中的，默认选第一个
        setActiveId(savedPersonas[0].id);
        localStorage.setItem("active_persona_id", savedPersonas[0].id);
      }
    } catch (e) {
      console.error("加载身份数据失败", e);
    }
  }, []);

  // 处理图片上传 (转Base64以存入localStorage)
  const handleImageUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        // 注意：localStorage 有大小限制(约5MB)，大图可能导致保存失败
        // 实际生产中应压缩图片或上传服务器，这里简化直接存
        setFormData((prev) => ({ ...prev, avatar: reader.result }));
      };
      reader.readAsDataURL(file);
    }
  };

  // 保存表单
  const handleSave = () => {
    if (!formData.name) {
      alert("请填写名字");
      return;
    }

    let newPersonas;
    const newId = formData.id || Date.now();
    const newPersona = { ...formData, id: newId };

    if (formData.id) {
      // 更新现有
      newPersonas = personas.map((p) =>
        p.id === formData.id ? newPersona : p,
      );
    } else {
      // 新建
      newPersonas = [...personas, newPersona];
    }

    setPersonas(newPersonas);
    localStorage.setItem("user_personas", JSON.stringify(newPersonas));

    // 如果是第一个创建的，或者正在编辑当前选中的，自动设为激活
    if (personas.length === 0 || activeId === newId) {
      handleSelect(newId, newPersonas);
    }

    setIsEditing(false);
    setFormData(initialForm);
  };

  // 选中身份
  const handleSelect = (id, currentList = personas) => {
    setActiveId(id);
    localStorage.setItem("active_persona_id", id);

    // 通知 MasterApp 更新显示
    const selected = currentList.find((p) => p.id === id);
    if (selected && onUpdateActiveUser) {
      onUpdateActiveUser(selected);
    }

    // 震动反馈
    if (navigator.vibrate) navigator.vibrate(10);
  };

  // 删除身份
  const handleDelete = (id) => {
    if (confirm("确定要删除这个身份吗？")) {
      const newPersonas = personas.filter((p) => p.id !== id);
      setPersonas(newPersonas);
      localStorage.setItem("user_personas", JSON.stringify(newPersonas));
      setIsEditing(false);

      // 如果删除了当前的，重置选中
      if (activeId === id) {
        setActiveId(null);
        localStorage.removeItem("active_persona_id");
        // 通知外部重置
        if (onUpdateActiveUser) onUpdateActiveUser(null);
      }
    }
  };

  // 开始编辑
  const startEdit = (persona = null) => {
    if (persona) {
      setFormData(persona);
    } else {
      setFormData(initialForm);
    }
    setIsEditing(true);
  };

  return (
    <div className="profile-container">
      {isEditing ? (
        /* --- 编辑模式 --- */
        <div className="fade-in">
          <div style={{ textAlign: "center", marginBottom: "20px" }}>
            <h3 style={{ fontSize: "18px", color: "#5a5f4d" }}>
              {formData.id ? "编辑身份" : "新建身份"}
            </h3>
          </div>

          <div
            className="avatar-uploader"
            onClick={() => fileInputRef.current.click()}
          >
            {formData.avatar ? (
              <img
                src={formData.avatar}
                className="avatar-preview"
                alt="avatar"
              />
            ) : (
              <div className="avatar-placeholder">
                <i
                  data-lucide="camera"
                  style={{ width: 24, height: 24, margin: "0 auto 4px" }}
                ></i>
                点击上传
              </div>
            )}
            <input
              type="file"
              ref={fileInputRef}
              onChange={handleImageUpload}
              accept="image/*"
              style={{ display: "none" }}
            />
          </div>

          <div className="pf-form-group">
            <label className="pf-label">名字</label>
            <input
              className="pf-input"
              value={formData.name}
              onChange={(e) =>
                setFormData({ ...formData, name: e.target.value })
              }
              placeholder="例如：广陵王"
            />
          </div>

          <div style={{ display: "flex", gap: "12px" }}>
            <div className="pf-form-group" style={{ flex: 1 }}>
              <label className="pf-label">性别</label>
              <input
                className="pf-input"
                value={formData.gender}
                onChange={(e) =>
                  setFormData({ ...formData, gender: e.target.value })
                }
                placeholder="例如：女"
              />
            </div>
            <div className="pf-form-group" style={{ flex: 1 }}>
              <label className="pf-label">年龄</label>
              <input
                className="pf-input"
                value={formData.age}
                onChange={(e) =>
                  setFormData({ ...formData, age: e.target.value })
                }
                placeholder="例如：18"
              />
            </div>
          </div>

          <div className="pf-form-group">
            <label className="pf-label">性格特点</label>
            <input
              className="pf-input"
              value={formData.personality}
              onChange={(e) =>
                setFormData({ ...formData, personality: e.target.value })
              }
              placeholder="例如：隐忍、坚毅、腹黑"
            />
          </div>

          <div className="pf-form-group">
            <label className="pf-label">个人背景</label>
            <textarea
              className="pf-textarea"
              value={formData.background}
              onChange={(e) =>
                setFormData({ ...formData, background: e.target.value })
              }
              placeholder="身份背景故事，将会影响AI对你的认知..."
            />
          </div>

          <div className="pf-form-group">
            <label className="pf-label">语言风格</label>
            <textarea
              className="pf-textarea"
              value={formData.style}
              onChange={(e) =>
                setFormData({ ...formData, style: e.target.value })
              }
              placeholder="例如：说话简练，喜欢用古风词汇..."
            />
          </div>

          <div className="btn-group">
            <button
              className="pf-btn pf-btn-secondary"
              onClick={() => setIsEditing(false)}
            >
              取消
            </button>
            {formData.id && (
              <button
                className="pf-btn pf-btn-delete"
                onClick={() => handleDelete(formData.id)}
              >
                删除
              </button>
            )}
            <button className="pf-btn pf-btn-primary" onClick={handleSave}>
              保存
            </button>
          </div>
        </div>
      ) : (
        /* --- 列表模式 --- */
        <div className="fade-in">
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: "20px",
            }}
          >
            <h3
              style={{
                fontSize: "18px",
                color: "#5a5f4d",
                fontWeight: "bold",
              }}
            >
              身份配置库
            </h3>
            <button
              className="pf-btn pf-btn-primary"
              style={{ padding: "8px 16px", fontSize: "12px" }}
              onClick={() => startEdit(null)}
            >
              <i data-lucide="plus" style={{ width: 14, height: 14 }}></i> 新建
            </button>
          </div>

          <div style={{ paddingBottom: "80px" }}>
            {personas.length === 0 ? (
              <div
                style={{
                  textAlign: "center",
                  color: "#ccc",
                  marginTop: "50px",
                }}
              >
                暂无保存的身份
                <br />
                请点击右上角新建
              </div>
            ) : (
              personas.map((p) => (
                <div
                  key={p.id}
                  className={`persona-card ${
                    activeId === p.id ? "active" : ""
                  }`}
                  onClick={() => handleSelect(p.id)}
                  // [修改点1] 给右侧留出足够的安全距离，防止文字和编辑按钮重叠
                  style={{
                    position: "relative",
                    paddingRight: "60px",
                    minHeight: "80px",
                  }}
                >
                  <div
                    style={{
                      width: "48px",
                      height: "48px",
                      borderRadius: "50%",
                      background: "#eee",
                      overflow: "hidden",
                      flexShrink: 0,
                    }}
                  >
                    {p.avatar ? (
                      <img
                        src={p.avatar}
                        style={{
                          width: "100%",
                          height: "100%",
                          objectFit: "cover",
                        }}
                      />
                    ) : (
                      <div
                        style={{
                          width: "100%",
                          height: "100%",
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "center",
                          color: "#aaa",
                        }}
                      >
                        无
                      </div>
                    )}
                  </div>

                  <div className="persona-info">
                    <div
                      style={{
                        display: "flex",
                        alignItems: "center",
                        flexWrap: "wrap",
                        gap: "6px",
                      }}
                    >
                      <span className="persona-name">{p.name}</span>
                      {p.age && <span className="persona-tag">{p.age}岁</span>}
                    </div>
                    <div className="persona-desc">
                      {p.personality || "暂无性格描述"}
                    </div>
                  </div>

                  {/* [修改点2] 选中状态图标：添加 pointerEvents: 'none' 防止阻挡点击 */}
                  {activeId === p.id && (
                    <div
                      className="active-check"
                      style={{
                        pointerEvents: "none",
                        zIndex: 1,
                        top: "8px",
                        right: "8px",
                      }}
                    >
                      <i
                        data-lucide="check-circle"
                        style={{
                          width: 18,
                          height: 18,
                          fill: "#9fa5d5",
                          color: "white",
                        }}
                      ></i>
                    </div>
                  )}

                  {/* [修改点3] 编辑按钮：使用绝对定位覆盖右侧区域，大幅增加点击热区 */}
                  <div
                    onClick={(e) => {
                      e.stopPropagation(); // 阻止冒泡，防止触发选中
                      startEdit(p);
                    }}
                    style={{
                      position: "absolute",
                      top: 0,
                      right: 0,
                      bottom: 0,
                      width: "60px", // 极大的触控宽度
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      cursor: "pointer",
                      zIndex: 10, // 确保层级最高
                      borderLeft: "1px solid rgba(0,0,0,0.03)", // 视觉分割线（可选）
                    }}
                  >
                    {/* 视觉上的按钮图标，实际点击区域是外面那个大框 */}
                    <div
                      style={{
                        width: "32px",
                        height: "32px",
                        borderRadius: "50%",
                        background: "#f0f2f5",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                      }}
                    >
                      <i
                        data-lucide="edit-3"
                        style={{ width: 16, height: 16, color: "#666" }}
                      ></i>
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      )}
    </div>
  );
};

