// ==================== 阅读器详情组件 (ReaderDetailPage) ====================
// ==================== 阅读器详情组件 (支持 AI 批注版) ====================
const ReaderDetailPage = ({
  book,
  isOpen,
  onClose,
  onProgressUpdate,
  onUpdateBookContent, // [新增]
  onAddToBookshelf, // [新增]
}) => {
  const [pages, setPages] = React.useState([]);
  const [currentPage, setCurrentPage] = React.useState(0);
  const [showMenu, setShowMenu] = React.useState(false);
  const [fontSize, setFontSize] = React.useState(18);

  // --- 共读 & 批注状态 ---
  const [allChars, setAllChars] = React.useState([]);
  const [activeChar, setActiveChar] = React.useState(null);
  const [showCharSelector, setShowCharSelector] = React.useState(false);

  // 气泡与输入
  const [aiBubble, setAiBubble] = React.useState("一起来读书吧...");
  const [userBubble, setUserBubble] = React.useState("点击输入感想...");
  const [isInputMode, setIsInputMode] = React.useState(false);
  const [isAiTyping, setIsAiTyping] = React.useState(false);

  // 批注数据结构: { pageIndex, quote, comment, id }
  const [annotations, setAnnotations] = React.useState([]);
  const [activeNote, setActiveNote] = React.useState(null); // 当前点击查看的批注
  // [新增] 用于处理长按的计时器引用
  const pressTimer = React.useRef(null);

  // [新增] 继续生成逻辑
  const [isGeneratingMore, setIsGeneratingMore] = React.useState(false);

  const handleGenerateMore = async () => {
    if (isGeneratingMore) return;
    setIsGeneratingMore(true);
    try {
      const worldContext = window.getWorldBookContext
        ? await window.getWorldBookContext()
        : "无特定背景设定";
      // 取文章末尾做上下文
      const previousContext = book.fullText.substring(
        Math.max(0, book.fullText.length - 800),
      );

      const sysPrompt = "你是一位东汉时期的著书人。";
      const userPrompt = `
                    【世界设定】
                    ${worldContext}

                    【书籍信息】
                    书名：${book.title}
                    作者：${book.author}

                    【前文回顾】
                    ...${previousContext}

                    【任务】
                    请紧接着前文的情节或论述，继续往下写大约800-1000字的内容。

                    【要求】
                    1. 必须顺着前文的逻辑和文风继续。
                    2. 绝对不能脱离东汉背景。
                    3. 直接输出小说的正文文本，不要输出任何额外的提示语、开场白或Markdown标记。
                  `;

      if (window.sendToLLM) {
        window.sendToLLM(
          [
            { role: "system", content: sysPrompt },
            { role: "user", content: userPrompt },
          ],
          null,
          (reply) => {
            const newContent = reply.replace(/```[a-z]*|```/gi, "").trim();
            const updatedFullText = book.fullText + "\n\n" + newContent;

            if (onUpdateBookContent) {
              onUpdateBookContent({ ...book, fullText: updatedFullText });
            }
            setIsGeneratingMore(false);
          },
          (err) => {
            console.error(err);
            alert("催更失败，作者外出取材了");
            setIsGeneratingMore(false);
          },
        );
      }
    } catch (e) {
      console.error(e);
      setIsGeneratingMore(false);
    }
  };

  // [修改] 初始化：智能动态分页算法
  React.useEffect(() => {
    const initReader = async () => {
      if (isOpen && book && book.fullText) {
        // 1. 获取屏幕实际可用尺寸
        const viewportHeight = window.innerHeight;
        const viewportWidth = window.innerWidth;

        // 2. 计算排版参数
        // 垂直扣除：顶部留白(20) + 底部共读区保留高度(150) + 底部页码预留(20)
        const safeHeight = viewportHeight - 190;
        // 水平扣除：左右 Padding (24 * 2 = 48)
        const safeWidth = viewportWidth - 48;

        // 行高倍数 (需与 CSS .reader-content-area 的 line-height: 1.8 保持一致)
        const lineHeightRatio = 1.8;
        const singleLineHeight = fontSize * lineHeightRatio;

        // 3. 计算容量
        const linesPerPage = Math.floor(safeHeight / singleLineHeight);
        // 汉字大概占 1em，英文占 0.5em，这里取平均值 1 来估算，并在最后设置缓冲
        const charsPerLine = Math.floor(safeWidth / fontSize);

        // 4. 得出每页字符数 (减去 50 个字符作为“安全缓冲”，防止标点符号溢出)
        // 最小值设为 50 防止极端情况
        const charsPerPage = Math.max(50, linesPerPage * charsPerLine - 50);

        // 5. 执行切分
        const totalLength = book.fullText.length;
        const totalPages = Math.ceil(totalLength / charsPerPage);

        const newPages = [];
        for (let i = 0; i < totalPages; i++) {
          const start = i * charsPerPage;
          // 简单切分可能截断单词，但对于中文阅读影响较小
          // 进阶做法是寻找最近的标点符号换页，这里为了性能保持按字切分
          newPages.push(book.fullText.substring(start, start + charsPerPage));
        }

        setPages(newPages);

        // 恢复进度 (防止页码越界)
        const savedPage = book.progress || 0;
        setCurrentPage(savedPage >= totalPages ? 0 : savedPage);
      }
      // 加载角色
      try {
        // 优先使用 IndexedDB 的 chatCharacterStore
        if (window.chatCharacterStore) {
          const characters = await window.chatCharacterStore.getAll();
          setAllChars(characters);
        } else {
          // 兼容旧版本，从 localStorage 获取
          const chats = JSON.parse(
            localStorage.getItem("t8_chat_list") || "[]",
          );
          setAllChars(chats);
        }
      } catch (e) {
        console.error("加载角色失败:", e);
      }
    };

    initReader();
  }, [isOpen, book, fontSize]); // 当字号改变时，会自动重新计算分页

  const turnPage = (direction) => {
    let newPage = currentPage;
    if (direction === "next") {
      if (currentPage < pages.length - 1) newPage = currentPage + 1;
    } else {
      if (currentPage > 0) newPage = currentPage - 1;
    }
    if (newPage !== currentPage) {
      setCurrentPage(newPage);
      if (onProgressUpdate) onProgressUpdate(book.id, newPage);
      if (activeChar) setAiBubble("（正在阅读本页...）");
      setActiveNote(null); // 翻页关闭弹窗
    }
  };

  // --- 核心逻辑：渲染带有批注的文本 ---
  // --- 核心逻辑：渲染带有批注的文本 (点击触发版) ---
  const renderPageContent = () => {
    const rawText = pages[currentPage];
    if (!rawText) return "";

    const pageNotes = annotations.filter((n) => n.pageIndex === currentPage);
    if (pageNotes.length === 0) return rawText;

    let elements = [];
    let lastIndex = 0;

    // 按位置排序
    const sortedNotes = pageNotes.sort(
      (a, b) => rawText.indexOf(a.quote) - rawText.indexOf(b.quote),
    );

    // 点击事件处理
    const handleNoteClick = (note) => {
      setActiveNote(note);
      // 震动反馈
      if (navigator.vibrate) navigator.vibrate(50);
    };

    sortedNotes.forEach((note) => {
      const startIdx = rawText.indexOf(note.quote, lastIndex);
      // 简单的防重叠逻辑：确保起始位置在上一段结束之后
      if (startIdx !== -1 && startIdx >= lastIndex) {
        // 1. 添加普通文本
        elements.push(rawText.substring(lastIndex, startIdx));

        // 2. 添加高亮文本 (绑定点击事件)
        elements.push(
          <span
            key={note.id}
            className="ai-annotation-mark"
            onClick={(e) => {
              e.stopPropagation(); // 阻止冒泡，防止触发翻页和菜单
              handleNoteClick(note);
            }}
            onTouchEnd={(e) => {
              e.stopPropagation();
              handleNoteClick(note);
            }}
            onMouseDown={(e) => {
              e.stopPropagation(); // 阻止鼠标按下事件冒泡
            }}
            onTouchStart={(e) => {
              e.stopPropagation(); // 阻止触摸事件冒泡
            }}
          >
            {note.quote}
          </span>,
        );
        lastIndex = startIdx + note.quote.length;
      }
    });

    // 添加剩余文本
    elements.push(rawText.substring(lastIndex));

    return elements;
  };

  // --- AI 功能 ---

  // 1. 普通共读聊天
  const handleAITalk = () => {
    if (!activeChar || isAiTyping) return;
    triggerLLM("talk");
  };

  // 2. 触发 AI 批注
  const handleAIAnnotate = () => {
    if (!activeChar || isAiTyping) return;
    triggerLLM("annotate");
  };

  // 统一 LLM 请求处理
  // 统一 LLM 请求处理 (支持多条批注 & JSON格式)
  const triggerLLM = (mode) => {
    setIsAiTyping(true);
    setAiBubble(mode === "annotate" ? "正在阅读并思考批注..." : "正在思考...");

    const currentText = pages[currentPage] || "";
    // 适当增加上下文长度以便 AI 更好理解
    const textSnippet = currentText.substring(0, 1000);
    const systemPrompt = window.buildSystemPrompt(
      activeChar.profile || { name: activeChar.name },
    );

    let userPrompt = "";
    if (mode === "annotate") {
      // [修改] 请求 JSON 数组格式，允许 1-3 条批注
      userPrompt = `
                                                                                                                     【指令】
                                                                                                                     请以“${activeChar.name}”的身份阅读下文。
                                                                                                                     根据你的人设、经历和性格，挑选 **1到3处** 你觉得有意思、想吐槽、或者感同身受的句子进行批注。
                                                                                                                     如果没有特别想说的，1处也可以。不要强行批注，要符合你的人设逻辑（比如傲娇的角色可能会挑刺，温柔的角色会共情）。

                                                                                                                     【输出格式严格要求】
                                                                                                                     请仅输出一个 JSON 格式的数组，不要包含 Markdown 代码块标记或其他文字。格式如下：
                                                                                                                     [
                                                                                                                       { "quote": "原文句子1", "comment": "你的评论1" },
                                                                                                                       { "quote": "原文句子2", "comment": "你的评论2" }
                                                                                                                     ]

                                                                                                                     【正文片段】
                                                                                                                     ${textSnippet}
                                                                                                                     `;
    } else {
      userPrompt = `
                                                                                                                     【当前情境】你正在陪用户阅读书籍《${book.title}》。
                                                                                                                     【正文片段】“${textSnippet.substring(0, 500)}...”
                                                                                                                     【用户刚才说】“${
                                                                                                                       userBubble ===
                                                                                                                       "点击输入感想..."
                                                                                                                         ? "(用户沉默)"
                                                                                                                         : userBubble
                                                                                                                     }”
                                                                                                                     【指令】请根据正文和用户感想，以“${
                                                                                                                       activeChar.name
                                                                                                                     }”的身份发表简短评论。50字以内。
                                                                                                                     `;
    }

    const apiMessages = [
      { role: "system", content: systemPrompt },
      { role: "user", content: userPrompt },
    ];

    window.sendToLLM(
      apiMessages,
      null,
      (reply) => {
        setIsAiTyping(false);
        if (mode === "annotate") {
          try {
            // [修改] 解析 JSON 数组
            // 尝试清理可能存在的 markdown 标记 ```json ... ```
            const cleanJson = reply.replace(/```json|```/g, "").trim();
            const notesData = JSON.parse(cleanJson);

            if (Array.isArray(notesData) && notesData.length > 0) {
              let addedCount = 0;
              const newNotes = [];

              notesData.forEach((item) => {
                const quote = item.quote.trim();
                const comment = item.comment.trim();

                // 验证原文是否存在且不重复
                if (
                  currentText.includes(quote) &&
                  !annotations.some((n) => n.quote === quote)
                ) {
                  newNotes.push({
                    id: Date.now() + Math.random(), // 随机ID防止冲突
                    pageIndex: currentPage,
                    quote: quote,
                    comment: comment,
                    charName: activeChar.name,
                    avatarColor: activeChar.avatarColor,
                  });
                  addedCount++;
                }
              });

              if (addedCount > 0) {
                setAnnotations((prev) => [...prev, ...newNotes]);
                setAiBubble(`我标注了 ${addedCount} 处我觉得有意思的地方。`);
              } else {
                setAiBubble("（看了一遍，好像没有特别想标注的...）");
              }
            } else {
              setAiBubble("（看完了，但这页没什么触动我的。）");
            }
          } catch (e) {
            console.error("批注解析失败", e);
            setAiBubble("（笔记写乱了，没法展示...）");
          }
        } else {
          // 普通聊天
          setAiBubble(reply.split("|||")[0]);
        }
      },
      (err) => {
        setIsAiTyping(false);
        setAiBubble("（连接断开了...）");
      },
    );
  };

  const handleUserSend = () => {
    setIsInputMode(false);
    // 用户发完，可以选择是否自动触发 AI，这里留给用户手动点击 AI 气泡触发更有仪式感
    // 或者你可以直接调用 handleAITrigger();
  };

  // 进度条拖拽
  const handleSliderChange = (e) => {
    const newVal = Number(e.target.value);
    const targetPage = Math.floor((newVal / 100) * (pages.length - 1));
    setCurrentPage(targetPage);
    if (onProgressUpdate) onProgressUpdate(book.id, targetPage);
  };

  if (!book || !isOpen) return null;
  const progressPercent =
    pages.length > 1 ? (currentPage / (pages.length - 1)) * 100 : 0;

  return (
    <div
      className={`reader-detail-overlay ${isOpen ? "open" : ""} ${
        showMenu ? "reader-menu-visible" : ""
      }`}
    >
      {/* 1. 顶部菜单 */}
      <div className="reader-menu-bar menu-top">
        <div
          onClick={onClose}
          style={{
            display: "flex",
            alignItems: "center",
            gap: "8px",
            cursor: "pointer",
          }}
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="m15 18-6-6 6-6" />
          </svg>
          <span style={{ fontSize: "14px" }}>书架</span>
        </div>

        {/* 书名 & 角色选择触发器 */}
        <div
          onClick={() => setShowCharSelector(!showCharSelector)}
          style={{
            fontSize: "14px",
            fontWeight: "bold",
            cursor: "pointer",
            display: "flex",
            alignItems: "center",
            gap: "4px",
          }}
        >
          {book.title || "未知书名"}
          <span
            style={{
              fontSize: "10px",
              color: "#999",
              padding: "2px 6px",
              background: "#eee",
              borderRadius: "4px",
            }}
          >
            {activeChar && activeChar.name
              ? `与 ${activeChar.name} 共读`
              : "选择伴读"}
          </span>
        </div>

        <div>
          <i data-lucide="highlighter"></i>
        </div>

        {/* 角色选择弹窗 */}
        {showCharSelector && (
          <div className="char-selector-modal no-scrollbar">
            {Array.isArray(allChars) &&
              allChars.map((char) =>
                char && char.id && char.name ? (
                  <div
                    key={char.id}
                    onClick={() => {
                      setActiveChar(char);
                      setShowCharSelector(false);
                      setAiBubble(`我们要开始读《${book.title}》了吗？`);
                    }}
                    style={{
                      padding: "8px",
                      borderBottom: "1px solid #f0f0f0",
                      display: "flex",
                      alignItems: "center",
                      gap: "8px",
                      cursor: "pointer",
                    }}
                  >
                    <div
                      style={{
                        width: 24,
                        height: 24,
                        borderRadius: "50%",
                        background: char.avatarColor || "#ccc",
                      }}
                    ></div>
                    <span style={{ fontSize: "13px" }}>{char.name}</span>
                  </div>
                ) : null,
              )}
            {(!Array.isArray(allChars) || allChars.length === 0) && (
              <div style={{ fontSize: "12px", color: "#999" }}>
                无角色，请先去传讯添加
              </div>
            )}
          </div>
        )}
      </div>

      {/* 2. 内容区域 */}
      <div
        className="reader-content-area"
        style={{ fontSize: `${fontSize}px` }}
      >
        <div
          className="reader-tap-zone zone-left"
          onClick={() => turnPage("prev")}
        ></div>
        <div
          className="reader-tap-zone zone-center"
          onClick={() => setShowMenu(!showMenu)}
        ></div>
        <div
          className="reader-tap-zone zone-right"
          onClick={() => turnPage("next")}
        ></div>
        <div
          style={{
            whiteSpace: "pre-wrap",
            height: "100%",
            paddingBottom: "120px" /* 给共读区留空 */,
          }}
        >
          {renderPageContent()}

          {/* 新增：如果是一本AI生成的书籍，且在最后一页，显示继续生成和添加书架按钮 */}
          {book.isStoreBook && currentPage === pages.length - 1 && (
            <div
              style={{
                display: "flex",
                justifyContent: "center",
                gap: "15px",
                marginTop: "40px",
                paddingBottom: "40px",
                position: "relative",
                zIndex: 10,
              }}
            >
              <button
                onClick={handleGenerateMore}
                disabled={isGeneratingMore}
                style={{
                  padding: "12px 24px",
                  background:
                    "linear-gradient(135deg, #D6724B 0%, #C95E36 100%)",
                  color: "white",
                  borderRadius: "24px",
                  border: "none",
                  fontWeight: "bold",
                  fontSize: "16px",
                  boxShadow: "0 4px 12px rgba(214,114,75,0.4)",
                  opacity: isGeneratingMore ? 0.7 : 1,
                  cursor: isGeneratingMore ? "not-allowed" : "pointer",
                }}
              >
                {isGeneratingMore ? "奋笔疾书中..." : "继续生成"}
              </button>

              <button
                onClick={() => {
                  if (onAddToBookshelf) onAddToBookshelf(book);
                }}
                style={{
                  padding: "12px 24px",
                  background:
                    "linear-gradient(135deg, #8FA99D 0%, #5A8F6D 100%)",
                  color: "white",
                  borderRadius: "24px",
                  border: "none",
                  fontWeight: "bold",
                  fontSize: "16px",
                  boxShadow: "0 4px 12px rgba(90,143,109,0.4)",
                  cursor: "pointer",
                }}
              >
                添加书架
              </button>
            </div>
          )}
        </div>
        <div
          style={{
            position: "absolute",
            bottom: "100px",
            right: "20px",
            fontSize: "10px",
            color: "#999",
          }}
        >
          {currentPage + 1} / {pages.length}
        </div>
      </div>

      {/* 3. [新增] 共读浮层 (始终显示在底部，但在菜单之下) */}
      {activeChar && activeChar.name && (
        <div
          className="co-read-panel"
          style={{ bottom: showMenu ? "60px" : "0" }}
        >
          {/* AI 侧 */}
          <div className="cr-side left">
            <div className="cr-bubble left" onClick={handleAITalk}>
              {aiBubble}
            </div>
            <div style={{ display: "flex", gap: "8px" }}>
              <div
                className="cr-avatar"
                style={{ background: activeChar.avatarColor || "#ccc" }}
                onClick={handleAITalk}
              >
                {activeChar.name && activeChar.name[0]
                  ? activeChar.name[0]
                  : "?"}
              </div>
              {/* [新增] 批注按钮 (仅在非菜单模式下显示更整洁) */}
              <button
                onClick={handleAIAnnotate}
                style={{
                  width: "40px",
                  height: "40px",
                  borderRadius: "50%",
                  border: "none",
                  background: "#fff",
                  boxShadow: "0 2px 8px rgba(0,0,0,0.1)",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  cursor: "pointer",
                  color: "#8fa38f",
                }}
              >
                <i data-lucide="pen-tool" style={{ width: 18, height: 18 }}></i>
              </button>
            </div>
          </div>

          {/* 用户侧 (右) */}
          <div className="cr-side right">
            <div
              className="cr-bubble right"
              onClick={() => setIsInputMode(true)}
            >
              {isInputMode ? (
                <textarea
                  className="cr-input"
                  value={userBubble === "点击输入感想..." ? "" : userBubble}
                  onChange={(e) => setUserBubble(e.target.value)}
                  onBlur={() => setIsInputMode(false)}
                  autoFocus
                />
              ) : (
                userBubble
              )}
            </div>
            <div className="cr-avatar" style={{ background: "#fff" }}>
              我
            </div>
          </div>
        </div>
      )}

      {/* 4. 批注详情弹窗 */}
      {activeNote && activeNote.quote && activeNote.comment && (
        <>
          <div className="note-mask" onClick={() => setActiveNote(null)}></div>
          <div className="note-bubble-modal">
            <div className="note-header">
              <div
                className="note-avatar"
                style={{ background: activeNote.avatarColor || "#ccc" }}
              >
                {activeNote.charName && activeNote.charName[0]
                  ? activeNote.charName[0]
                  : "?"}
              </div>
              <span
                style={{
                  fontWeight: "bold",
                  fontSize: "14px",
                  color: "#333",
                }}
              >
                {activeNote.charName || "未知角色"} 的批注
              </span>
            </div>
            <div className="note-quote">“{activeNote.quote || ""}”</div>
            <div className="note-content">{activeNote.comment || ""}</div>
          </div>
        </>
      )}

      {/* 5. 底部菜单 (保持不变) */}
      <div className="reader-menu-bar menu-bottom">
        <div
          style={{
            width: "100%",
            display: "flex",
            alignItems: "center",
            gap: "10px",
            fontSize: "12px",
            color: "#666",
          }}
        >
          <span style={{ minWidth: "30px" }}>进度</span>
          <input
            type="range"
            min="0"
            max="100"
            step="0.1"
            value={progressPercent}
            onChange={(e) => {
              const newVal = Number(e.target.value);
              const targetPage = Math.floor(
                (newVal / 100) * (pages.length - 1),
              );
              setCurrentPage(targetPage);
            }}
            className="reader-slider"
          />
          <span style={{ minWidth: "35px", textAlign: "right" }}>
            {Math.round(progressPercent)}%
          </span>
        </div>
        <div
          style={{
            width: "100%",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <div
            onClick={() => setFontSize((s) => Math.max(14, s - 2))}
            style={{
              padding: "10px",
              background: "#f0eadd",
              borderRadius: "8px",
            }}
          >
            A-
          </div>
          <span style={{ fontSize: "14px" }}>字号: {fontSize}</span>
          <div
            onClick={() => setFontSize((s) => Math.min(26, s + 2))}
            style={{
              padding: "10px",
              background: "#f0eadd",
              borderRadius: "8px",
            }}
          >
            A+
          </div>
        </div>
      </div>
    </div>
  );
};

// ==================== AI 多人荐书组件 (AIBookRecommender Pro) ====================
const AIBookRecommender = ({ books, onConfirm }) => {
  const [isOpen, setIsOpen] = React.useState(false);
  const [status, setStatus] = React.useState("idle"); // idle, loading_recs, selecting, loading_reactions, viewing_reactions

  const [recommendations, setRecommendations] = React.useState([]); // [{char, book, reason}]
  const [reactions, setReactions] = React.useState([]); // [{charName, content, isWinner}]
  const [selectedRec, setSelectedRec] = React.useState(null);

  // 1. 触发推荐 (竞选阶段)
  const handleTrigger = async () => {
    if (!books || books.length === 0) return alert("书架空空如也~");

    // 优先从IndexedDB获取角色，兼容旧版本从localStorage获取
    let chats = [];
    try {
      if (window.chatCharacterStore) {
        const characters = await window.chatCharacterStore.getAll();
        if (characters && characters.length > 0) {
          chats = characters;
        }
      }
    } catch (error) {
      console.error("从IndexedDB获取角色失败:", error);
    }

    // 如果IndexedDB中没有角色，从localStorage获取
    if (chats.length === 0) {
      const savedChats = localStorage.getItem("t8_chat_list");
      if (savedChats) {
        try {
          chats = JSON.parse(savedChats);
        } catch (error) {
          console.error("解析localStorage角色数据失败:", error);
          chats = [];
        }
      }
    }

    if (chats.length === 0) return alert("请先在传讯中添加角色");

    setIsOpen(true);
    setStatus("loading_recs");
    setRecommendations([]);
    setReactions([]);
    setSelectedRec(null);

    // 随机抽取 2-3 名角色 (如果不足2名则全选)
    const shuffled = [...chats].sort(() => 0.5 - Math.random());
    const selectedChars = shuffled.slice(
      0,
      Math.min(3, Math.max(1, chats.length)),
    );

    // 构建 Prompt
    const bookListStr = books
      .map((b) => `ID:${b.id},《${b.title}》`)
      .join("; ");
    const charsInfo = selectedChars
      .map((c) => `角色名:${c.name}, 人设:${c.profile?.personality || "未知"}`)
      .join("\n");

    const systemPrompt = "你正在扮演一个多角色互动的场景。";
    const userPrompt = `
                                                                                                                    【任务】
                                                                                                                    请让以下几位角色，分别从书架中挑选一本他们想推荐给用户读的书。
                                                                                                                    书架：[${bookListStr}]

                                                                                                                    【角色列表】
                                                                                                                    ${charsInfo}

                                                                                                                    【要求】
                                                                                                                    1. 每个角色必须根据自己的人设挑选一本独特的书（尽量不重复）。
                                                                                                                    2. 每个角色给出一句简短的推荐理由（30字以内）。
                                                                                                                    3. **严格返回 JSON 数组**格式：
                                                                                                                    [
                                                                                                                      {"charName": "角色A的名字", "bookId": 书籍ID, "reason": "理由"},
                                                                                                                      {"charName": "角色B的名字", "bookId": 书籍ID, "reason": "理由"}
                                                                                                                    ]
                                                                                                                    `;

    // 调用 API
    window.sendToLLM(
      [
        { role: "system", content: systemPrompt },
        { role: "user", content: userPrompt },
      ],
      null,
      (reply) => {
        try {
          const cleanJson = reply.replace(/```json|```/g, "").trim();
          const data = JSON.parse(cleanJson);

          const recs = [];
          data.forEach((item) => {
            const char = chats.find((c) => c.name === item.charName);
            const book = books.find((b) => b.id == item.bookId);
            if (char && book) {
              recs.push({ char, book, reason: item.reason });
            }
          });

          if (recs.length > 0) {
            setRecommendations(recs);
            setStatus("selecting");
          } else {
            throw new Error("解析为空");
          }
        } catch (e) {
          console.error(e);
          alert("角色们好像没商量好，请重试");
          setIsOpen(false);
        }
      },
      () => {
        setIsOpen(false);
        alert("网络错误");
      },
    );
  };

  // 2. 用户选择 -> 触发反应 (反应阶段)
  const handleSelectRec = (rec) => {
    setSelectedRec(rec);
    setStatus("loading_reactions");

    const winnersName = rec.char.name;
    const losers = recommendations.filter((r) => r.char.name !== winnersName);

    // 构建反应 Prompt
    const losersInfo = losers
      .map((r) => `${r.char.name}(性格:${r.char.profile?.personality})`)
      .join(", ");
    const winnerInfo = `${rec.char.name}(性格:${rec.char.profile?.personality})`;

    const userPrompt = `
                                                                                                                    【情境】
                                                                                                                    用户采纳了【${winnersName}】推荐的书《${rec.book.title}》。
                                                                                                                    其他角色（${losersInfo}）的推荐落选了。

                                                                                                                    【任务】
                                                                                                                    请生成这几位角色的反应对话：
                                                                                                                    1. ${winnersName}：表示开心、得意或感激（符合人设）。
                                                                                                                    2. 落选角色：表示遗憾、吃醋、不服气或傲娇（符合人设）。

                                                                                                                    【要求】
                                                                                                                    严格返回 JSON 数组格式：
                                                                                                                    [
                                                                                                                      {"charName": "${winnersName}", "content": "反应台词"},
                                                                                                                      {"charName": "落选者A", "content": "反应台词"}
                                                                                                                    ]
                                                                                                                    `;

    window.sendToLLM(
      [
        {
          role: "system",
          content: "你是一个能够生动模拟多角色心理的编剧AI。",
        },
        { role: "user", content: userPrompt },
      ],
      null,
      (reply) => {
        try {
          const cleanJson = reply.replace(/```json|```/g, "").trim();
          const data = JSON.parse(cleanJson);

          // 整理数据用于渲染
          const reactionList = data.map((item) => {
            // 找回原始头像颜色
            const originalChar = recommendations.find(
              (r) => r.char.name === item.charName,
            )?.char;
            return {
              charName: item.charName,
              content: item.content,
              isWinner: item.charName === winnersName,
              avatarColor: originalChar ? originalChar.avatarColor : "#ccc",
            };
          });

          setReactions(reactionList);
          setStatus("viewing_reactions");
        } catch (e) {
          // 兜底：直接跳转，不显示反应
          onConfirm(rec.book);
        }
      },
      () => onConfirm(rec.book), // 错误则直接跳转
    );
  };

  const handleClose = () => {
    setIsOpen(false);
    setStatus("idle");
  };

  return (
    <>
      <div className="ai-rec-fab" onClick={handleTrigger}>
        <i data-lucide="sparkles" style={{ width: 24, height: 24 }}></i>
      </div>

      {isOpen && (
        <div
          className="weather-modal-mask"
          onClick={handleClose}
          style={{ background: "rgba(255, 253, 249, 0.95)" }}
        >
          <div
            className="weather-modal-box"
            onClick={(e) => e.stopPropagation()}
            style={{ background: "#fffdf9" }}
          >
            {/* 标题 */}
            <div className="wm-title">
              {status === "loading_recs" && "正在召开读书选品会..."}
              {status === "selecting" && "谁的推荐更合你意？"}
              {status === "loading_reactions" && "正在观察大家的反应..."}
              {status === "viewing_reactions" && "大家的反应"}
            </div>

            {/* Loading 状态 */}
            {(status === "loading_recs" || status === "loading_reactions") && (
              <div
                style={{
                  textAlign: "center",
                  padding: "30px",
                  color: "#999",
                }}
              >
                <i
                  data-lucide="loader-2"
                  className="animate-spin"
                  style={{
                    width: 32,
                    height: 32,
                    animation: "spin 1s linear infinite",
                    margin: "0 auto 10px",
                  }}
                ></i>
                <div>
                  {status === "loading_recs"
                    ? "角色们正在争论..."
                    : "有人欢喜有人忧..."}
                </div>
              </div>
            )}

            {/* 阶段一：选择推荐 */}
            {status === "selecting" && (
              <div className="rec-list-container no-scrollbar">
                {recommendations.map((rec, idx) => (
                  <div
                    key={idx}
                    className="rec-card-item"
                    onClick={() => handleSelectRec(rec)}
                  >
                    <div className="rec-card-header">
                      <div
                        className="rec-card-avatar"
                        style={{ background: rec.char.avatarColor }}
                      >
                        {rec.char.name[0]}
                      </div>
                      <span
                        style={{
                          fontWeight: "bold",
                          fontSize: "14px",
                          color: "#333",
                        }}
                      >
                        {rec.char.name}
                      </span>
                    </div>
                    <div className="rec-reason">“{rec.reason}”</div>
                    <div className="rec-book-mini">
                      <div
                        style={{
                          width: 24,
                          height: 32,
                          background: rec.book.color,
                          borderRadius: 4,
                        }}
                      ></div>
                      <div style={{ fontSize: "13px", fontWeight: "500" }}>
                        {rec.book.title}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}

            {/* 阶段二：查看反应 */}
            {status === "viewing_reactions" && (
              <>
                <div className="reaction-container no-scrollbar">
                  {reactions.map((r, idx) => (
                    <div key={idx} className="reaction-bubble">
                      <div
                        className="rec-card-avatar"
                        style={{
                          background: r.avatarColor,
                          minWidth: 32,
                        }}
                      >
                        {r.charName[0]}
                      </div>
                      <div
                        className={`reaction-content ${
                          r.isWinner ? "winner" : "loser"
                        }`}
                      >
                        {r.content}
                        {r.isWinner && (
                          <div
                            style={{
                              position: "absolute",
                              top: -8,
                              right: -8,
                              fontSize: "16px",
                            }}
                          >
                            💖
                          </div>
                        )}
                        {!r.isWinner && (
                          <div
                            style={{
                              position: "absolute",
                              top: -8,
                              right: -8,
                              fontSize: "16px",
                            }}
                          >
                            💔
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
                <button
                  className="go-read-btn"
                  onClick={() => {
                    handleClose();
                    onConfirm(selectedRec.book);
                  }}
                >
                  开始共读《{selectedRec.book.title}》
                </button>
              </>
            )}

            {/* 关闭按钮 */}
            <div className="wm-close" onClick={handleClose}>
              <i data-lucide="x"></i>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

// ==================== [新增] 长期记忆设置组件 ====================
// ==================== [新增/修改] 长期记忆设置组件 ====================
const LongTermMemoryPage = () => {
  const { useState, useEffect } = React;

  // 默认设置
  const [memoryConfig, setMemoryConfig] = useState({
    globalMemoryDays: 30,
    contextLimit: 20,
    memories: [], // 存储整合后的记忆
  });

  const [editingMemoryId, setEditingMemoryId] = useState(null);
  // --- 新增控制展开折叠的状态 ---
  const [expandedMemoryId, setExpandedMemoryId] = useState(null);

  const [editTitle, setEditTitle] = useState("");
  const [editContent, setEditContent] = useState("");

  // 加载配置
  useEffect(() => {
    const saved = localStorage.getItem("t8_memory_config");
    if (saved) {
      setMemoryConfig(JSON.parse(saved));
    }
  }, []);

  // 保存配置
  const saveConfig = (newConfig) => {
    setMemoryConfig(newConfig);
    localStorage.setItem("t8_memory_config", JSON.stringify(newConfig));
  };

  // 删除记忆
  const deleteMemory = (id) => {
    if (confirm("确定要删除这条核心记忆吗？")) {
      const newMemories = (memoryConfig.memories || []).filter(
        (m) => m.id !== id,
      );
      saveConfig({ ...memoryConfig, memories: newMemories });
    }
  };

  // 开启编辑
  const startEditMemory = (mem) => {
    setEditingMemoryId(mem.id);
    setEditTitle(mem.title);
    setEditContent(mem.content);
  };

  // 保存编辑
  const saveEditMemory = () => {
    if (!editTitle.trim()) return alert("标题不能为空");
    const newMemories = (memoryConfig.memories || []).map((m) =>
      m.id === editingMemoryId
        ? { ...m, title: editTitle, content: editContent }
        : m,
    );
    saveConfig({ ...memoryConfig, memories: newMemories });
    setEditingMemoryId(null);
  };

  return (
    <div
      style={{
        flex: 1,
        overflowY: "auto",
        padding: "20px",
        background: "#f5f6f8",
      }}
    >
      {/* 1. 全局记忆天数 */}
      <div className="wb-card">
        <div className="wb-header">
          <div className="wb-title">全局记忆范围</div>
          <span
            style={{
              fontSize: "14px",
              color: "#4A90E2",
              fontWeight: "bold",
            }}
          >
            {memoryConfig.globalMemoryDays} 天
          </span>
        </div>
        <div className="wb-content" style={{ marginBottom: "16px" }}>
          AI 将会检索并参考最近多少天内的对话内容。
        </div>
        <input
          type="range"
          min="1"
          max="365"
          value={memoryConfig.globalMemoryDays}
          onChange={(e) =>
            saveConfig({
              ...memoryConfig,
              globalMemoryDays: Number(e.target.value),
            })
          }
          className="reader-slider"
          style={{ width: "100%", margin: 0 }}
        />
      </div>

      {/* 2. 上下文记忆条目 */}
      <div className="wb-card">
        <div className="wb-header">
          <div className="wb-title">上下文携带条数</div>
          <span
            style={{
              fontSize: "14px",
              color: "#4A90E2",
              fontWeight: "bold",
            }}
          >
            {memoryConfig.contextLimit} 条
          </span>
        </div>
        <div className="wb-content" style={{ marginBottom: "16px" }}>
          每次对话发送给 AI 的历史消息数量。条数越多记忆越连贯，但消耗 Token
          越多。
        </div>
        <input
          type="range"
          min="5"
          max="100"
          value={memoryConfig.contextLimit}
          onChange={(e) =>
            saveConfig({
              ...memoryConfig,
              contextLimit: Number(e.target.value),
            })
          }
          className="reader-slider"
          style={{ width: "100%", margin: 0 }}
        />
      </div>

      {/* 3. 核心记忆摘要列表 */}
      <div
        className="wb-card"
        style={{ border: "2px solid #E8C3A8", padding: "20px" }}
      >
        <div
          style={{
            marginBottom: "16px",
            borderBottom: "1px dashed #eee",
            paddingBottom: "10px",
          }}
        >
          <div
            style={{
              color: "#D49A6A",
              fontSize: "16px",
              fontWeight: "bold",
            }}
          >
            核心记忆卷宗
          </div>
          <div style={{ fontSize: "12px", color: "#999", marginTop: "4px" }}>
            通过传讯页多选消息[整合]生成，AI 会永远铭记这些设定。
          </div>
        </div>

        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "12px",
          }}
        >
          {!memoryConfig.memories || memoryConfig.memories.length === 0 ? (
            <div
              style={{
                textAlign: "center",
                color: "#ccc",
                padding: "20px 0",
                fontSize: "13px",
              }}
            >
              卷宗空空如也...
              <br />
              快去传讯长按多选消息生成吧。
            </div>
          ) : (
            memoryConfig.memories.map((mem) => (
              <div
                key={mem.id}
                style={{
                  background: "#FDFCF8",
                  border: "1px solid #EAEAEA",
                  borderRadius: "12px",
                  padding: "16px",
                  cursor: "pointer",
                  transition: "all 0.2s",
                }}
                onClick={() => {
                  if (expandedMemoryId !== mem.id) {
                    setExpandedMemoryId(mem.id);
                    setEditTitle(mem.title);
                    setEditContent(mem.content);
                  }
                }}
              >
                <div
                  style={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                  }}
                >
                  <div
                    style={{
                      fontWeight: "bold",
                      color: "#D6724B",
                      fontSize: "15px",
                    }}
                  >
                    {mem.title}
                  </div>
                  <div
                    style={{
                      display: "flex",
                      gap: "12px",
                      alignItems: "center",
                    }}
                  >
                    <i
                      onClick={(e) => {
                        e.stopPropagation();
                        deleteMemory(mem.id);
                      }}
                      className="ph-bold ph-trash"
                      style={{
                        fontSize: "16px",
                        color: "#ff6b6b",
                        cursor: "pointer",
                      }}
                    ></i>
                    <i
                      className={
                        expandedMemoryId === mem.id
                          ? "ph-bold ph-caret-up"
                          : "ph-bold ph-caret-down"
                      }
                      style={{ fontSize: "16px", color: "#8C917B" }}
                    ></i>
                  </div>
                </div>

                {expandedMemoryId === mem.id && (
                  <div
                    style={{
                      marginTop: "16px",
                      paddingTop: "16px",
                      borderTop: "1px dashed #eee",
                      display: "flex",
                      flexDirection: "column",
                      gap: "10px",
                    }}
                    onClick={(e) => e.stopPropagation()}
                  >
                    <input
                      value={editTitle}
                      onChange={(e) => setEditTitle(e.target.value)}
                      style={{
                        width: "100%",
                        padding: "10px",
                        borderRadius: "8px",
                        border: "1px solid #D6724B",
                        outline: "none",
                        fontSize: "14px",
                        fontWeight: "bold",
                        color: "#5a5f4d",
                        background: "#fff",
                      }}
                      placeholder="核心要义（标题）"
                    />
                    <textarea
                      value={editContent}
                      onChange={(e) => setEditContent(e.target.value)}
                      style={{
                        width: "100%",
                        height: "120px",
                        padding: "10px",
                        borderRadius: "8px",
                        border: "1px solid #D6724B",
                        outline: "none",
                        fontSize: "13px",
                        color: "#666",
                        resize: "none",
                        lineHeight: "1.5",
                        background: "#fff",
                      }}
                      placeholder="记忆内容..."
                    />
                    <div
                      style={{
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                        marginTop: "4px",
                      }}
                    >
                      <span style={{ fontSize: "10px", color: "#ccc" }}>
                        创建于 {mem.timestamp}
                      </span>
                      <div style={{ display: "flex", gap: "8px" }}>
                        <button
                          onClick={() => setExpandedMemoryId(null)}
                          style={{
                            background: "#f5f5f5",
                            border: "none",
                            padding: "8px 16px",
                            borderRadius: "8px",
                            color: "#666",
                            cursor: "pointer",
                            fontSize: "12px",
                            fontWeight: "bold",
                          }}
                        >
                          收起
                        </button>
                        <button
                          onClick={() => {
                            if (!editTitle.trim()) return alert("标题不能为空");
                            const newMemories = (
                              memoryConfig.memories || []
                            ).map((m) =>
                              m.id === mem.id
                                ? {
                                    ...m,
                                    title: editTitle,
                                    content: editContent,
                                  }
                                : m,
                            );
                            saveConfig({
                              ...memoryConfig,
                              memories: newMemories,
                            });
                            setExpandedMemoryId(null);
                            alert("保存成功！");
                          }}
                          style={{
                            background:
                              "linear-gradient(135deg, #D6724B 0%, #C95E36 100%)",
                            border: "none",
                            padding: "8px 16px",
                            borderRadius: "8px",
                            color: "#fff",
                            cursor: "pointer",
                            fontSize: "12px",
                            fontWeight: "bold",
                            boxShadow: "0 2px 8px rgba(214,114,75,0.3)",
                          }}
                        >
                          保存修改
                        </button>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            ))
          )}
        </div>
      </div>

      <div
        style={{
          textAlign: "center",
          marginTop: "30px",
          color: "#ccc",
          fontSize: "12px",
        }}
      >
        所有设置即时保存，将在下一次对话中生效。
      </div>
    </div>
  );
};

