// ==================== [新增] 字体设置页面组件 ====================

const FontSettingsPage = ({ onClose }) => {
  const [fontUrl, setFontUrl] = React.useState("");

  // 莫兰迪色系样式配置
  const styles = {
    container: {
      position: "absolute",
      top: 0,
      left: 0,
      width: "100%",
      height: "100%",
      background: "#F9F7F5",
      zIndex: 205,
      display: "flex",
      flexDirection: "column",
    },
    content: { flex: 1, padding: "24px", overflowY: "auto" },
    card: {
      background: "#FFFFFF",
      borderRadius: "20px",
      padding: "24px",
      boxShadow: "0 8px 24px rgba(163, 177, 164, 0.1)",
      marginBottom: "24px",
    },
    label: {
      fontSize: "14px",
      color: "#8C917B",
      marginBottom: "8px",
      display: "block",
      fontWeight: "500",
    },
    input: {
      width: "100%",
      padding: "14px",
      borderRadius: "12px",
      border: "1px solid #EAEAEA",
      background: "#FCFAFA",
      color: "#5A5F4D",
      fontSize: "14px",
      outline: "none",
      transition: "all 0.3s",
    },
    previewBox: {
      marginTop: "16px",
      padding: "20px",
      background: "#F2EFDE",
      borderRadius: "16px",
      color: "#5A5F4D",
      lineHeight: "1.6",
      fontSize: "18px",
      minHeight: "100px",
      fontFamily: fontUrl ? "CustomUserFontPreview" : "inherit",
      border: "1px dashed #C9C9C1",
      transition: "font-family 0.3s",
    },
    btnPrimary: {
      width: "100%",
      padding: "16px",
      borderRadius: "24px",
      border: "none",
      background: "linear-gradient(135deg, #A8C8BA 0%, #8FA99D 100%)",
      color: "#FFFFFF",
      fontSize: "16px",
      fontWeight: "bold",
      cursor: "pointer",
      boxShadow: "0 4px 12px rgba(168, 200, 186, 0.4)",
      marginTop: "30px",
    },
    btnReset: {
      width: "100%",
      padding: "16px",
      borderRadius: "24px",
      border: "1px solid #E0E0E0",
      background: "#FFFFFF",
      color: "#999",
      fontSize: "14px",
      cursor: "pointer",
      marginTop: "12px",
    },
  };

  // 初始化加载本地存储的URL
  React.useEffect(() => {
    const savedUrl = localStorage.getItem("custom_font_url");
    if (savedUrl) setFontUrl(savedUrl);
  }, []);

  // 动态注入预览字体样式 (仅用于当前预览框，不影响全局)
  React.useEffect(() => {
    if (!fontUrl) return;
    const styleId = "font-preview-style";
    let styleTag = document.getElementById(styleId);
    if (!styleTag) {
      styleTag = document.createElement("style");
      styleTag.id = styleId;
      document.head.appendChild(styleTag);
    }
    // 使用唯一的 font-family 名称避免冲突
    styleTag.textContent = `
                                                                                                                               @font-face {
                                                                                                                                 font-family: 'CustomUserFontPreview';
                                                                                                                                 src: url('${fontUrl}');
                                                                                                                                 font-display: swap;
                                                                                                                               }
                                                                                                                             `;
  }, [fontUrl]);

  const handleApply = () => {
    if (!fontUrl.trim()) return alert("请输入字体URL");

    // 注入全局样式
    const styleId = "global-custom-font";
    let styleTag = document.getElementById(styleId);
    if (!styleTag) {
      styleTag = document.createElement("style");
      styleTag.id = styleId;
      document.head.appendChild(styleTag);
    }
    styleTag.textContent = `
                                                                                                                               @font-face {
                                                                                                                                 font-family: 'GlobalUserFont';
                                                                                                                                 src: url('${fontUrl}');
                                                                                                                                 font-display: swap;
                                                                                                                               }
                                                                                                                               /* 终极全局字体应用，利用 :not 排除所有图标组件，防止图标变成文字 */
                                                                                                                               *:not(.material-symbols-outlined):not([class*="ph-"]):not(iconify-icon) {
                                                                                                                                 font-family: 'GlobalUserFont', "Quicksand", "Noto Sans SC", sans-serif !important;
                                                                                                                               }
                                                                                                                             `;

    localStorage.setItem("custom_font_url", fontUrl);
    alert("字体已成功应用到全局！");
    onClose();
  };

  const handleReset = () => {
    localStorage.removeItem("custom_font_url");
    const styleTag = document.getElementById("global-custom-font");
    if (styleTag) styleTag.remove();
    setFontUrl("");
    alert("已恢复默认字体");
  };

  return (
    <div className={`settings-overlay open`} style={styles.container}>
      <div className="settings-nav">
        <div className="back-btn" onClick={onClose}>
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="m15 18-6-6 6-6" />
          </svg>
        </div>
        <div className="title">字体设置</div>
      </div>
      <div className="no-scrollbar" style={styles.content}>
        <div style={styles.card}>
          <label style={styles.label}>字体文件 URL (WOFF2/TTF)</label>
          <input
            style={styles.input}
            value={fontUrl}
            onChange={(e) => setFontUrl(e.target.value)}
            placeholder="例如： `https://example.com/font.woff2` "
          />
          <div
            style={{
              fontSize: "12px",
              color: "#B0B0B0",
              marginTop: "8px",
              lineHeight: "1.4",
            }}
          >
            * 推荐使用直链，支持 .ttf, .woff2 格式。
            <br />* 部分字体可能因跨域限制无法加载。
          </div>
        </div>

        <div style={styles.card}>
          <label style={styles.label}>效果预览</label>
          <div style={styles.previewBox}>
            有女青史无名姓，一笔胭脂开眉弓。
            <br />
            Watermelon is great！！.
            <br />
            1234567890
          </div>
        </div>

        <button style={styles.btnPrimary} onClick={handleApply}>
          立即应用
        </button>
        <button style={styles.btnReset} onClick={handleReset}>
          恢复默认
        </button>
      </div>
    </div>
  );
};

// ==================== [新增] IndexedDB 存储管理器 ====================

class IndexedDBManager {
  constructor() {
    this.dbName = "AppStorage";
    this.dbVersion = 1;
    this.db = null;
  }

  // 打开数据库连接
  async open() {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(this.dbName, this.dbVersion);

      request.onerror = () => reject("Failed to open IndexedDB");

      request.onsuccess = () => {
        this.db = request.result;
        resolve(this.db);
      };

      request.onupgradeneeded = (event) => {
        const db = event.target.result;

        // 创建存储对象
        if (!db.objectStoreNames.contains("settings")) {
          db.createObjectStore("settings", { keyPath: "id" });
        }
      };
    });
  }

  // 存储数据
  async set(key, value) {
    if (!this.db) await this.open();

    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction(["settings"], "readwrite");
      const store = transaction.objectStore("settings");

      const request = store.put({ id: key, value });
      request.onsuccess = () => resolve();
      request.onerror = () => reject("Failed to save data");
    });
  }

  // 读取数据
  async get(key) {
    if (!this.db) await this.open();

    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction(["settings"], "readonly");
      const store = transaction.objectStore("settings");

      const request = store.get(key);
      request.onsuccess = () =>
        resolve(request.result ? request.result.value : null);
      request.onerror = () => reject("Failed to read data");
    });
  }

  // 删除数据
  async remove(key) {
    if (!this.db) await this.open();

    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction(["settings"], "readwrite");
      const store = transaction.objectStore("settings");

      const request = store.delete(key);
      request.onsuccess = () => resolve();
      request.onerror = () => reject("Failed to delete data");
    });
  }
}

// 创建全局实例
const dbManager = new IndexedDBManager();

