  const [isMemoryOpen, setIsMemoryOpen] = useState(false);
  // [新增] 煎药台页面状态
  const [isDecoctionOpen, setIsDecoctionOpen] = useState(false);
  // [新增] 字体设置页面状态
  const [isFontSettingsOpen, setIsFontSettingsOpen] = useState(false);

  // [新增] Minimax 配置页面状态
  const [isMinimaxSettingsOpen, setIsMinimaxSettingsOpen] = useState(false);

  // [新增] 隐私与安全二级页面状态
  const [isPrivacySecurityOpen, setIsPrivacySecurityOpen] = useState(false);

  // [ADD] 新增用户配置状态
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [currentUser, setCurrentUser] = useState({
    name: "用户名",
    age: "未知",
    avatar: null,
  });

  // [新增] 天下书城相关状态
  const [storeRecommendBooks, setStoreRecommendBooks] = useState([]);
  const [storePopularBooks, setStorePopularBooks] = useState([]);
  const [isGeneratingRecommend, setIsGeneratingRecommend] = useState(false);
  const [isGeneratingPopular, setIsGeneratingPopular] = useState(false);
  const [isGeneratingMoreContent, setIsGeneratingMoreContent] = useState(false);

  // [新增] 书城每周打卡状态
  const [readerWeeklyPunch, setReaderWeeklyPunch] = useState([]);

  // [新增] 初始化读取书城缓存与打卡记录
  React.useEffect(() => {
    const savedRec = localStorage.getItem("store_recommend_books");
    const savedPop = localStorage.getItem("store_popular_books");
    const savedPunch = localStorage.getItem("reader_weekly_punch");
    if (savedRec) setStoreRecommendBooks(JSON.parse(savedRec));
    if (savedPop) setStorePopularBooks(JSON.parse(savedPop));
    if (savedPunch) setReaderWeeklyPunch(JSON.parse(savedPunch));
  }, []);

  // [新增] 书城阅读打卡逻辑
  const handleReaderWeeklyPunch = (dayIndex) => {
    const today = new Date();
    let currentDayIndex = today.getDay();
    if (currentDayIndex === 0) currentDayIndex = 7; // 周日转为7

    if (dayIndex !== currentDayIndex) {
      alert("只能在当天的方块进行打卡哦！");
      return;
    }

    const dateStr = today.toLocaleDateString();
    if (readerWeeklyPunch.includes(dateStr)) {
      alert("今天已经打过卡啦，明天继续加油！");
      return;
    }

    const newPunch = [...readerWeeklyPunch, dateStr];
    setReaderWeeklyPunch(newPunch);
    localStorage.setItem("reader_weekly_punch", JSON.stringify(newPunch));
    alert("今日阅读打卡成功！书香伴你每一天。");
  };

  // [新增] 将书城书籍加入书架的逻辑
  const handleAddToBookshelf = async (bookToAdd) => {
    if (books.some((b) => b.id === bookToAdd.id)) {
      alert("该书已经在今日阅读的书架上了！");
      return;
    }
    // 构建本地书籍对象
    const newLocalBook = {
      id: bookToAdd.id,
      title: bookToAdd.title,
      author: bookToAdd.author,
      summary: bookToAdd.summary,
      progress: 0,
      color: bookToAdd.color,
      fullText: bookToAdd.fullText,
    };

    const updatedBooks = [newLocalBook, ...books];
    setBooks(updatedBooks);

    // 持久化保存到数据库或localStorage
    if (window.bookStore) {
      await window.bookStore.save(newLocalBook);
      await window.bookStore.saveContent(newLocalBook.id, bookToAdd.fullText);
    } else {
      localStorage.setItem("morandi_books_meta", JSON.stringify(updatedBooks));
      localStorage.setItem(
        `book_content_${newLocalBook.id}`,
        bookToAdd.fullText,
      );
    }
    alert("成功加入今日阅读书架！");
  };

  // [新增] 生成书城书籍
  const handleGenerateBookstore = async (type) => {
    const isRecommend = type === "recommend";
    const setBooksState = isRecommend
      ? setStoreRecommendBooks
      : setStorePopularBooks;
    const setLoadingState = isRecommend
      ? setIsGeneratingRecommend
      : setIsGeneratingPopular;

    if (isRecommend && isGeneratingRecommend) return;
    if (!isRecommend && isGeneratingPopular) return;

    setLoadingState(true);

    try {
      const worldContext = window.getWorldBookContext
        ? await window.getWorldBookContext()
        : "无特定背景设定";

      const sysPrompt =
        "你是一个深谙东汉背景的藏书阁管理员，可以根据要求提供各种东汉背景下的书籍信息。";
      const userPrompt = `
                    【世界设定】
                    ${worldContext}

                    【任务】
                    请为书架生成 5 本截然不同的东汉背景书籍。

                    【要求】
                    1. 书籍品类应丰富多样：${isRecommend ? "小说，散文，传记，奇闻异事，文学等" : "心理，悬疑推理，宗教，医学，艺术，军事等"}。
                    2. 文风多样，根据作者人设不同而不同（可搞笑无厘头，也可严肃）。
                    3. 无论如何不要脱离东汉背景。
                    4. 严格返回纯 JSON 数组格式，不要包含任何 Markdown 标记（如 \`\`\`json ），直接以 [ 开头，] 结尾。

                    【JSON 格式示例】
                    [
                      {
                        "id": "唯一ID字符串",
                        "title": "书名",
                        "author": "作者名字",
                        "summary": "简短的简介，20字左右",
                        "color": "#A8C8BA",
                        "category": "分类"
                      }
                    ]
                  `;

      if (window.sendToLLM) {
        window.sendToLLM(
          [
            { role: "system", content: sysPrompt },
            { role: "user", content: userPrompt },
          ],
          null,
          (reply) => {
            try {
              const cleanJson = reply.replace(/```json|```/g, "").trim();
              const data = JSON.parse(cleanJson);
              if (Array.isArray(data)) {
                const fallbackColors = [
                  "#8C9DB0",
                  "#A67B7B",
                  "#C9D6C8",
                  "#B4C7E7",
                  "#D4AB90",
                ];
                const formattedData = data.map((b, idx) => ({
                  ...b,
                  id: b.id || Date.now() + idx.toString(),
                  isStoreBook: true,
                  fullText: "",
                  progress: 0,
                  color: b.color || fallbackColors[idx % fallbackColors.length],
                }));
                setBooksState(formattedData);
                // 保存到本地缓存
                localStorage.setItem(
                  isRecommend ? "store_recommend_books" : "store_popular_books",
                  JSON.stringify(formattedData),
                );
              }
            } catch (e) {
              console.error("生成书籍失败:", e, reply);
              alert("书籍整理失败，请重试。");
            } finally {
              setLoadingState(false);
            }
          },
          (err) => {
            console.error("API请求失败:", err);
            setLoadingState(false);
            alert("请求失败，请检查API配置");
          },
        );
      } else {
        alert("未配置 API！");
        setLoadingState(false);
      }
    } catch (e) {
      console.error(e);
      setLoadingState(false);
    }
  };

  // [新增] 打开书城书籍并生成初次内容
  const handleOpenStoreBook = async (book) => {
    // 如果已经有内容，直接打开
    if (book.fullText) {
      setCurrentReadingBook(book);
      setIsReadingDetailOpen(true);
      return;
    }

    setIsGeneratingMoreContent(true);
    try {
      const worldContext = window.getWorldBookContext
        ? await window.getWorldBookContext()
        : "无特定背景设定";

      const sysPrompt = "你是一位东汉时期的著书人，擅长撰写各种风格的文章。";
      const userPrompt = `
                    【世界设定】
                    ${worldContext}

                    【书籍信息】
                    书名：${book.title}
                    作者：${book.author}
                    分类：${book.category}
                    简介：${book.summary}

                    【任务】
                    请根据以上信息，为这本书撰写开头部分（约800-1000字，足够分成两页阅读）。

                    【要求】
                    1. 文风要符合作者人设和分类，可搞笑无厘头也可严肃。
                    2. 绝对不能脱离东汉背景，不要出现现代违和词汇。
                    3. 结构连贯，引人入胜。
                    4. 直接输出文章正文文本，绝对不要输出任何额外的提示语、开场白、结语或Markdown标记。
                  `;

      if (window.sendToLLM) {
        window.sendToLLM(
          [
            { role: "system", content: sysPrompt },
            { role: "user", content: userPrompt },
          ],
          null,
          (reply) => {
            const content = reply.replace(/```[a-z]*|```/gi, "").trim();
            const newBook = { ...book, fullText: content };

            // 更新书架状态
            setStoreRecommendBooks((prev) =>
              prev.map((b) => (b.id === book.id ? newBook : b)),
            );
            setStorePopularBooks((prev) =>
              prev.map((b) => (b.id === book.id ? newBook : b)),
            );

            setCurrentReadingBook(newBook);
            setIsReadingDetailOpen(true);
            setIsGeneratingMoreContent(false);
          },
          (err) => {
            console.error(err);
            alert("获取书籍内容失败");
            setIsGeneratingMoreContent(false);
          },
        );
      }
    } catch (e) {
      console.error(e);
      setIsGeneratingMoreContent(false);
    }
  };

