                    <span
                      style={{
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                      }}
                    >
                      <i
                        data-lucide={item.icon}
                        style={{
                          width: 22,
                          height: 22,
                          stroke: "#6d735b",
                        }}
                      ></i>
                    </span>
